quests[29165] = { id = 29165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf des Rudels", description = "<Matookla fährt fort:>\n\nDas östlichste Flammenportal ist das Reich von Lylagar. Stellt Euch vor das Portal und stoßt ein herausforderndes Geheul aus. Zwingt dann die Bestie dazu, sich zu ergeben.", sourceObjective = "Benutzt den Fangzahn des Wolfs, um Lylagar zu beschwören und besiegt ihn.", completion = "Ich habe die Echos Eurer triumphierenden Schreie über die Bergfelsen hinweg gehört.\n\nIch habe auch gehört wie Lylagar eine... andere Art von Schrei von sich gegeben hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[29166] = { id = 29166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachschub für die andere Seite", description = "Eine der größten Gefahren, denen sich unsere Druiden innerhalb der Feuerlande stellen müssen, ist profanes Austrocknen. Unsere Proviantmeister verbringen sehr viel Zeit damit, die Feldflaschen für die Truppen auf der anderen Seite herzurichten. Wir haben allerdings andere Methoden.\n\nIm grüneren Dickicht im Osten solltet Ihr noch immer einige Blauknollenwinden finden, die noch nicht verbrannt wurden. Diese Pflanzen haben einen enormen Wasseranteil in ihren Wurzeln - und bieten dem müden Soldaten einiges an Energie.", sourceObjective = "Sammelt 7 Blauknollenwinden.", progress = "Dann wollen wir mal sehen... wie viele habt Ihr denn bisher sammeln können?", completion = "Ich werde diese hier sofort verpacken und verschicken lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29167] = { id = 29167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bansheekönigin", description = "Fürstin Sylvanas soll eine der besten Kämpferinnen der Horde sein. Vielleicht ist sie ja deswegen Kriegshäuptling!\n\nIch wollte sie schon immer mal treffen, {name}. Vielleicht kann ja <ein Abenteurer/eine Abenteuerin> wie Ihr eine Audienz bei ihr bekommen! Würdet Ihr mich zum Königsviertel von Unterstadt bringen, damit ich Fürstin Sylvanas treffen kann? Das ist ganz schön weit weg und die Wachen würden mich nie allein reinlassen!", sourceObjective = "Bringt Euer Waisenkind ins Königsviertel von Unterstadt und besucht Fürstin Sylvanas Windläufer. Wenn Euer Waisenkind nicht bei Euch ist, wenn Ihr ankommt, solltet Ihr es herbeirufen.", progress = "Die Kinderwoche ist die einzige Zeit im Jahr, zu der ich aus dem Waisenhaus oder aus Orgrimmar herauskomme.", completion = "Sie ist genauso grimmig, wie ich sie mir vorgestellt hatte! Aber dieser Botschafter ist ganz schön wütend geworden, als ich mit Fürstin Sylvanas gesprochen habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[29168] = { id = 29168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sekundärziele", description = "Die Gurubashitrolle haben ihre mächtigsten Verbündeten zusammengerufen, um Zul'Gurub wiederaufzubauen und das Schlingendorntal zurückzuerobern.\n\nDie mächtigsten unter diesen Verbündeten sind zwei monströse Trolle, Kaulema der Beweger und Mor'Lek der Zerleger, sowie ein gefährlicher Seelendieb namens Mortaxx.\n\nSie sind zwar nicht die Befehlshaber in Zul'Gurub, aber diese mächtigen Diener zu besiegen wird dafür sorgen, dass die Gurubashi so schnell nicht an die Macht kommen.", sourceObjective = "Tötet Kaulema den Beweger, Mor'Lek den Zerleger und Mortaxx, das Schlagen der Stunde in Zul'Gurub.", sourceObjectiveStatus = "unverified-source-field" }
quests[29169] = { id = 29169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tiere im Inneren", description = "<Maywiki ist unruhig.>\n\nNach dem Fall Hakkars ist die Stadt der Gurubashi immer mehr verfallen und der Dschungel hat Zul'Gurub Stück für Stück zurückerobert. In den Schlupfwinkeln der alten Stadt leben jetzt einige mächtige Tiere.\n\nWir haben gesehen, welche Mächte die Gurubashipriester befehligen - mit ihren giftigen Gebräuen bringen sie sogar die Flora gegen uns auf. Bitte Ihr Helden, beseitigt diese Tiere bevor Jin'do und seine Handlanger sie zu ihren willenlosen Dienern machen!", sourceObjective = "Tötet die Blütenflügelschwarmkönigin, Tor-Tun den Schläfer sowie einen von Gahz'rankas verlorenem Nachwuchs in Zul'Gurub.", sourceObjectiveStatus = "unverified-source-field" }
quests[29170] = { id = 29170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo sind wir hier?", description = "<Finkles Helm versetzt Euch einen kleinen Schlag.>\n\nWas ist das für ein Ort? Es sieht so aus, als ob sie mit diesem Nethergroßdrachen etwas Schreckliches anstellen. Die Energie wird von dem Geschöpf auf die Frau übertragen! Wir müssen dieses Ritual unterbrechen!\n\nTötet Corla, um die Halle durchqueren zu können!", sourceObjective = "Tötet Corla, Botin des Zwielichts.", sourceObjectiveStatus = "unverified-source-field" }
quests[29171] = { id = 29171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo sind wir hier?", description = "<Finkles Helm versetzt Euch einen kleinen Schlag.>\n\nWas ist das für ein Ort? Es sieht so aus, als ob sie mit diesem Nethergroßdrachen etwas Schreckliches anstellen. Die Energie wird von dem Geschöpf auf die Frau übertragen! Wir müssen dieses Ritual unterbrechen!\n\nTötet Corla, um die Halle durchqueren zu können!", sourceObjective = "Tötet Corla, Botin des Zwielichts.", sourceObjectiveStatus = "unverified-source-field" }
quests[29172] = { id = 29172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tiere im Inneren", description = "<Blutschlächterin T'ara beäugt Euch einen Moment lang.>\n\nNach dem Fall Hakkars is' die Stadt der Gurubashi immer mehr verfall'n und der Dschungel hat Zul'Gurub Stück für Stück zurückerobert. In den Schlupfwinkeln der alten Stadt leb'n jetzt einige mächtige Tiere.\n\nWir hab'n geseh'n, welche Mächte die Gurubashipriester befehlig'n - mit ihren giftigen Gebräuen bring'n sie sogar die Flora gegen uns auf. Du hältst dich für stark? Dann beseitige diese Tiere, bevor Jin'do und seine Handlanger sie zu ihren willenlosen Dienern mach'n!", sourceObjective = "Tötet die Blütenflügelschwarmkönigin, Tor-Tun den Schläfer sowie einen von Gahz'rankas verlorenem Nachwuchs in Zul'Gurub auf heroischem Schwierigkeitsgrad.", completion = "<T'aras Hauer bewegen sich ein wenig. Ist das ein Lächeln?>\n\nGut gemacht.\n\nWir werd'n heute Nacht ruhig schlaf'n in dem Wissen, dass Jin'do und Zanzil diese mächtigen Tiere nich' dem Willen der Gurubashi unterwerf'n können.", sourceObjectiveStatus = "unverified-source-field" }
quests[29173] = { id = 29173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sekundärziele", description = "Die Gurubashitrolle hab'n ihre mächtigsten Verbündeten zusammengeruf'n, um Zul'Gurub wiederaufzubau'n und das Schlingendorntal zurückzuerobern.\n\nDie mächtigsten unter diesen Verbündeten sind zwei monströse Trolle, Kaulema der Beweger und Mor'Lek der Zerleger, sowie ein gefährlicher Seelendieb namens Mortaxx.\n\nSie sind zwar nich' die Befehlshaber in Zul'Gurub, aber diese mächtigen Diener zu besieg'n wird dafür sorg'n, dass die Gurubashi so schnell nich' an die Macht komm'n.", sourceObjective = "Tötet Kaulema den Beweger, Mor'Lek den Zerleger und Mortaxx, das Schlagen der Stunde in Zul'Gurub auf heroischem Schwierigkeitsgrad.", completion = "Jin'dos Reich bricht um ihn herum in sich zusammen, wie die Ruinen dieser verlassenen Stadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29174] = { id = 29174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brecht ihren Willen", description = "Eine Stadt wie Zul'Gurub ähnelt den mächtigen Bäumen, die Ihr hier in der Umgebung sehen könnt.\n\nDer Stamm mag dick und das Laubdach dicht und üppig sein, aber ohne Nährstoffe aus den Wurzeln muss der Baum welken und umstürzen.\n\nJin'dos Armee wird hauptsächlich durch die Handlungen von zwei niederen Gurubashitrollen versorgt. Wenn Ihr diese Wurzeln durchtrennt, wird die Stadt umso schneller fallen.", sourceObjective = "Tötet Gub und den Meisterkoch der Gurubashi in Zul'Gurub.", sourceObjectiveStatus = "unverified-source-field" }
quests[29175] = { id = 29175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brecht ihren Willen", description = "Eine Stadt wie Zul'Gurub ähnelt den mächtigen Bäumen, die du hier in der Umgebung seh'n kannst.\n\nDer Stamm mag dick und das Laubdach dicht und üppig sein, aber ohne Nährstoffe aus den Wurzeln muss der Baum welk'n und umstürz'n.\n\nJin'dos Armee wird hauptsächlich durch die Handlungen von einer Handvoll niederer Gurubashitrolle versorgt. Wenn du diese Wurzeln durchtrennst, wird die Stadt umso schneller fall'n.", sourceObjective = "Tötet Gub und den Meisterkoch der Gurubashi in Zul'Gurub auf heroischem Schwierigkeitsgrad.", completion = "Das große Reich der Gurubashi fängt bereits an, zu vergeh'n.\n\nJetzt is' es nur noch eine Frage der Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[29176] = { id = 29176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gefallene Häuptling", description = "Matrone Schlachterbe sagt, dass die Horde eine 'Stimme der Weisheit' mit Cairne Bluthufs Tod verloren hat. Ich weiß nicht, was das heißt, aber ich wollte ihn schon immer mal treffen. Einige der anderen Waisenkinder haben sogar seinen Hufabdruck.\n\nNehmt Ihr mich nach Mulgore mit? Unser Lehrer sagt, die Tauren bringen ihre Toten zu einem Ort, den sie die Teufelsfelsen nennen, und dort verehren sie sie. Lasst uns dorthin gehen und sehen, ob wir Cairne finden.", sourceObjective = "Besucht die Teufelsfelsen mit Eurem Waisenkind, um Cairne Bluthufs Scheiterhaufen zu sehen. Wenn Euer Waisenkind nicht bei Euch ist, wenn Ihr ankommt, solltet Ihr es herbeirufen.", progress = "Ich möchte öfter Mulgore besuchen.", completion = "Eines Tages werde ich auch so toll kämpfen können wie Cairne oder der Kriegshäuptling. Alle werden sich an meine Taten erinnern und die Geister werden auch meine Seele in ihre Reihen aufnehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29177] = { id = 29177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geflügelte Wachsamkeit", description = "Die Agenten des Zwielichts setzen ihren Angriff innerhalb dieses Kessels in den Feuerlanden fort. Wir dürfen nicht in unserer Offensive nachlassen! Schwingt Euch in die Lüfte und vernichtet so viele der Tjoster, wie Ihr könnt!\n\nVergesst nicht, Euch zunächst mit einer Lanze auszurüsten.", sourceObjective = "Legt eine Zwielichtfeuerlanze an und fliegt auf Avianas Wächter. Vernichtet 10 Zwielichttjoster, indem Ihr in sie hineinfliegt. Drückt die Taste 'Flattern', damit Euer Reittier mit den Flügeln schlägt!", completion = "Gut gemacht, {class}. Ich hoffe, Ihr vergesst uns hier in der Brutstätte nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[29178] = { id = 29178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, es glitzert!", description = "Nur keine Scheu, <Mann/Süße>! Lass den alten Gaunah mal einen Blick auf deine Klunker werf'n...\n\nHmm. Ja, nich' schlecht, aber das Zeug könnte besser sein. Viel, viel besser.\n\n<Gaunah kommt näher und flüstert.>\n\nSchätze von unermesslichem Wert lass'n sich überall find'n, {name}, man muss nur wiss'n, wo! Heute ist dein Glückstag! Ich kenne da einen Typen, der dir zu mehr Reichtümern verhelf'n kann, als du jemals trag'n könntest.\n\nStatte meinem alten Kumpel Budd in der Nähe von Zul'Aman einen Besuch ab und zeig ihm das hier. Sag ihm, dass der alte Gaunah dich geschickt hat, dann wird er dich bei seinem neuen Projekt mit einsteig'n lass'n.", sourceObjective = "Sprecht mit Budd in den Geisterlanden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29179] = { id = 29179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feindliche Elemente", description = "Die Elementare drängen weiterhin voran und ich erwarte nicht, dass sie bald nachlassen werden.\n\nIhr werdet sie im Norden finden, wo sie sich auf die Aschenfelder ergießen. Dünnt ihre Reihen aus.", sourceObjective = "Tötet 8 verkohlte Soldaten oder Bezwinger.", progress = "Wir können nicht zulassen, dass diese Elementare Boden gutmachen. Es ist unwahrscheinlich, dass sie in ihren Angriffen nachlassen und uns erlauben, ihn zurückzuerobern.", completion = "Wir wissen Eure fortgesetzten Anstrengungen zu schätzen, {class}. Wir werden diesen Krieg gewinnen, solange wir Kämpfer wie Euch an unserer Seite haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[29180] = { id = 29180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versprechen, Versprechen...", description = "Meine Theorien bestätigen die Gerüchte, dass in Zul'Aman sagenhafte Schätze zu finden sind. Das bedeutet Reittiere und Anwesen für alle!\n\nNun ja, eins nach dem anderen. Ihr müsst Euch Euren Anteil natürlich verdienen...\n\nUnsere anfänglichen Bemühungen haben uns hier doch nicht so weit gebracht, wie ich es mir erhofft hatte. Tatsächlich sieht es so aus, dass meine Karte, und die Tagelöhner, denen ich sie geliehen habe, verschwunden sind. Sie sind aufgebrochen, um einen Troll namens Nalorakk zu jagen. Ich kann zwar die Gruppe ersetzen, aber ich brauche diese Karte!\n\nSolltet Ihr diese Aufgabe bewältigen, dann wird man von Euch sagen, dass Ihr derjenige wart, der Budd Winterhäldler geholfen hat, die Geheimnisse von Zul'Aman zu lüften!", sourceObjective = "Sucht auf Hohepriester Nalorakks Terrasse in Zul'Aman nach Budds Karte.", sourceObjectiveStatus = "unverified-source-field" }
quests[29181] = { id = 29181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Druiden der Kralle", description = "Himmelsfürst Omnuron und seine Druiden der Kralle waren eine furchterregende Streitkraft, damals in Hyjal. Ich weiß, dass sie die bekannten Himmel dieses Schlachtfelds vorziehen, aber die Zeit mag kommen, dass wir sie trotzdem hier brauchen.\n\nSolltet Ihr es schaffen, genügend Abzeichen zusammenzubekommen, so appelliert an Omnuron, dass seine Druiden an der Hauptfront sein sollten. Omnuron passt auf die seinen auf, aber er versteht auch die Wichtigkeit dieser Anstrengung.", sourceObjective = "Sammelt 150 Abzeichen des Weltenbaums.", progress = "Es ist gut, Euch wiederzusehen.", completion = "Ich verstehe. Ich kann nicht behaupten, dass ich erpicht darauf wäre, meine Leute in die Feuerlande zu schicken, aber mir war klar, dass es irgendwann notwendig werden würde.\n\nWir werden da sein, {class}. Danke, dass Ihr die Nachricht überbracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29182] = { id = 29182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Flug der Sturmkrähen", description = "Viele der Druiden der Kralle haben sich auf Euer Geheiß zur Geschmolzenen Front begeben. Ihr solltet zu Himmelsfürst Omnuron bei Malfurions Bresche gehen und sehen, wie sich ihre Schwingen in diesen brennenden Himmeln schlagen.", sourceObjective = "Sprecht mit Himmelsfürst Omnuron bei Malfurions Bresche.", completion = "Diese Himmel sind tatsächlich beklemmend, aber wir haben es geschafft, uns größtenteils durchzunavigieren.\n\nEs kann sein, dass wir Eure Hilfe brauchen, um zusätzliche Landeplätze hinter dem Schmelzofen zu sichern. Ich werde Euch rufen, wenn wir so weit sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[29183] = { id = 29183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daily Tier 2 Heroic (Nth)" }
quests[29184] = { id = 29184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das X markiert Euren Untergang!", description = "Wie konnten diese Narren nur versagen? Ich habe ihnen gesagt, dass sie vorsichtig sein müssen - sogar Verkleidungen habe ich ihnen gegeben, damit sie sich leichter einschleichen können. Ach, was soll's. Das Gute an der Sache ist, dass diese Gelegenheit jetzt Euch und Euren Freunden zuteil wird.\n\nWenn Ihr Euch richtig anstellt, dann seid Ihr auf dem besten Weg, ein Teil meiner Mannschaft zu werden und damit an all dem unermesslichen Ruhm teilzuhaben, der bald mein sein wird. Nicht, dass ich Euch brauchen würde, vergesst das nicht.\n\nEs gibt da noch einige Bereiche auf der Karte, die noch besser erforscht werden müssen, bevor unsere Ausgrabung wirklich beginnen kann...", sourceObjective = "Erkundet Halazzis Kammer, Jan'alais Plattform und Akil'zons Plattform in Zul'Aman.", sourceObjectiveStatus = "unverified-source-field" }
quests[29185] = { id = 29185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daily Tier 2 Heroic (1st)" }
quests[29186] = { id = 29186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fetisch des Hexlords", description = "Dieser neue Kriegsherr der Amani is' ohne den Schutz eines starken Hexendoktors nichts als ein zu groß geratener Haudrauf. Leider genießt er genau diesen Schutz.\n\nMit dem neuen Kriegsherrn im Bunde steht Hexlord Malacrass, der seit Jahrzehnten gefürchtetste Hexendoktor unter den Amani. Daakara wird sein Volk nich' dazu bring'n, sich der Kontrolle der Zandalari zu unterstell'n, es sei denn, der Hexlord befiehlt es.\n\nBesieg Hexlord Malacrass, bring mir seinen Lieblingsfetisch und ich garantier' dir eine angemessene Belohnung.", sourceObjective = "Erbeutet den Fetisch des Hexlords von Hexlord Malacrass in Zul'Aman.", progress = "Hast du Hexlord Malacrass ausgeschaltet?", completion = "Das ist also der Fetisch vom mächtigen Malacrass? Der macht sich sicher gut in meiner Sammlung, {name}. Und für dich is', glaub' ich, 'ne Belohnung angebracht.", sourceObjectiveStatus = "unverified-source-field" }
quests[29187] = { id = 29187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jäger der verlorenen Hauer", description = "Hey Mann! Du bist neu hier, oder? Kannst du mir einen Gefallen tun?\n\nBudd will seiner Waldtrollverkleidung den letzten Schliff verpass'n. Meinte, dass er schon fast fertig is' und nur noch eine letzte Sache braucht. Hauer.\n\nMeine Kürschnerkünste wär'n hier reine Zeitverschwendung. Trollhauer rauszieh'n... ah, bei so was würde mir sofort schlecht werd'n. \n\nBring mir 10 Trollhauer, ja, Mann?", sourceObjective = "Sammelt 10 Hauer eines Waldtrolls von Trollen in Zul'Aman.", sourceObjectiveStatus = "unverified-source-field" }
quests[29188] = { id = 29188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Troll unter Trollen", description = "Hör zu, Mann, da gibt's noch was anderes, was du für den alten Prigmon tun könntest.\n\nZungam, mein alter Taugenichts von Vetter, steckt in Zul'Aman fest. Er lebt auch noch - ich habe sein Rauchsignal erst letzte Nacht geseh'n!\n\nIch sollte ihn eigentlich verrott'n lass'n, dafür, dass er mich in dieses ganze Schlamassel verwickelt hat... allerdings schuldet er mir noch eine Stange Geld.\n\nTu, was du kannst, um ihn da rauszuhol'n, das Abkassier'n kannste mir überlass'n!", sourceObjective = "Sprecht mit Zungam in Zul'Aman.", sourceObjectiveStatus = "unverified-source-field" }
quests[29189] = { id = 29189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nervige Netze", description = "Einige unserer Späher haben sich nicht zum Dienst zurückgemeldet. Wir fürchten, dass sie den tödlichen Spinnen in der Umgebung zum Opfer gefallen sind.\n\nAllerdings sind wir noch nicht bereit, alle Hoffnung fahren zu lassen, denn die Spinnen wickeln ihre Opfer oft noch lebend ein, um sie später zu... konsumieren.\n\nGeht und sucht bei den Säulen im Norden nach eingesponnenen Opfern. Vielleicht gelingt es Euch, einige unserer Brüder zu retten.", sourceObjective = "Befreit 8 Opfer aus Aschenweberkokons.", completion = "Unsere verlorenen Verbündeten sind bereits zurückgekehrt. Sie sind gebeutelt, aber sie sind am Leben. Vielen Dank, dass Ihr sie gerettet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29190] = { id = 29190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachensteigen", description = "Neulich, als ein paar von uns mit der Matrone unterwegs waren, haben wir einen Goblin gesehen, der einen Wagen mit Spielzeugen geschoben hat. Er hatte Puppen, Rennwagen aus Kupfer, Lederbälle und Papierdrachen. Ich wollte schon immer einen Drachen haben und die Matrone sagt, dass ich nur all mein Geld sparen muss, dann kann ich mir einen kaufen, aber das dauert noch ewig.\n\nIch glaube, der Name des Goblins war Blax Flaschenzünder oder so was. Wenn wir ihn aufspüren, könnten wir uns ein paar Drachen holen und sie steigen lassen? Ich habe ihn und seinen Karren in der Gasse gesehen.", sourceObjective = "Kauft einen Doppelpack Papierdrachen von Blax Flaschenzünder in Orgrimmars Gasse und benutzt sie, um mit Eurem Orcwaisenkind einen Drachen steigen zu lassen. Wenn Euer Waisenkind nicht bei Euch ist, solltet Ihr es herbeirufen.", progress = "Ich dachte, dass ich ganz bestimmt eine Million Jahre lang sparen muss, bis ich mir einen Drachen kaufen kann!", completion = "Danke für den Drachen, {name}. Jedesmal wenn ich ihn steigen lasse, werde ich an den Tag denken, an dem Ihr ihn mir geschenkt habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[29191] = { id = 29191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lecker Eis", description = "Es gibt einen brandneuen Eisladen in Orgrimmar und dort verkaufen sie nicht einfach nur gewöhnliches Eis. Deren Eis wird von einem verrückten Goblinmagier gemacht! Glaubt Ihr, es verschwindet, wenn ich es nicht innerhalb von fünfzehn Minuten schaffe?\n\nIch wette, das schmeckt richtig lecker. Gehen wir kosten?\n\nIch habe einige der anderen Kinder darüber reden hören und die sagen, der Laden heißt 'Der Kältekegel' und Ihr findet ihn bei der Botschaft von Orgrimmar.", sourceObjective = "Kauft ein Eis im Laden 'Kältekegel' und teilt es mit Eurem Waisenkind.", progress = "Eiscreme mag ich am liebsten.", completion = "Ich glaube, das ist das erste Mal, dass ich einen Goblin Essen machen sehe, für das er keine große, laute Maschine benutzt, die dicken Rauch spuckt. Vielleicht würden mehr Leute ihre Gerichte mögen, wenn sie sie wie normale Leute zubereiten würden... oder wie Magier! Das Eis war so lecker!", sourceObjectiveStatus = "unverified-source-field" }
quests[29192] = { id = 29192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wächter sehen zu", description = "Wir müssen vorsichtig vorgehen, {class}. Fandrals Druiden der Flamme praktizieren ihre feurige Magie jenseits der Säulen im Norden.\n\nIch möchte, dass Ihr einen dieser Druiden lebend gefangennehmt, damit wir ihn befragen können. Wir müssen jede Gelegenheit beim Schopf ergreifen, um ihre Pläne in Erfahrung zu bringen.\n\nEine meiner Wächterinnen wird Euch begleiten. Folgt ihren Anweisungen, wenn Ihr am Leben bleiben wollt.", sourceObjective = "Greift einen Druiden der Flamme an, um ihn zu schwächen und lockt ihn dann in die Falle der Schattenwächterin.", completion = "Ich bin beeindruckt, {class}. Eure Taten werden unter den Schattenwächtern nie vergessen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29193] = { id = 29193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf gut Glück", description = "Wir haben guten Nutzen aus unserer Zeit gezogen, <Sterblicher/Sterbliche>.\n\nWährend Ihr auf der Ebene des Feuers gekämpft habt, haben meine Wächter und ich herausgefunden, wann und vor allem wo unser Blick behindert wurde.\n\nWir haben festgestellt, dass der Schleier über den Nexus, im hohen Norden, im Reich des blauen Drachenschwarms, gelegt wurde.\n\nIch habe das zeitlose Auge darauf abgestimmt, dass es Euch zeigen wird, was uns hier bisher verhüllt bleibt.\n\nBringt es sofort nach Kaltarra und findet einen geeigneten Ort, um das Auge zu aktivieren.\n\nGeht jetzt. Wir haben keine Zeit zu verlieren...", sourceObjective = "Bringt das zeitlose Auge nach Kaltarra.", completion = "Ihr seid entweder ein Narr oder ein Wahnsinniger. Doch ungeachtet dessen müsst Ihr dahin zurückkehren, wo Ihr herkommt.\n\nWärt Ihr irgendeinem anderen Mitglied meiner Brut begegnet, wäre Euer Ende bereits gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29194] = { id = 29194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie in einem Spiegel", description = "<Tarecgosa hört Euch zu, während Ihr Eure Anwesenheit in Kaltarra erklärt.>\n\nEure Geschichte klingt glaubwürdig, {class}. Viel hat sich seit Malygos' Tod geändert - wenig davon zum Guten.\n\nIch weiß von dem Gerät, das Ihr mit Euch führt, und ich erkenne Anachronos' Magie in seiner Erschaffung. Es gibt in ganz Kaltarra nur einen Ort, der es erlaubt, dass dieses zeitlose Auge diskret eingesetzt wird.\n\nIhr werdet meine Hilfe brauchen, falls Ihr auf Erfolg hofft. Sprecht mich im Inneren des Nexus erneut an und sie soll Euch gewährt werden.", sourceObjective = "Blickt in das zeitlose Auge am Nethervortex im Inneren des Nexus.\n\nTrefft Tarecgosa im Nexus, wo sie Euch zum Riss eskortieren wird.", completion = "Das kann nicht sein, {class}.\n\nDas muss ein Trick sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[29195] = { id = 29195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ritual der Flamme", description = "Es scheint, als hätten wir alles unter Kontrolle. Unser Invasionsportal zu den Feuerlanden wird jeden Augenblick geöffnet werden und die Elementare haben sich bisher nicht besonders zur Wehr gesetzt.\n\nHelft unseren Druiden, indem Ihr die letzten paar Elementare erledigt. Sobald das Tor dann geöffnet ist, können wir losschlagen.", sourceObjective = "Bekämpft die Wellen der verkohlten Eindringlinge auf dem Nordunegrat bis das Portal geöffnet ist.", completion = "Leyara... sie ist am Leben. Ich spüre, dass Fandral die Hände mit im Spiel hat...", sourceObjectiveStatus = "unverified-source-field" }
quests[29196] = { id = 29196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Heiligtum!", description = "Für den Augenblick sollten wir uns keine Sorgen um diese \"Druidin der Flamme\" machen. Wir müssen uns um die Fortführung unserer Operation kümmern.\n\nKehrt zu Matookla beim Heiligtum von Malorne zurück. Wenn Ragnaros auf unsere Ankunft vorbereitet war, dann erwarte ich, dass seine Streitkräfte schon bald einen Gegenangriff starten werden.", sourceObjective = "Meldet Euch bei Matookla beim Heiligtum von Malorne auf dem Hyjal.", completion = "Was ist dort oben geschehen? Ich habe Feuer gesehen und... Ach, unwichtig, Ihr könnt es mir später erzählen. Wir haben andere, dringendere Dinge, um die wir uns kümmern müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29197] = { id = 29197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kalt erwischt", description = "Es sieht so aus, als sei unser Invasionsplan nach hinten losgegangen. Einige unserer Vögel haben sich bereits zurückgemeldet und berichten von Feuern, die in den Tälern des zentralen Hyjal ausgebrochen seien.\n\nNun sind viele von unseren Druiden im Feld gestrandet, unvorbereitet für solch einen großangelegten Angriff. Thisalee war in der Nähe des Aschensees und verschiedene andere befanden sich beim Geheilten Hyjal, im Nordosten.\n\nGeht, {name}! Findet sie und stellt sicher, dass sie dieser Explosion nicht zum Opfer fallen!", sourceObjective = "Helft Ahnenzweig, Thisalee Krähe, Tholo Weißhuf und Anren Schattensucher, den Flammen zu entkommen.", completion = "{name}! Ihr seid zurück!\n\nSie haben uns zum Heiligtum zurückgedrängt. Wir sind ihnen zahlenmäßig weit unterlegen. Bei diesem Tempo haben die Wächter des Hyjal kaum eine Chance zu überleben.\n\nIch bin froh, dass Ihr hier an unserer Seite steht.", sourceObjectiveStatus = "unverified-source-field" }
quests[29198] = { id = 29198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Heiligtum darf nicht fallen", description = "Malfurion arbeitet an einem Wunder für uns. Er glaubt, dass er in diesen gefährlichen Zeiten Malorne wiederauferstehen lassen kann, um das Heiligtum zu beschützen. Ich habe Vertrauen in ihn.\n\nIn der Zwischenzeit müssen wir die Stellung hier halten. Haltet Euch bereit und stellt sicher, dass dem Erzdruiden kein Leid widerfährt.", sourceObjective = "Schützt Malfurion, während er Malorne wiederauferstehen lässt.", completion = "Malornes Stärke alleine hat vielleicht gerade Kalimdor gerettet. Sich vorzustellen, dass Malorne heute zurückgekehrt ist, nach so langer Abwesenheit...\n\n<Malfurion überblickt die Gegend.>\n\nWir haben heftige Verluste erlitten. Obwohl die unmittelbare Bedrohung nicht länger besteht, werden unsere Streitkräfte doch Zeit brauchen, zu gesunden, und alle verbleibenden Feuer am Hyjal zu löschen.\n\nUnser Angriff auf die Feuerlande wird warten müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29199] = { id = 29199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung rufen", description = "Durch die Gegenwehr während unseres Invasionsversuchs haben wir schwere Verluste erlitten. Unser zweiter Versuch darf einfach nicht fehlschlagen.\n\nWir brauchen Verstärkung, bevor wir uns an einer neuen Invasion versuchen können. Bitte, {name}, arbeitet mit Matookla zusammen, um neue Quellen zu erschließen, um Verstärkung zu ermöglichen. Dann werden wir uns zum zweiten und letzten Mal daran versuchen, die Feuerlande anzugreifen.", sourceObjective = "Sammelt 20 Abzeichen des Weltenbaums.", progress = "Je eher wir einen Durchbruch durch unser Invasionsportal erzielen können, umso besser.", completion = "Ausgezeichnete Arbeit. Ich fordere sofort unsere Verstärkung an.", sourceObjectiveStatus = "unverified-source-field" }
quests[29200] = { id = 29200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leyara", description = "Bevor wir aufbrechen, {name}, gibt es noch eine weitere Sache, um die Ihr Euch kümmern solltet.\n\nEine dieser \"Druiden der Flamme\" wurde in den Ruinen im Nordwesten gesehen. Ich schätze, dass es dieselbe ist, die uns vor einigen Tagen am Portal angegriffen hat. Jetzt wäre ein idealer Zeitpunkt, um herauszufinden, was sie wirklich will... und sie, wenn nötig, zu erledigen.\n\nKümmert Euch um diese Flammendruidin, dann können wir auf dem geplanten Weg fortfahren.", sourceObjective = "Findet Leyara, die Druidin der Flamme.", completion = "<Matookla hört aufmerksam zu, als Ihr erklärt, was geschehen ist.>\n\n<Sie ist sichtbar erschüttert.>\n\nIhr seid von unserem Plan abgewichen, {name}. Unser Angriff hätte heute stattfinden sollen! All diese Vorbereitungen... wie können wir ohne die Hilfe Hamuuls siegreich sein?", sourceObjectiveStatus = "unverified-source-field" }
quests[29201] = { id = 29201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch die Tore der Hölle", description = "Wir werden später um Hamuul trauern. Er war das erste von vielen unvermeidlichen Opfern dieses Kriegs... Aber unser Angriff kann nicht warten und die Triebkraft, die wir über die letzten Tage aufgebaut haben, darf nicht verschwendet werden.\n\nHeute greifen wir die Feuerlande an.\n\nDas Portal auf dem Nordunegrat ist jetzt geöffnet. Unsere Verstärkung ist vorbereitet und wartet nur auf meinen Befehl, um durch das Portal zu gehen.\n\nWir werden uns auf der anderen Seite des Portals wiedersehen. Sobald wir einmal dort sind, werden wir sicherstellen, dass unsere Stellung gesichert ist.", sourceObjective = "Geht durch das Portal auf dem Nordunegrat und helft Malfurion dabei, die Stellung an der Geschmolzenen Front zu sichern.", completion = "Sehr gut gemacht, {class}. Wir haben es geschafft, uns im Reich des Feindes eine Stellung einzurichten, ohne dass sie es bemerkt haben. In genau diesem Moment bewegen sich unsere Armeen voran und errichten eine Front.\n\nUns steht ein langer, brutaler Krieg bevor. Es ist meine Hoffnung, dass Ihr an unserer Seite sein werdet, um uns hierbei zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29202] = { id = 29202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal von Runentotem", description = "Ich entschuldige mich dafür, dass ich Euch gegenüber zuvor so kurzangebunden war. Der Verlust von Hamuul hat mich schockiert und es ist nicht einfach, damit umzugehen.\n\nSie haben seinen Körper hereingebracht, während Ihr weg wart. Er lebt, aber er hat - wie Ihr Euch denken könnt - sehr, sehr schwere Verbrennungen erlitten.\n\nDie Wunden sind tief. Vielleicht wird er es nicht überleben.\n\nIch habe ihm einige unserer besten Heiler zur Seite gestellt, die sich um ihn kümmern. Wenn es nicht zu viel verlangt ist, könntet Ihr vielleicht mit Dorda'en Nachtweber sprechen? Er und die anderen Pfleger könnten vielleicht Eure Hilfe brauchen.", sourceObjective = "Sprecht mit Dorda'en Nachtweber beim Heiligtum von Malorne auf dem Hyjal.", completion = "Ja, Hamuul lebt. Ihr könnt ihn in dem Zelt hinter mir besuchen, aber seid bitte vorsichtig. Er ist in sehr schlechtem Zustand und wir tun alles in unserer Macht Stehende, um ihn am Leben zu halten und es ihm bequem zu machen.\n\nWer auch immer das dem Erzdruiden angetan hat, hat keinerlei Gnade gezeigt. Ich hoffe, dass Ihr Euch dafür irgendwann revanchieren könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29203] = { id = 29203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Tiefen", description = "Leyara ist in den Feurigen Tiefen entdeckt worden. Eine Gruppe Schattenwächter hat sie umzingelt.\n\nBegebt Euch sofort dorthin. Ich werde Euch treffen, sobald ich eine notwendige Vorbereitung abgeschlossen habe.", sourceObjective = "Tötet Leyara.", completion = "Leyaras Geschichte ist tragisch. Es schmerzt mich, dass es so weit gekommen ist.\n\nHirschhaupt muss aufgehalten werden, bevor er noch weitere mit sich in den Abgrund reißt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29204] = { id = 29204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Angriff der Wächterinnen", description = "Hauptmann Saynna Sturmläufer ist im Begriff, einen Angriff gegen den Einsamen Turm zu führen. Wenn Ihr Euch nach Nordosten begebt, werdet Ihr sie unten an der Rampe finden, die zu der Anhöhe führt.\n\nIch habe ihr eine große Gruppe unserer Männer unterstellt, aber ihre Erfolgsgruppen würden enorm steigen, wenn Ihr Euch ihr anschließen würdet. Es ist Eure Entscheidung, {name}.", sourceObjective = "Wenn Ihr den Wächterinnen helfen wollt, den Einsamen Turm anzugreifen, dann sprecht mit Hauptmann Saynna Sturm in den nordöstlichen Aschenfeldern.", sourceObjectiveStatus = "unverified-source-field" }
quests[29205] = { id = 29205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Einsame Turm", description = "Hauptmann Saynna Sturmläufer ist im Begriff, einen Angriff gegen den Einsamen Turm zu führen. Wenn Ihr Euch nach Nordosten begebt, werdet Ihr sie unten an der Rampe finden, die zu der Anhöhe führt.\n\nGeht dorthin und eskortiert einen ihrer Druiden zum Turm mit allen Streitkräften, die sie entbehren kann. Euch steht ein ordentlicher Kampf bevor - stellt sicher, dass der Druide bis zum Ende überlebt oder es wird ihnen nicht möglich sein, den Turm zu erobern.", sourceObjective = "Beschützt einen der Druiden, die versuchen, den Einsamen Turm einzunehmen.", completion = "Gut gemacht, {class}. Das sollte ein guter Ausgangspunkt sein, um weiter in feindliches Gebiet vorzudringen.\n\nIch kann in der Nähe Druiden der Flamme spüren. Vielleicht sollten wir auch mit ihnen kurzen Prozess machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29206] = { id = 29206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ins Feuer", description = "Der Himmelsfürst Omnuron und seine Druiden versuchen durch den Schmelzofen im Nordwesten durchzubrechen. Es war ihnen möglich, über die Gefahren hinwegzufliegen, aber sie benötigen wirklich jemand auf dem Boden, der ihnen hilft, das Gebiet jenseits des Feuers zu sichern... jemanden wie Euch.\n\nWenn Ihr den Druiden der Kralle helfen wollt, so wartet darauf, dass einer von Omnurons Windrufern versucht, das Feuer zu durchbrechen, bleibt in seiner Nähe und beschützt ihn vor Angreifern aus den Flammen.", sourceObjective = "Eskortiert einen Windrufer durch den Schmelzofen und sichert den Eingang zum Geschmolzenen Strom.", completion = "Es ist gut zu sehen, dass der Himmelsfürst endlich jemand Fähigen ohne Flügel gefunden hat. Die Fähigkeit zu fliegen nützt uns in diesen beengten Umständen und im Anbetracht der Thermalwinde jenseits dieses Grats wenig.\n\nEs sieht so aus, als müssten wir uns auf konventionellere Taktiken verlassen. Seid Ihr dabei?", sourceObjectiveStatus = "unverified-source-field" }
quests[29208] = { id = 29208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein alter Freund", sourceObjective = "Zwischen all den Raptoren in Mandokirs Reich sticht ein vertrautes Gesicht heraus. Sie ist etwas größer geworden und hat ein paar mehr Narben, aber sie ist noch immer hier und wartet auf Eure Rückkehr.\n\nSie erkennt Euch wieder. Ihr Papa ist endlich da, um sie zu retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29209] = { id = 29209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinein in die Feurigen Tiefen", description = "Eine unserer Druidinnen ist vorangegangen in die Feurigen Tiefen, auf der Jagd nach einem Druiden der Flamme.\n\nGeht zu ihr. Helft ihr.", sourceObjective = "Sprecht mit Theresa Baumrinde in den Feurigen Tiefen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29210] = { id = 29210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erdulden der Hitze", description = "Shalis ist mit einem unserer Druiden losgezogen, um einen Druiden der Flamme davon abzuhalten, in den Feurigen Tiefen unter uns ein Beschwörungsritual zu vollziehen. Ihnen ist aufgetragen worden, den Druiden zu töten, aber ich brauche Euch, um das Ritual zu stoppen.\n\nIhr werdet den Eingang zu den Feurigen Tiefen östlich der Magmaquellen finden. Sobald Ihr im Inneren seid, werdet Ihr 8 blaue Runen über die Höhle verteilt sehen. Ihr könnt diese Runen benutzen, um Euch vor den feurigen Kreaturen zu schützen, aber Ihr werdet alle von ihnen austreten müssen, um das Ritual zu beenden. Ihr werdet schnell handeln müssen.", sourceObjective = "Findet den Weg in die Feurigen Tiefen und zerstört dann alle 8 der blauen Runen, die sich im Inneren befinden.", progress = "Ihr müsst die Runen zerstören! Beeilt Euch!", completion = "Gut gemacht!\n\nSie haben versucht, Rituale wie dieses überall an der Geschmolzenen Front durchzuführen, doch bisher konnten wir dieses Vorhaben noch immer vereiteln. Hoffentlich werdet Ihr auch in Zukunft da sein, um uns dabei zu helfen, diesen Trend fortzusetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29211] = { id = 29211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Solarkernzerstörung", description = "Der Kampf hat uns direkt zu Fandrals Haustür gebracht. Seine Druiden kanalisieren Energien der Feuerlande in ein Behältnis, das der Solarkern genannt wird.\n\nSollte dieses Behältnis auf Azeroth explodieren, wird keinem von uns eine Heimat bleiben, in die wir zurückkehren könnten.\n\nWir müssen jetzt einen Schlag gegen den Solarkern führen, solange er noch angreifbar ist. Ihr könnt das infernalische Gerät auf der nordöstlichen Kante der Insel finden.", sourceObjective = "Sprengt den Solarkern.", completion = "Ist er zerstört? Gut. Ich bezweifle, dass das Fandral lange aufhalten wird, aber wir müssen uns jeden Vorteil sichern, den wir bekommen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[29212] = { id = 29212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Hawk Down" }
quests[29213] = { id = 29213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie geht's dem Jäger?", description = "Das sah nich' gut aus. Der Panther stand unter irgendeiner Art von mächtiger Magie... Wir sollt'n besser nach dem Jäger seh'n und schau'n, wie's ihm geht.", sourceObjective = "Seht nach Grent Düsterhammer.", completion = "Oh... Mein Kreuz. Bist du das, Bruder?", sourceObjectiveStatus = "unverified-source-field" }
quests[29214] = { id = 29214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schattenwächterinnen", description = "Die Schattenwächterinnen sind zurück im Geheilten Hyjal. Ich weiß, dass sie den Verlust von Fandral aus ihrem Gewahrsam sehr ernst nehmen, weshalb es wenig Ansporn bedürfen wird, sie in die Feuerlande zu bringen und die Druiden der Flamme zu jagen.\n\nSobald Ihr genügend Abzeichen zusammen habt, solltet Ihr Euch bei Hauptmann Saynna Sturmläufer beim Heiligtum von Malorne melden und Euch ihre Unterstützung sichern.", sourceObjective = "Sammelt 150 Abzeichen des Weltenbaums.", progress = "Ja, {class}?", completion = "Ich verstehe. Die Zeit ist also gekommen, dass wir uns der Jagd in den Feuerlanden anschließen. Meine Schwestern werden hinter Euch stehen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29215] = { id = 29215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd beginnt", description = "Die Schattenwächterinnen haben sich auf Eure Bitte hin dem Kampf an der Geschmolzenen Front angeschlossen. Ihr solltet Hauptmann Saynna Sturmläufer finden und dafür sorgen, dass sie einen Weg finden, ihre Fähigkeiten am besten einzusetzen.", sourceObjective = "Sprecht mit Hauptmann Saynna Sturmläufer bei Malfurions Bresche.", completion = "Hallo {name}. Es ist gut, Euch wiederzusehen.\n\nIhr hättet Euch keine Sorgen machen müssen, wir haben uns hier ganz gut eingerichtet. Ich habe mehrere meiner Wächterinnen ausgeschickt, um dabei zu helfen, die Druiden der Flamme zur Strecke zu bringen und ich habe die Angriffspläne für den Einsamen Turm angefertigt. Wenn der Zeitpunkt gekommen ist, werdet Ihr Euch uns vielleicht dort anschließen wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29216] = { id = 29216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "alfurion's Breach" }
quests[29217] = { id = 29217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gefangenen Späher", description = "Nachdem wir hier angekomm'n sind, habe ich meine Späher losgeschickt, um mehr über die Anwesenheit der Zandalari hier in Zul'Aman zu erfahr'n. Viele sind mit nützlichen Informationen zurückgekehrt, aber vier werd'n noch immer vermisst. Wenn wir nich' schnell handeln, werd'n die Handlanger des neuen Kriegsherrn sie zu Ehren der Gesandten der Zandalari opfern.\n\nFinde meine Späher, {name}, und befrei sie, bevor die Priester sie opfern!", sourceObjective = "Befreit die gefangenen Späher: Hazlek, Bakkalzu, Norkani und Kasha. Sie werden von den Hohepriestern der Amanitrolle gefangen gehalten.", completion = "Ich hätte nich' gedacht, die nochmal wiederzuseh'n, {name}. Die Informationen, die sie gesammelt hab'n, werd'n der Schlüssel dazu sein, den Einfluss der Zandalari in Zul'Aman zu brech'n. Herzlichen Dank von mir und meinen Spähern.", sourceObjectiveStatus = "unverified-source-field" }
quests[29218] = { id = 29218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abzeichen des Weltenbaums" }
quests[29219] = { id = 29219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bwembas Geist", description = "Es sind gefährliche Zeiten für uns Dunkelspeere. Die Zandalaritrolle versammeln alle Trollklans und hab'n vor, die Länder wiederzuerobern, die sie verlor'n hab'n.\n\nWir versuch'n alle zu warnen, die wir können. Aber es könnte zu spät sein.\n\nEin weiterer Dunkelspeertroll is' ins Schlingendorntal gegang'n, um die Leute zu warnen. Aber es is' nich' sicher, allein da durchzuwandern.\n\nHilf mir, ihn zu find'n und sicherzustell'n, dass die Leute im Schlingendorntal von der Bedrohung durch die Trollstämme erfahr'n.\n\nIch werd' meinen Geist mit deinem verbind'n. Wenn du ins Schlingendorntal gelangst, werd' ich dir helf'n können.", sourceObjective = "Warnt die Bewohner des Schlingendorntals und findet den anderen Abgesandten der Dunkelspeere.", completion = "Da siehst du's, {name}. Sieht aus, als würd'n wir einen Angriff auf die Gurubashi in Zul'Gurub anführ'n.\n\nDies sind dunkle Zeiten für uns Dunkelspeere. Aber für die Zandalaritrolle werd'n sie noch dunkler. Sie sind zu weit gegang'n.\n\nDu bist gut zu Bwemba gewes'n, hoffentlich wirst du weiter das ganze Schlingendorntal unterstütz'n.\n\nMög'n die Geister mit dir sein, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29220] = { id = 29220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Bambala", description = "Zuerst sollt'n wir dort nachsehen, wo vermutlich der erste Angriff stattfindet, also in Bambala.\n\nBambala is' gefährlich nahe an der Trollstadt Zul'Gurub dran... ein leichtes Ziel.\n\nVielleicht find'n wir den Abgesandten dort. Hoffentlich is' es noch nich' zu spät.", sourceObjective = "Reist nach Bambala im Nördlichen Schlingendorntal, um den Abgesandten der Dunkelspeere zu finden.", completion = "Wie's aussieht, sind die Geister mit dir, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29221] = { id = 29221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlangen und Gift", description = "Die Warnung hat geholf'n, {name}.\n\nWir hab'n mehr Kopfjäger für unsere Verteidigung versammelt. Aber Kopfjäger... na ja, die jag'n für gewöhnlich nich' die Köpfe von Schlangen. Wir werd'n also bald überwältigt sein. Diese Schlangen scheinen von überall herzukomm'n. Und wahrscheinlich wird's nur noch schlimmer.\n\nHilf uns, die Schlangen zu töt'n und lass Bwemba ihr Mojo verwend'n, damit die Vergifteten geheilt werd'n.", sourceObjective = "Tötet Dschungelschlangen und untersucht die vergifteten Kopfjäger, damit Bwemba sie heilen kann.", completion = "Danke für deine Hilfe, {class}. Die Schlangen sind ja überall.", sourceObjectiveStatus = "unverified-source-field" }
quests[29222] = { id = 29222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geister sind mit uns", description = "Mit den Schlangen hat was nich' gestimmt, {name}. In ihrem Gift war eine Spur von schlechtem Mojo und das passiert nich' von Natur aus.\n\nDas Freudenfeuer in der Mitte des Lagers - dort können wir ein Ritual abhalt'n.\n\nWas auch immer diese Schlangen zum Angreif'n bringt, passt bestimmt noch gut auf sie auf.\n\nDas einzige Problem is', {name}, dass ich nur in Geisterform hier bin. Du musst meine Hände sein. Geh zu dem Feuer und bereite es für mich vor. Dann kümmere ich mich um den Rest.", sourceObjective = "Bereitet das Freudenfeuer vor dem Schlangenschrein in der Nähe von Bambala für Bwembas Ritual vor.", completion = "Venoxis... das kann nix Gutes heiß'n, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29223] = { id = 29223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nesingwary wird es wissen", description = "Die Gurubashi sind also auf dem Vormarsch und die benutz'n Schlangen als erste Angriffswelle.\n\nWeißt du, wer sich darauf versteht, die Wildtierbestände hier klein zu halt'n? Die Jäger in Nesingwarys Expedition.\n\nSpazier doch mal da 'rüber und frag sie nach einer guten Methode, wie man Schlangen loswird.\n\nWenn die's nich' wiss'n, dann solltest du sie wenigstens warn'n, dass mit diesen Schlangen was nich' stimmt.", sourceObjective = "Warnt die Jäger in Nesingwarys Expedition im Nördlichen Schlingendorntal.", completion = "Über die Schlangen wissen wir Bescheid, {name}. Aber da draußen lauert noch etwas anderes... Der Dschungel ist zum Leben erwacht, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[29224] = { id = 29224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "O LONGER USED" }
quests[29225] = { id = 29225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Informationen mit Konsequenzen", description = "<Tarecgosa hört gebannt zu, während Ihr Eure Vision schildert.>\n\nUnmöglich!\n\nNicht einmal Arygos würde es wagen, so weit zu gehen.\n\nIch stelle hier nicht Eure Integrität in Frage, {class}, doch müsst Ihr verstehen, Euer sterblicher Geist kann leicht getäuscht werden.\n\nDoch in jedem Fall muss Kalecgos über diese Ereignisse unterrichtet werden. Ihr müsst sofort nach Nordrassil reisen und ihn aufsuchen.\n\nIch bleibe hier und beseitige die Beweise unserer Aktivitäten. Erzählt sonst niemandem davon.", sourceObjective = "Sprecht mit Kalecgos bei Nordrassil auf dem Hyjal.", completion = "<Kalecgos hört sich Eure Erzählung der jüngsten Ereignisse an.>\n\nEs war weise von Tarecgosa, Euch zu mir zu schicken, {class}.\n\nObwohl Eure Vision im Nexus fast sicher eine ausgeklügelte Illusion war, wäre es unverantwortlich von mir, die Sache nicht zu untersuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29226] = { id = 29226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Spurenleser auf der Spur", description = "Wir schlagen hier schon seit Tagen die Schlangen zurück, {name}. Aber Schlangen sind nichts im Vergleich zu dem, was sich da sonst noch so im Dschungel herumtreibt.\n\nWir Jäger werden zu Gejagten.\n\nEin großer Panther namens Mauti hat meine Männer einen nach dem anderen in den Busch weggezerrt.\n\nWir haben Grent Düsterhammer, einen unserer besten Jäger, auf dieses Mistviech angesetzt.\n\nDüsterhammer ist nach Osten aufgebrochen. Vielleicht könnt Ihr ihn dort finden.", sourceObjective = "Findet Düsterhammer im Nördlichen Schlingendorntal.", completion = "Schhh...", sourceObjectiveStatus = "unverified-source-field" }
quests[29227] = { id = 29227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rache des Jägers", description = "Die Bestie, die uns auf der Spur war... ich habe nach ihr gejagt.\n\nIhr Name ist Mauti. Sie ist ziemlich schlau. Doch sie hat einen großen Fehler begangen, als sie meinen Bruder getötet hat. Das wird sie teuer zu stehen kommen. Der alte Düsterhammer ist ihr auf den Fersen.\n\nIch habe sie oberhalb von Kurzens Truppenlager herumstreifen sehen. Wenn wir schnell zuschlagen, können wir ihr den Garaus machen.\n\nSeid Ihr bereit, {name}?", sourceObjective = "Gewährt Grent Düsterhammer die Genugtuung, die er sich wünscht, indem Ihr Mauti tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[29228] = { id = 29228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Folgt dieser Katze", description = "Tja, deshalb schien Mauti wohl kleiner... Der echte Mauti hat sich mit Grent Düsterhammer davongemacht, aber da er so ein vorausschauender Jäger ist, hat er Signalfeuer abgeschossen, damit Ihr ihm auf der Spur bleiben könnt. Findet Düsterhammer, bevor es zu spät ist!", sourceObjective = "Findet heraus, wohin Mauti Grent Düsterhammer gebracht hat.", completion = "Da sind wir... Der Jäger, er is' in der Höhle. Die Bestie... Etwas stimmt mit ihr nicht...", sourceObjectiveStatus = "unverified-source-field" }
quests[29229] = { id = 29229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Folgt dieser Katze", description = "Tja, deshalb schien Mauti wohl kleiner... Der echte Mauti hat sich mit Grent Düsterhammer davongemacht, aber da er so ein vorausschauender Jäger ist, hat er Signalfeuer abgeschossen, damit Ihr ihm auf der Spur bleiben könnt. Findet Düsterhammer, bevor es zu spät ist!", sourceObjective = "Findet heraus, wohin Mauti Grent Düsterhammer gebracht hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[29230] = { id = 29230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mauti", description = "Ich hab das Gefühl, dass mit dem Panther was nich' stimmt, {name}. Fühlt sich unnatürlich an. Ich werd' ein paar Rituale über dem Leichnam abhalt'n müss'n. Töte Mauti und dann werd'n wir mal seh'n, was wir herausfinden können, {name}.", sourceObjective = "Bringt Bwemba zu den Überresten von Mauti.", completion = "Hohepriesterin Kilnara steckt hinter dieser Monstrosität. Das sieht nich' gut aus. Wir sollt'n nach dem Zwerg seh'n und dann herausfind'n, was sonst noch so los ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[29231] = { id = 29231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie geht's dem Jäger?", description = "Das sah nich' gut aus. Der Panther stand unter irgendeiner Art von mächtiger Magie... Wir sollt'n besser nach dem Jäger seh'n und schau'n, wie's ihm geht.", sourceObjective = "Seht nach Grent Düsterhammer.", completion = "Oh... Mein Kreuz. Bist du das, Bruder?", sourceObjectiveStatus = "unverified-source-field" }
quests[29232] = { id = 29232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzten Botten", description = "Ah... Ihr seid es, {name}. Mauti... Sie ist tot? Dann wurde mein Bruder gerächt. Ich habe nur noch eine Bitte an Euch... Dieser Schuft hier hat an meinen nackten Füßen herumgekratzt. Kein Zwerg sollte ohne Stiefel unter die Erde müssen.\n\nBitte, begrabt mich mit meinen Stiefeln.", sourceObjective = "Holt die Stiefel von Grent Düsterhammer.", progress = "Habt Ihr meine Stiefel? Gewährt einem Zwerg doch seinen letzten Wunsch, ja?", completion = "Da-Danke… Kumpel.\n\nPapi...?\n\n\nBist...\n\n\n\ndu das...\n\n\n\n\n...", sourceObjectiveStatus = "unverified-source-field" }
quests[29233] = { id = 29233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warnt Grom'gol", description = "Dieser Tod war nich' vergebens, {name}. Wir hab'n herausgefund'n, dass Kilnara auf Streifzug is'. Das sieht ziemlich düster für uns aus.\n\nWir seh'n besser nach, wie es in Grom'gol im Westen aussieht. Vielleicht find'n wir ja auch meine Kontaktperson dort.", sourceObjective = "Begebt Euch zum Basislager Grom'gol.", completion = "Erst waren es Schlangen, dann Panther und jetzt sind es blutrünstige Trolle.\n\nBloß gut, dass Ihr hier seid, {class}, es gibt reichlich Trolle abzuschlachten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29234] = { id = 29234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delegierung", description = "Meine Pflicht bindet mich, Euren Aussagen unverzüglich nachzugehen, {race}, was bedeutet, dass meine Mission hier nun in Eure Hände fällt.\n\nEin Anstieg uralter Magie, viel zu stark, um natürlichen Ursprungs zu sein, führte mich hierher. Seitdem habe ich eine zutiefst beunruhigende Entwicklung entdeckt.\n\nEin Ast wurde von Nordrassil abgebrochen und tief in die Feuerlande verschleppt. Dort droht ein mächtiges Ritual, Nordrassil zu verderben und ihn in Flammen aufzuzehren.\n\nIhr müsst einen Weg finden, das Ritual zu unterbrechen und den Zweig des Weltenbaumes zurückzuholen.", sourceObjective = "Holt den Zweig von Nordrassil aus den Feuerlanden zurück.", progress = "Konntet Ihr den Zweig von Nordrassil zurückholen, {class}?", completion = "Der Zweig von Nordrassil…\n\nIhr habt Euch gut geschlagen, sterbliches Wesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29235] = { id = 29235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigt Grom'gol", description = "Ich hoffe, Ihr kämpft gern, {name}. Euer Trollfreund ist hier durchgekommen und hat uns gewarnt, dass die Gurubashi auf dem Vormarsch sind. Ich hätte nie gedacht, dass die Schlacht so glorreich werden würde.\n\nKommt, werft Euch mit uns in die Schlacht und zeigt diesen Gurubashitrollen die Macht der Horde!", sourceObjective = "Helft dabei, das Basislager Grom'gol drei Minuten lang zu verteidigen.", completion = "Diese Trolle strömen immer weiter auf uns ein, {name}. Fantastisch!\n\nWie ich schon sagte, war der Abgesandte der Dunkelspeere für kurze Zeit hier. Er hat uns gewarnt, dann ist er wieder aufgebrochen.\n\nThysta, unsere Windreitermeisterin, hat ihm geholfen, zu seinem nächsten Bestimmungsort zu kommen, vielleicht kann sie Euch helfen.\n\nGute Jagd, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29236] = { id = 29236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Hartzangs Versteck", description = "Bwemba... Seid Ihr das?\n\nEuer Kontakt war hier. Er war erpicht darauf, zum nächsten Ort zu eilen und die Leute zu warnen. Ich habe ihn auf einen Flug nach Hartzangs Versteck am Schlingendornkap geschickt. Ich hoffe, er war nicht zu spät.\n\nIhr könnt einen meiner Wyvern verwenden, um zum Versteck zu gelangen.\n\nSagt Bescheid, wenn Ihr bereit seid aufzubrechen, {name}.", sourceObjective = "Begebt Euch nach Hartzangs Versteck am Schlingendornkap.", completion = "Das sieht nich' sehr gut aus, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29237] = { id = 29237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voodoozombies", description = "Die Leute... alles Zombies, Voodoozombies! Das wird nich' schön, {name}.\n\nDu musst die alle töt'n.\n\nAber sobald sie erledigt sind, gibt es einen Weg, wie ich sie zurückhol'n kann. Wieder in die Personen verwandeln, die sie war'n.\n\nWir müss'n schnell handeln, die Zombies schlafen nich'.", sourceObjective = "Rettet 10 Überlebende des Verstecks.", progress = "Mit dem Voodoo wird die Sache schnell erledigt. Aber gefährlich is' es trotzdem.", completion = "Wir hab'n getan, was wir konnt'n, {name}. Wir können diese Zombies nich' länger bekämpf'n. Wir müss'n die Wurzel dieses Voodoos ausfindig mach'n. Und ich glaub', ich weiß, wo wir anfang'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[29238] = { id = 29238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdorbene Vorräte", description = "Einige der Überlebenden hab'n Nahrungsmittel erwähnt, {name}. Wir sollt'n ihre Vorräte überprüf'n. Ich hab ein schlechtes Gefühl bei der Sache.", sourceObjective = "Überprüft den Ort in Hartzangs Versteck, an dem Nahrungsmittel zubereitet werden.", completion = "Zanzil... Es fängt alles an, Sinn zu ergeb'n. Wenn ich meinen Kontakt find'n kann, können wir einen Angriffsplan entwickeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[29239] = { id = 29239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zweig von Nordrassil", description = "Viel hat sich seit unserem letzten Gespräch ereignet.\n\nIch habe es auf mich genommen, zum Nexus zu reisen und Anachronos' Artefakt zurückzuholen, doch nicht ohne es selbst zu verwenden. Jetzt kann auch ich das bezeugen, was Ihr gesehen habt.\n\nBevor wir noch weiter darüber reden, erlaubt mir, Euch meine Dankbarkeit auszusprechen, sowohl hierfür als auch für die Feuerlande.", sourceObjective = "Besorgt Euch den Zweig von Nordrassil beim Bernsteinflöz in der Boreanischen Tundra.", completion = "Der Zweig von Nordrassil ist jetzt mit dem zeitlosen Auge verbunden.\n\nSelbst ein kampferprobter Held wie Ihr kommt nicht umhin, bei einem solchen Geschenk Demut zu empfinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29240] = { id = 29240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notextrahierung", description = "Nun wieder zur anstehenden Aufgabe...\n\nIch bin mir sicher, dass die Vision im Nexus eine von Todesschwinges Illusionen ist, um unseren Schwarm in dieser schweren Zeit in Streit zu versetzen.\n\nDer Weltenbrecher würde nur noch stärker werden, wenn wir zu den Waffen greifen.\n\nDennoch, mir ist nicht ganz wohl bei der Sache, somit bin ich versucht einen Pfad der Vorsicht einzuschlagen.\n\nEs wäre weise, wenn ich mich mit Tarecgosa zurückziehen würde, bis die Zeit der Wahl gekommen ist.", sourceObjective = "Begleitet Kalecgos nach Kaltarra.\n\nSprecht mit ihm, wenn Ihr bereit seid.", completion = "Sie stirbt, {name}.\n\nIch habe... sie enttäuscht.", sourceObjectiveStatus = "unverified-source-field" }
quests[29241] = { id = 29241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brecht den Götterbrecher", description = "<Blutschlächterin Zala zeigt auf den entfernten Tempel.>\n\nAls Jin'do das letzte Mal ins Jenseits befördert wurde, hat er als schwacher und gebrochener Schemen in der Geisterwelt überlebt.\n\nAber Jin'do hatte ja schon immer Macht über die Geister. Einen nach dem anderen hat er sie seinem Willen unterworf'n und mit jeder verschlungenen Seele is' er seinem Ziel näher gekomm'n, einen Riss in unsere Welt zu öffnen.\n\nJetzt is' er hier...\n\nDie Geister sind mit uns. Wir müss'n Jin'do ein Ende bereit'n.", sourceObjective = "Tötet Jin'do den Götterbrecher in Zul'Gurub auf heroischem Schwierigkeitsgrad.", completion = "<Blutschlächterin Zala greift sich an die Brust.>\n\nEs ist also getan. Das Blut unserer Brüder zu vergieß'n is' keine schöne Aufgabe. Die Stadt der Gurubashi hat jahrelang nur Tod und Hass erlebt.\n\nVielleicht is' es an der Zeit, dass der Dschungel Zul'Gurub zurückerobert und den Gestank des Todes von diesem Ort fortwäscht.\n\nBlut und Donner, Champion! Den Siame Quashi wirst du auf ewig als \"Blutschlächter\" bekannt sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[29242] = { id = 29242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbezahlbar mit Rabatt", description = "Hört zu, <mein Bester/meine Beste>. Ich kenne Euch nicht und Ihr kennt mich nicht, aber wo wir beide nun hier sind: Revilgaz wollte, dass ich etwas erwähne.\n\nVielleicht macht Ihr ja einen Spaziergang durch diese trollinfizierte Dschungelkalypse. Vielleicht findet Ihr ja rein zufällig das eine oder andere kostbare Trollartefakt. Vielleicht bringt Ihr es zu mir und ich lasse aus Versehen ein kleines Geschenk für Euch zurück.\n\nWenn Ihr es unbedingt wissen müsst, es ist für ein Projekt. Und nein, Ihr dürft nicht fragen, was das für ein Projekt ist.", sourceObjective = "Untersucht den Hort des Wahnsinns und findet das mysteriöse Schmuckstück der Gurubashi.", progress = "Na, habt Ihr etwas gefunden? Mir hängen nämlich langsam die Hosen auf Halbmast von all den Schätzen, auf die ich für Euch aufpasse.", completion = "Was habt Ihr denn da?\n\nEin merkwürdiges Schlangengötzenbild? Was soll ich denn damit anfangen? Etwa jemandem damit eins auf den Deckel geben und etwas stehlen, was tatsächlich was wert ist?\n\nDas Ding ist doch Ramsch!\n\n<Briney wirft das Schmuckstück ins Wasser.>\n\nNa dann danke für Eure \"Hilfe\". Hier habt Ihr Eure \"Belohnung.\"\n\nTrottel.", sourceObjectiveStatus = "unverified-source-field" }
quests[29243] = { id = 29243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Stich ins Herz", description = "Einer von Ragnaros' Leutnants hat sich auf Ragnaros' Ebenen gezeigt. Es ist Zeit, zuzuschlagen. Hauptmann Saynna hat darum gebeten, dass Ihr dabei seid und ihr im Kampf beisteht.\n\nDorrzweig und einige andere werden sich bereits dem Kampf angeschlossen haben, wenn Ihr eintrefft. Ihr solltet Euch besser gleich in Richtung Nordwesten aufmachen und sie finden.", sourceObjective = "Tötet den Leutnant der Flamme.", completion = "Sehr gut gemacht, {name}! Das sollte sie erheblich hemmen.\n\nWenn wir das durchhalten, sollten wir den Kampf leicht zu Ragnaros selbst tragen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[29244] = { id = 29244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieutenant of Flame" }
quests[29245] = { id = 29245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das mysteriöse Samenkorn", description = "Eine kleine, trockene Eichel ist aus der Robe des Flammendruiden gefallen.\n\nWarum sollte ein Druide der Flamme so etwas mit sich herumtragen?\n\nVielleicht würde jemand in Malfurions Bresche sie gerne mal sehen.", sourceObjective = "Bringt die Eichel zu Avrilla in Malfurions Bresche in den Feuerlanden.\n\nBereitgestellter Gegenstand:", completion = "Faszinierend! Es scheint sich um eine Eichel zu handeln!", sourceObjectiveStatus = "unverified-source-field" }
quests[29246] = { id = 29246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lindert den Schmerz", description = "Der Erzdruide kann ungeheure Schmerzen ertragen. Ich habe Opfer von Verbrennungen behandelt, die vierundzwanzig Stunden am Tag vor Schmerzen geschrien haben und ihre Verbrennungen waren nicht einmal halb so schlimm wie die, die Hamuul erlitten hat.\n\nNichtsdestotrotz kann ich sehen, dass er heute unter größeren Beschwerden leidet als normal. Bringt mir die Herzen der großen Feuerelementare im Südosten. Ich kann sie verwenden, um eine beruhigende Salbe für unseren Patienten herzustellen.", sourceObjective = "Sammelt 4 flammenumwundene Herzen von wutentbrannten Pyrolords.", progress = "Diese Herzen werden uns genau das geben, was Hamuul benötigt, um sich zu erholen.", completion = "Ich muss mich sofort daran machen, die Salbe zuzubereiten. Diese Reagenzien verlieren jede Minute an Wirkungskraft.\n\nHabt Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29247] = { id = 29247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verarzten der Wunden", description = "Wir haben hier beim Heiligtum ausreichend Vorräte an medizinischer Ausrüstung, aber wir dürfen nicht aus den Augen verlieren, dass wir uns im Krieg befinden. Hamuul ist nicht der Einzige, der Verbände benötigt.\n\nDie feurigen Ungetüme, die Sethrias Nest durchstreifen, tragen feuerresistente Bandagen, die Hamuul genauso gute Dienste leisten werden wie alle anderen Bandagen. Bringt mir diese Bandagen und ich werde sie dazu vorbereiten, sie dem Erzdruiden anzulegen.", sourceObjective = "Besorgt 4 sulfurgetränkte Bandagen von den feurigen Ungetümen in Sethrias Nest.", progress = "Es gibt Leute, die sagen, dass das Sulfur in diesen Bandagen heilende Wirkung hätte. Ich persönlich bin davon nicht überzeugt, aber für den unwahrscheinlichen Fall, dass dem doch so ist, bin ich willens, den Geruch zu ertragen.", completion = "Vielen Dank, {class}.\n\nIhr habt den Kriegsanstrengungen einen Dienst erwiesen. Opfer von Verbrennungen haben einen hohen Verbrauch an Verbänden und Hamuul ist da keine Ausnahme.", sourceObjectiveStatus = "unverified-source-field" }
quests[29248] = { id = 29248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Druck lindern", description = "Nachdem er so furchtbare Verbrennungen erlitten hat, leidet der Erzdruide Hamuul unter Ödemen - Schwellungen des Körpergewebes. Es kostet seine Pfleger große Mühen, die Schwellungen so weit in Schach zu halten, dass er atmen kann.\n\nNormalerweise würden wir die Schwellung behandeln, indem wir Einschnitte ins Fleisch vornehmen, aber er ist zu schwach dafür, {name}. Ich kann ihn heute nicht heilen. Ich brauche Eure Hilfe.\n\nFlammenschürerschuppen helfen gegen die Schwellungen, aber man braucht davon eine ganze Menge.", sourceObjective = "Sammelt 100 Flammenschürerschuppen.", progress = "Habt Ihr die Schuppen? Ich zögere, dem Erzdruiden weitere Schnittwunden zuzufügen, aber wir müssen irgendwie die Schwellung bekämpfen.", completion = "Ihr seid barmherzig, {race}. Mit diesen vielen Schuppen werden wir ihm zumindest für einen Tag keine weiteren Schnitte zufügen müssen. Vielleicht sogar für zwei.", sourceObjectiveStatus = "unverified-source-field" }
quests[29249] = { id = 29249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pflanzzeit", description = "Die Eichel scheint unversehrt zu sein.\n\n<Avrilla zuckt mit den Schultern.>\n\nLasst uns nicht um den heißen Brei reden: Pflanzen wir sie ein und sehen, was daraus wird.\n\nZum Glück für Euch haben wir etwas Resterde mitgebracht, um uns beim Aufbau unserer Basis zu helfen.\n\nIhr findet die Erde beim Friedhof, direkt im Osten.", sourceObjective = "Pflanzt die Eichel in der Erde von Un'Goro bei Malfurions Bresche ein.", completion = "Eine rote Blume erwächst aus der Erde.", sourceObjectiveStatus = "unverified-source-field" }
quests[29250] = { id = 29250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kontaktaufnahme", description = "Ihr seid keiner von den Zombies...\n\nEin Troll? Ich habe einen gesehen, direkt vor dem Ausbruch... Er hat uns gewarnt, gesagt, dass wir vorsichtig sein sollen... Aber es war zu spät.\n\nEuer Trollfreund ist nach Beutebucht gegangen, um sie zu warnen...", sourceObjective = "Begebt Euch nach Beutebucht und findet Bwembas Kontaktperson.", completion = "Ich werde Baron Revilgaz jetzt von der Zandalaribedrohung erzählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29251] = { id = 29251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Interessen Beutebuchts", description = "Also, {name}. Ihr habt uns schon gewaltig geholfen, aber das wird noch nicht reichen. Diese verrückten Trolle müssen aufgehalten oder zumindest von Beutebucht ferngehalten werden.\n\nIch werde jemanden losschicken, der das Geschehen im Auge behält, aber von Euch möchte ich, dass Ihr in Zul'Gurub eindringt und die Dinge in Bewegung setzt.\n\nIhr müsst mir zumindest etwas bringen, das diese Trolle aus Beutebucht fernhält.\n\nBringt das zustande und wir werden uns erkenntlich zeigen.", sourceObjective = "Spürt ein Artefakt auf, das die Trolle aus Zul'Gurub von Beutebucht fern halten könnte.", progress = "Habt Ihr etwas gefunden, {name}?", completion = "Ihr habt sie alle getötet? Ich wünschte, das wäre genug, um mir keine Sorgen mehr zu machen. Aber diese Typen scheinen die Angewohnheit zu haben, von den Toten zurückzukehren.\n\nAh, was habt Ihr denn da?\n\nIhr meint, das könnte sie aus Beutebucht fernhalten?\n\nSo kommen wir ins Geschäft!\n\nOh, sagte ich, dass ich eine Belohnung für Euch habe? Natürlich... gebt mir nur einen Moment, um die Belohnung zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29252] = { id = 29252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Interessen Beutebuchts", description = "Ich wurde von Baron Revilgaz aus Beutebucht hergeschickt, damit ich sicherstelle, dass diese Trollbedrohung aufgehalten wird. Oder dass sie zumindest vor den Toren von Beutebucht aufgehalten wird.\n\nIch will Taten und Ergebnisse sehen.\n\nIhr geht da jetzt für mich rein und veranstaltet ein Gemetzel.\n\nIhr geht da jetzt rein und sucht mir etwas, das diese Trolle aus Beutebucht fernhält.\n\nBringt das zustande und wir werden uns erkenntlich zeigen.", sourceObjective = "Spürt ein Artefakt auf, das die Trolle aus Zul'Gurub von Beutebucht fern halten könnte.", progress = "Habt Ihr etwas gefunden, {name}?", completion = "Ihr habt sie alle getötet? Ich wünschte, das wäre genug, um mir keine Sorgen mehr zu machen. Aber diese Typen scheinen die Angewohnheit zu haben, von den Toten zurückzukehren.\n\nAh, was habt Ihr denn da?\n\nIhr meint, das könnte sie aus Beutebucht fernhalten?\n\nSo kommen wir ins Geschäft!\n\nOh, sagte ich, dass ich eine Belohnung für Euch habe? Natürlich... gebt mir nur einen Moment, um die Belohnung zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29253] = { id = 29253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine glitzernde Beute", description = "Es gibt etwas Plündergut innerhalb der Statue auf der Janeirospitze, gleich nordwestlich von Beutebucht im Schlingendorntal.\n\nBegebt Euch zur Statue und nehmt Euren Preis an Euch, {class}.", sourceObjective = "Holt Euch Eure Belohnung aus einer Kiste in der Statue auf der Janeirospitze.", completion = "Endlich Beute!", sourceObjectiveStatus = "unverified-source-field" }
quests[29254] = { id = 29254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleiner Peitscher", description = "Die kleine rote Blume wackelt zufrieden mit den Ranken. Sie scheint Euch zu mögen!\n\nMöglicherweise würde Avrilla gerne sehen, was aus der Eichel erwachsen ist.", sourceObjective = "Bringt Avrilla den Purpurpeitscher.", completion = "Oh, hallo! Wer ist denn Euer kleiner Freund? Es ist Euch gefolgt, sagt Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[29255] = { id = 29255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glutharz", description = "Der Purpurpeitscher hat auf seinen Ranken einige aufbrechende Blasen entwickelt. Ohne Behandlung könnte dieser Zustand lebensbedrohlich werden.\n\nZum Glück produzieren die verkohlten Soldaten und Bezwinger in dieser Gegend eine wächserne Substanz mit Namen Glutharz, die die Qualen des Peitschers lindern könnte.\n\nBringt mir etwas von dieser Substanz und tötet diese garstigen Feuerelementare, während Ihr dabei seid.", sourceObjective = "Besorgt Euch 5 Portionen Glutharz von verkohlten Soldaten und Bezwingern.", progress = "Der Peitscher wächst sehr schnell.", completion = "Es riecht nicht besonders gut, aber es sollte dem Peitscher wieder auf die Beine helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29256] = { id = 29256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eat Your Heart Out" }
quests[29257] = { id = 29257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magmolien, die ich stahl", description = "Wir haben eine neue Blumenart entdeckt, die in den Magmaquellen im Norden wächst. Erstaunlicherweise leben sie von reiner geschmolzener Lava!\n\nBitte geht und besorgt ein paar Exemplare dieser Pflanze für mich. Ich bin mir sicher, dass weitere Studien an diesen Pflanzen uns Aufschluss geben werden über unseren kleinen Freund hier.\n\nWo ich gerade von ihm spreche: er scheint ganz erpicht darauf zu sein, mit Euch zu gehen. Wollen wir hoffen, dass er sich benimmt.", sourceObjective = "Sammelt 8 Magmolien in den Magmaquellen im Norden.", progress = "Faszinierend! Je mehr Zeit ich in den Feuerlanden verbringe, desto mehr Hinweise erhalte ich, dass hier ein echtes Ökosystem am Werk ist.", completion = "Habt Dank, {name}. Ich werde diese Proben sofort analysieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[29258] = { id = 29258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meteoritenjagd" }
quests[29259] = { id = 29259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hide and Seek", description = "Es ist gut, Euch wiederzusehen, {name}. Euer Peitscher hier hat ein neues Spiel erfunden - ein Versteckspiel!\n\nEs sieht so aus, als wollte er mit Euch spielen.\n\nWartet, bis er sich versteckt und dann sucht ihn im Lager.\n\nFür den Fall, dass er sich zu gut versteckt haben sollte, habe ich einen speziellen Nebel entwickelt, der seine allgemeine Position erkennen lässt. Erzählt ihm bloß nicht, dass ich Euch das gegeben habe.", sourceObjective = "Findet den versteckten Feuerpeitscher in Malfurions Bresche.", sourceObjectiveStatus = "unverified-source-field" }
quests[29260] = { id = 29260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enlighten Us", description = "Euer Feuerpeitscher war recht unruhig. Er hat wiederholt den alten verbrannten Baum besucht, der Grund dafür bleibt mir allerdings schleierhaft.\n\n{name}, würdet Ihr mir einen Gefallen tun und Euren Feuerpeitscher zu dem Baum bringen? Vielleicht findet Ihr ja heraus, was er an dem Ort so interessant findet.", sourceObjective = "Bringt den Feuerpeitscher zu dem verbrannten Baum.", sourceObjectiveStatus = "unverified-source-field" }
quests[29261] = { id = 29261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul'Aman Voodoo" }
quests[29262] = { id = 29262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul'Gurub Voodoo", progress = "Dieser mächtige Haufen Voodoohexenkunst verströmt starkes Mojo...", completion = "Als Ihr die Tafel in den Voodoohaufen steckt, zerreißt ein markerschütternder Schrei die Stille." }
quests[29263] = { id = 29263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine bittere Pille", description = "Soweit es mich betrifft, gibt es kein Problem, das nicht mithilfe von Bomben gelöst werden kann. Und wenn eine Bombe das Problem nicht beim ersten Versuch löst... dann muss man eben eine größere Bombe nehmen.\n\nEs gibt da also diesen großen Wurm, der Leute bei der Lavapfütze im Norden frisst. Haltet Ausschau nach Luftblasen, um ihn zu finden. Greift ihn an, bis er sich bereit macht, zuzubeißen, und platziert dann die Bombe vor ihm. Und dann könnt Ihr Euch zurücklehnen und das Feuerwerk genießen.\n\nHmm... es gab noch eine andere Sache, die ich sagen wollte... Ach ja! Lasst Euch nicht fressen.", sourceObjective = "Findet die Luftblasen des unterirdischen Magmawurms und besiegt ihn dann, indem Ihr ihn die bittere Pille schlucken lasst.", completion = "Ah, ich wusste, dass Rickets Bomben noch einmal nützlich sein würden. Es war nur eine Frage, ob wir etwas ausreichend Großes zum in die Luft sprengen finden würden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29264] = { id = 29264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flammenschürer des Geschmolzenen Stroms", description = "Von allen Dienern Ragnaros' scheinen die Flammenschürer die hingebungsvollsten zu sein. Die meisten von ihnen weilen in dieser Höhle und bereiten sich auf einen weiteren Angriff vor. Wir haben hier vielleicht eine recht sichere Stellung, aber wir werden keine Überraschungsangriffe von diesem Gewürm tolerieren.\n\nNein, wir werden als erste zuschlagen.\n\nReißt sie in Stücke, {name}.", sourceObjective = "Erschlagt 8 Flammenschürer im Geschmolzenen Strom.", completion = "Mir gefällt, wie Ihr arbeitet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29265] = { id = 29265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerblumen", description = "Meine Kollegin, Choluna, hat uns gebeten, alles, was wir an pflanzlichem Leben in den Feuerlanden finden, einzusammeln...\n\n... Ich weiß nicht, wessen Idee es war, Wissenschaftler an eine Kriegsfront zu schicken.\n\nNichtsdestotrotz, da Ihr nun schon mal in der Höhle sein werdet - und Dinge tötet - könnt Ihr auch genauso gut Ausschau nach Dingen halten, die am Boden wachsen.", sourceObjective = "Sammelt 5 Luzifarne.", progress = "Sie können überall wachsen. Haltet die Augen offen.", completion = "Diese Dinge werden nie aufhören, mich in Staunen zu versetzen. Ob sie nun wirklich Pflanzen sind oder einfach nur feingliedrige Steinformationen... der Umstand, dass sie unter solch feindlichen Bedingungen wachsen können, verblüfft mich einfach nur.\n\nIch muss sie sofort an Avrilla zur Analyse schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[29267] = { id = 29267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glück im Unglück", description = "So viel Gewalt, so viel Tod. Brüder sind gestorben, eine Mutter ist gestorben und nun wird ein Pantherjunges sterben, wenn sich niemand seiner annimmt.\n\nWerdet Ihr Euch für einen Moment von der Gewalt abwenden und für ein Pantherjunges sorgen?", sourceObjective = "Das Pantherkätzchen sieht Euch mit einem Ausdruck an, der sagt \"Bist du mein neuer Papa?\"", sourceObjectiveStatus = "unverified-source-field" }
quests[29268] = { id = 29268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glück im Unglück", description = "So viel Gewalt, so viel Tod. Brüder sind gestorben, eine Mutter ist gestorben und nun wird ein Pantherjunges sterben, wenn sich niemand seiner annimmt.\n\nWerdet Ihr Euch für einen Moment von der Gewalt abwenden und für ein Pantherjunges sorgen?", sourceObjective = "Kümmert Euch um das Pantherjunge. Schließlich habt Ihr seine Mutter auf dem Gewissen.", completion = "Das Pantherkätzchen sieht Euch mit einem Ausdruck an, der sagt \"Bist du mein neuer Papa?\"", sourceObjectiveStatus = "unverified-source-field" }
quests[29269] = { id = 29269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vereint", description = "Ich war mit ihrer Sicherheit betraut, und doch war sie es, die sich für mich opferte.\n\nIch ertrage es nicht, sie zu verlieren, {name}. Ich muss Euch eine entscheidende Bitte stellen.\n\nNoch nie hat ein Sterblicher die Essenz eines wahren Drachen getragen, doch mit Eurer Erlaubnis würde ich eine Ausnahme machen.\n\nBitte, solange noch etwas Leben in ihr verweilt, erlaubt mir Tarecgosa an Euch zu binden.", sourceObjective = "Sprecht mit Kalecgos, um der Bitte zuzustimmen.", completion = "Ich bin dankbar, {name}.\n\nWärt Ihr nicht gewesen oder hättet Ihr abgelehnt, wäre Tarecgosa für mich für immer verloren.", sourceObjectiveStatus = "unverified-source-field" }
quests[29270] = { id = 29270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zeit drängt", description = "Tarecgosa ist an Euch gebunden, {name}, aber nur auf begrenzte Zeit. Die Macht eines Aspekts ist von Nöten, um ihre Essenz permanent zu versiegeln.\n\nMalygos' Nachfolger wird nicht vor der nächsten Mondfinsternis Azeroths bestimmt und der Bund, den Ihr mit ihr teilt wird nicht so lange überdauern.\n\nGlücklicherweise gibt es eine Möglichkeit, uns die nötige Zeit zu verschaffen. Es gibt mächtige Elemente, die die Dauer des Rituals verlängern können. Einige davon können in der Ebene des Feuers gefunden werden, mit der Ihr bereits vertraut seid.\n\nBesorgt sie, {class}, und haltet Tarecgosa bis zur Mondfinsternis aufrecht.", sourceObjective = "Sammelt 1000 Einheiten siedender Schlacke aus den Feuerlanden.", progress = "Es tut gut, Euch wiederzusehen, {name}.", completion = "Ich spüre, dass Tarecgosa noch immer bei Euch ist.\n\nDas habt Ihr gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[29271] = { id = 29271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ound for Warmer Weather" }
quests[29272] = { id = 29272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brauche... Wasser... Dringend...", description = "Brauche... Wasser... Dringend...", sourceObjective = "Bringt Anren Schattensucher zum Eingang der Geschmolzenen Front.", completion = "Ihr! Ihr seid derjenige, der Anren gerettet hat. Meinen besten Freund Anren.\n\nWir sind in dieser Höhle getrennt worden. Ich wusste nicht, wie ich ohne Anren weitermachen sollte.\n\nIhr seid ein einfallsreicher {class}. Vielleicht werden wir Euch später noch einmal um Unterstützung bei unseren Erkundungsmissionen bitten. Mit Eurer Hilfe werden Anren und ich möglicherweise nicht länger mit dem entsetzlichen Risiko leben müssen, voneinander getrennt zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29273] = { id = 29273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie heiß", description = "Die Feuerfalken des Schwarzrauchgipfels können unglaublichen Temperaturen widerstehen. Man kann sie sowohl dabei beobachten, wie sie am Himmel ihre Kreise ziehen, als auch dabei, wie sie in flüssiger Lava schwimmen.\n\nStimmt doch, oder, Anren?\n\nWir würden gerne wissen, wie heiß diese Lava werden kann. Der Schwarzrauchgipfel verfügt über drei große Lavaseen. Benutzt dies, um in jedem von ihnen die Temperatur zu messen.", sourceObjective = "Benutzt Tholos Thermometer, um die Temperatur in den drei großen Lavaseen des Schwarzrauchgipfels zu messen.", completion = "Diese Ergebnisse werden uns sehr dabei helfen, die Feuerfalken besser zu verstehen und - noch wichtiger - Alysrazar, ihre neue, feurige Königin.\n\nTholo und ich sind dankbar, dass Ihr uns hier ausgeholfen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29274] = { id = 29274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hunde von Shannox", description = "Auf der größten Insel der Feuerlande haben unsere Truppen Probleme im Kampf gegen Shannox, den Jäger der Flammenschürer. Er verfügt nicht nur über unfehlbare Zielgenauigkeit, sondern er hält sich auch abgerichtete Hunde, die unseren Truppen Ärger ohne Ende bereiten.\n\nTholo, in seiner Weisheit, glaubt, dass es eine gute Idee wäre, die Biologie dieser Hunde zu studieren. Ich stimme natürlich mit Tholo überein.\n\nIhr werdet mehrere Hunde im Geschmolzenen Strom finden, unterhalb des Schmelzofens. Wir werden ihre Asche für unsere Studien benötigen.", sourceObjective = "Sammelt 6 kleine Haufen Asche von Hundeknochen.", progress = "Jede Information, die wir kriegen können, wird hilfreich sein, wenn wir unseren Männern helfen wollen, Shannox zu bezwingen.", completion = "Diese Asche mag genauso aussehen wie alle anderen Arten von Asche, die man auf dieser gottverlassenen Insel findet, aber vertraut mir... Ihr habt das richtige Zeug gefunden.\n\nWir werden es sofort untersuchen lassen.\n\nKehrt bald zurück. Ich verbringe zwar gerne Zeit mit Anren, aber Eure Gesellschaft ist uns auch sehr angenehm, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29275] = { id = 29275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fandrals Methoden", description = "Die Druiden der Flamme... ein Orden von Druiden von dem Tholo und ich bis vor wenigen Wochen noch niemals gehört hatten. Und nun, unter der Führerschaft von Fandral Hirschhaupt, bedrohen sie den Erfolg unserer Mission mit ihrer Herrschaft über das Feuer.\n\nEs scheint, als würden sie einige Ausrüstungsgegenstände in den Feurigen Tiefen aufbewahren, im Nordosten. Wenn es uns gelingt, in den Besitz von einigen Teilen dieser Ausrüstung zu gelangen, haben wir vielleicht mehr Glück, wenn wir den Kampf zu Fandral tragen.", sourceObjective = "Beschafft Euch einen Flammendruidenstab, ein Flammendruidenzauberbuch, einen Flammendruidenreagenzienbeutel sowie einen Flammendruidengötzen.", progress = "Vertraut mir - alle Informationen, die wir hier sammeln, werden uns sehr dabei helfen, zu verstehen, was die Quelle für Fandrals Macht ist.", completion = "Anren, seht was {name} entdeckt hat! Das ist genau das, was wir brauchen!\n\nWir werden einige Zeit brauchen, um diese Ausrüstung anzusehen. In der Zwischenzeit ist Euch unser Dank gewiss.", sourceObjectiveStatus = "unverified-source-field" }
quests[29276] = { id = 29276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flammenspinnenkönigin", description = "Das Gelege der Witwe, im Nordosten, ist nach Beth'tilac benannt, der riesigen Königin der Flammenspinnen. Ihre Netze und ihr Gift sind eine nagende Bedrohung unserer Hauptoffensivkraft.\n\nWir glauben, wenn wir die Flammenspinnen hier an der Geschmolzenen Front studieren, dann können wir diese Information einsetzen, um einen Erfolg gegen Beth'tilac zu erzielen. Setzt alle Euch zur Verfügung stehenden Methoden ein, um Proben ihres Gifts und ihrer Spinnenseidenflüssigkeit zu sammeln und kehrt dann zu meinem getreuen Freund Anren zurück.", sourceObjective = "Sammelt 8 Proben Flammengift und 8 Proben sengende Spinnenseidenflüssigkeit.", progress = "Seid vorsichtig mit diesen Flüssigkeiten, {name}. Wir wollen doch nicht, dass etwas davon verschüttet wird.", completion = "Ihr seid ein echter Gewinn für unsere Sache, {name}. Tholo und ich danken Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[29277] = { id = 29277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Druid Tree, Stage 3 Tracking" }
quests[29278] = { id = 29278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lebendes Obsidium", description = "Habt Ihr diese Feuerbälle gesehen, die vom Himmel kommen? Ich habe gesehen, wie einer von ihnen in die Felder im Norden eingeschlagen ist und das Gestein, was da gelandet ist, bestand aus purem Lebendem Obsidium!\n\nIch kann das Material benutzen, um ultra-robuste, hitzebeständige Rüstung und Waffen für unsere Truppen herzustellen. Könntet Ihr mir das Erz bringen?\n\nGeht zu den Magmaquellen und berührt einen der magnetischen Steine. Passt nur auf, wo Ihr steht, wenn der Feuerregen herunterkommt, und sammelt das Gestein ein, bevor es durch den Aufprall zerbricht.", sourceObjective = "Sammelt 10 Obsidiummeteoriten ein.", progress = "Wie geht es voran? Habt Ihr schon Meteoriten gefunden?", completion = "Fantastisch! Dann kann ich mich ja jetzt an die Arbeit machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29279] = { id = 29279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befüllung des Mondbrunnens", description = "Wir haben diesen Mondbrunnen erschaffen, doch erfüllt er wenig Zweck, solange er noch nicht mit den Wassern des Brunnens der Ewigkeit gefüllt wurde.\n\nMit einem aktiven Mondbrunnen wäre es uns möglich, unsere Lebensmittelvorräte zu segnen, zu denen Ihr selbstverständlich Zugang bekommen würdet. Es sollte uns auch möglich sein, den Segen des Mondbrunnens zu nutzen, um Euch Schutz vor dem Feuer zu gewähren.\n\nSobald Ihr genügend Abzeichen zusammen habt, solltet Ihr mit Matookla am Heiligtum von Malorne sprechen. Sie wird in der Lage sein, für den sicheren Transport des heiligen Wassers zu sorgen.", sourceObjective = "Sammelt 125 Abzeichen des Weltenbaums.", progress = "Wie kann ich Euch helfen, {name}?", completion = "Natürlich. Ich werde mich sofort darum kümmern, dass die heiligen Wasser durch das Portal gebracht werden.\n\nDanke, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29280] = { id = 29280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lebensspendende Wasser", description = "Ich habe die Wasser des heiligen Mondbrunnens zu Malfurions Bresche gesandt, wie Ihr es gewünscht habt. Ayla ist gut darin ausgebildet, sich um sie zu kümmern. Ihr solltet zu ihr zurückkehren und sehen, welche Segen sie für Euch dort bereithält.", sourceObjective = "Sprecht mit Ayla Schattensturm bei Malfurions Bresche.", completion = "Es wird Euch freuen, zu hören, dass die Wasser hier sicher angekommen sind. Nun da der Mondbrunnen gefüllt ist und der Schatten des Wachenden Baums über uns liegt, kann ich manchmal sogar mehrere Momente lang vergessen, dass wir in den Feuerlanden sind.\n\nIch habe den Segen des Mondbrunnens auf diese Bäume und Büsche verteilt. Nehmt die Frucht mit Euch, bevor Ihr geht. Sie ist erfrischender als Ihr Euch vorstellen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29281] = { id = 29281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung", description = "Diesen Druiden fehlen die Werkzeuge, um ihre Aufgaben hier vernünftig zu erledigen. Ich hab' aber 'nen Kumpel beim Schrein des alten Hirschbocks, auf der anderen Seite des Portals. Wenn wir uns wiedertreffen sollten, dann hätten wir sicher ein bisschen Spielzeug, das wir gegen Ragni und seine Kumpane einsetzen könnten.\n\nNehmt einige der Abzeichendinger und geht damit zu Matookla. Fragt sie nach Ricket. Wir brauchen sie hier, damit wir ordentlich Ärger anzetteln können.", sourceObjective = "Sammelt 125 Abzeichen des Weltenbaums.", progress = "Ja, {name}?", completion = "Ich hatte mich schon gefragt, ob sich diese zwei nicht noch als nützlich erweisen würden. Sie schienen recht fehl am Platz zu sein, seitdem sie angekommen sind.\n\nIch habe Ricket vor ein paar Augenblicken hier in der Gegend gesehen. Ich werde sie mit Vergnügen mit Euch zusammen durch das Portal schicken. Auf der Seite wird sie auch weniger Gefahr laufen, das lokale Pflanzenleben in die Luft zu sprengen.\n\nLasst mich mal sehen... wo ist sie...?", sourceObjectiveStatus = "unverified-source-field" }
quests[29282] = { id = 29282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gut bewaffnet", description = "Ricket sollte zusammen mit Damek bei Malfurions Bresche sein, wie von Euch erbeten. Ich bin mir allerdings nicht sicher, dass Ihr wirklich wisst, worauf Ihr Euch mit den beiden einlasst.\n\nWo wir gerade davon sprechen: Ihr solltet vermutlich mal nach ihnen sehen... um sicherzugehen, dass sie es noch nicht geschafft haben, den Wachenden Baum in die Luft zu jagen. So lange Ihr sie mit Elementaren beschäftigt haltet, sollte die Wahrscheinlichkeit von \"Unfällen\" an der Bresche dramatisch sinken.", sourceObjective = "Sprecht mit Ricket bei Malfurions Bresche.", completion = "Hey Ihr! Gut, Euch wiederzusehen!\n\nIch habe mich hier eigentlich schon ganz gut eingelebt! Es ist schön, mal wieder Zeit mit dem guten alten Damek zu verbringen. Ich hätte nie gedacht, dass ich mich mal so gut mit einem Zwerg verstehen würde, aber was die wichtigen Dinge angeht, da liegen er und ich auf derselben Wellenlänge.\n\nMacht Ihr mal Euer Ding und sorgt Euch nicht um uns. Wenn wir irgendwelches nettes Spielzeug für Euch haben, dann werden wir es Euch wissen lassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29283] = { id = 29283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rufen der Urtume", description = "Die Urtume warten in Hyjal. Die Feuerlande werden sich als gefährlicher Ort herausstellen, wenn man ihre... Zusammensetzung bedenkt, aber ihre Stärke wird uns sehr von Nutzen sein, wenn wir uns Ragnaros' Leutnants stellen müssen.\n\nSammelt Eure Abzeichen und sprecht mit Ahnenzweig am Heiligtum von Malorne. Wenn sie an unserer Seite marschieren sollen, so wäre er derjenige, der sie durch das Portal anführen würde.", sourceObjective = "Sammelt 125 Abzeichen des Weltenbaums.", progress = "Seid gegrüßt, junges Wesen.", completion = "Ich verstehe. Wir sind bereit. Wir werden uns dem Zug anschließen und Euch auf der am weitesten entfernten Seite des Portals treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29284] = { id = 29284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe der Urtume", description = "Die Urtume haben den Wert Eurer Weisheit erkannt und sich bei Malfurions Bresche niedergelassen. Ihr solltet Ahnenzweig aufsuchen. Ich bin sicher, er würde sich freuen, von Euch zu hören.", sourceObjective = "Sprecht mit Ahnenzweig bei Malfurions Bresche.", completion = "Ihr habt einen weisen Zeitpunkt ausgewählt, um zu uns zu kommen, {class}. Ich war besorgt gewesen, ob wir in diesem Reich gegen die Elemente bestehen könnten, aber der Schutz des Wachenden Baums hat sich als mehr als ausreichend erwiesen.\n\nWir werden alles tun, um Euch in Euren Bemühungen zu unterstützen. Dorrzweig hat sich mit Euren anderen Verbündeten getroffen und bespricht mit ihnen Wege, einige von Ragnaros' Leutnants in die Ecke zu treiben. Ihr solltet mit ihnen sprechen, wenn die Zeit gekommen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[29285] = { id = 29285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausrichtung", description = "Die Zeit der Wahl ist gekommen, {name}.\n\nObwohl nur Mitglieder des blauen Drachenschwarms dort erlaubt sind, macht die Bindung mit Tarecgosa Eure Anwesenheit dort erforderlich.\n\nIch muss Euch bitten, ihre Form anzunehmen und in ihrem Namen abzustimmen.\n\nTrödelt nicht, der Zeitpunkt der Mondfinsternis ist nahe...", sourceObjective = "Begleitet Kalecgos zum Konzil der blauen Drachen.\n\nSprecht mit Kalecgos in Kaltarra, wenn Ihr bereit seid.", completion = "Arygos' Pläne wurden durchkreuzt, und zwar größtenteils wegen Eurer Mühen, {class}.\n\nAls meine erste Tat als Aspekt des blauen Drachenschwarms wird Euer Bund mit Tarecgosa nun ein stabiler sein.\n\nDie Macht, die diesen Bund einst getragen hat, übertrage ich nun in Euren Stab.\n\nMöge der Runenstab von Nordrassil Euch wohl dienen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29286] = { id = 29286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Druid Tree, Stage 2 Tracking" }
quests[29287] = { id = 29287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gipfel des Interesses", description = "Diese Feuerfalken sind Wesen aus Feuer, aber sie zeigen viel von dem Verhalten, dass wir auch bei den Vögeln in unserer Heimat beobachtet haben. Ich frage mich, was wohl ihr Ursprung sein mag.\n\nAber zurück zum Punkt - ich glaube, es könnte uns gelingen, sie abzurichten. Sie zähmen, wenn Ihr es so sagen wollt. Sie gegen unsere Feinde einsetzen.\n\nIch möchte, dass Ihr Euch eins ihrer Eier vom Schwarzrauchgipfel besorgt. Wenn Ihr es heil zu mir zurückbringt, werde ich mich um den Rest kümmern.", sourceObjective = "Besorgt ein Ei eines Feuerfalken von der Spitze des Schwarzrauchgipfels.", progress = "Ist es Euch gelungen, ein Ei zu besorgen?", completion = "Das wird perfekt funktionieren! Kommt in einem oder zwei Tagen wieder und wir werden sehen, wie sich die Dinge entwickelt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[29288] = { id = 29288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Junges Blut", description = "Unsere Späher kommen mit Berichten von Feuerfalkenjungen überall auf dem Gipfel zurück... ihre Eier müssen also vor Kurzem ausgebrütet worden sein. Und, was noch besser ist: sie scheinen extrem gelehrig zu sein.\n\nIch weiß, es mag sich wie eine seltsame und vielleicht auch geschmacklose Bitte anhören, aber wenn es Euch gelänge, ein paar dieser Jungtiere zu mir zu bringen, dann könnte ich sie vielleicht ausbilden, um uns in unseren Kriegsanstrengungen zu helfen.\n\nSeid Ihr willens?", sourceObjective = "Besorgt Euch 5 Feuerfalkenjunge.", progress = "Ich kann mich einfach nicht entscheiden, wie ich diese Kreaturen sehen soll. Sie verhalten sich genauso wie andere Vögel, aber sie sind ganz offensichtlich an diesem feurigen Ort heimisch.\n\nIch frage mich, warum Ragnaros und seine Diener keine Versuche unternommen haben, sie gegen uns einzusetzen...", completion = "Es sieht so aus, als hätten sie Eure Handschuhe ein wenig angesengt, aber ich sehe ansonsten keine weiteren Schäden. Gut gemacht, {class}.\n\nKommt in den nächsten paar Tagen wieder, um zu sehen, wie es mit der Ausbildung vorangeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[29289] = { id = 29289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sorgen einer Mutter", description = "Wenig überraschend hat die Matriarchin Anstoß daran genommen, dass wir ihre Jungen für unsere eigenen Zwecke ausgebildet haben. Verständlich... und eigentlich ein wenig tragisch. In dieser Sache sind wir die Bösen.\n\nJetzt ist aber nicht die Zeit, über solche Dinge nachzudenken. Diese Kreaturen sind Wesen aus Feuer und bei mehr als einer Gelegenheit haben sie Leben in unseren Reihen gefordert. Nun da ihre Matriarchin verärgert ist, ist die Gefahr immens gewachsen.\n\nIch brauche jemanden, der ihren Zorn besänftigt, und ich fürchte, dass Ihr dazu am fähigsten seid.", sourceObjective = "Bezwingt die Feuerfalkenmatriarchin.", sourceObjectiveStatus = "unverified-source-field" }
quests[29290] = { id = 29290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer am Himmel", description = "Schaut Euch das an! Es ist unglaublich! Gerade mal vor zwei Tagen geboren und schon ausgewachsen. Traurigerweise fürchte ich, dass ihre Lebensdauer entsprechend kurz sein wird, deshalb sollten wir die Zeit ausnutzen, die wir haben.\n\nSeine Ausbildung ist erstaunlich gut verlaufen. Ich möchte, dass Ihr derjenige seid, der ihn auf die Masse an feindlichen Streitkräften loslässt, die sich in der Nähe von Ragnaros' Unterschlupf versammelt haben.\n\nZeigt keine Gnade, {race}.", sourceObjective = "Benutzt den dressierten Feuerfalken, um 100 Flammenschürersalamander, 40 Aschenweberspinnen und 3 geschmolzene Lords, die in den Feuerlanden häufig anzutreffen sind, zu töten.", completion = "Ich nehme an, Euer Angriff war erfolgreich! Großartig. Dies könnte ein Schlüsselmoment im Durchbrechen von Ragnaros' Verteidigung sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[29291] = { id = 29291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Schirm, Charm und Bomben" }
quests[29292] = { id = 29292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falkenfeuer" }
quests[29293] = { id = 29293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesengte Flügel", description = "Viele unserer Sturmkrähen sind vorausgeflogen, um die Spitze auszukundschaften und zu versuchen, einige der Feuerfalkeneier zu besorgen, allerdings mit wenig Erfolg, fürchte ich. Die Thermalwinde machen sicheres Fliegen fast unmöglich und die Feuerfalken sind auch nicht gerade besonders freundlich.\n\nIch möchte, dass Ihr Euch dorthin begebt und so viele Druiden rettet, wie Ihr könnt. Ich habe Schienen, Verbände, Brandsalben, Riechsalze... alles, was Ihr braucht, um ihnen wieder auf die Beine zu helfen, vorausgesetzt, sie leben noch. Bitte beeilt Euch und helft allen, die Ihr finden könnt.", sourceObjective = "Rettet 5 verletzte Druiden der Kralle auf dem Schwarzrauchgipfel.", completion = "Mehrere unserer Brüder und Schwestern sind hier vorbeigekommen, als sie in die Sicherheit des Wachenden Baums zurückkehrten. Ihr habt da draußen sehr gute Arbeit geleistet, {name}. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[29294] = { id = 29294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "nimate Embers" }
quests[29295] = { id = 29295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Je größer...", description = "Ihr wollt Euch ja wohl nicht in DER Ausstattung den feurigen Ungetümen stellen, oder? Wenn Ihr nicht meine aus Obsidium hergestellten Sachen tragt, dann werdet Ihr sofort in Flammen aufgehen! Und selbst wenn Ihr sie tragt, Ihr könnt nie genug von den guten Dingen haben.\n\nSchaut, <Bruder/Schwester>, ich kann Euch die beste Rüstung herstellen, die für Gold zu haben ist, aber ich brauche zuerst reines, unverhüttetes lebendiges Obsidium.\n\nDie Obsidiumbestrafer auf dem Schwarzrauchgipfel bestehen im wahrsten Sinne des Wortes aus dem Zeug. Geht und tötet sie und sammelt ihre Überreste ein.", sourceObjective = "Sammelt 10 Stücke lebendiges Obsidium von den Obsidiumbestrafern auf dem Schwarzrauchgipfel.", progress = "Habt Ihr mir die Waren mitgebracht?", completion = "Das sollte genügen. Gute Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29296] = { id = 29296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Territoriale Vögel", description = "Die Feuerfalken sind aufgebracht über unsere fortgesetzte Anwesenheit. Sie werden langsam extrem feindselig und nicht nur auf die übliche territoriale Art. Ich mache mir Sorgen, dass sie sich schon bald dem Angriff auf unseren Baum anschließen werden, wenn wir sie sich selbst überlassen - und ich bin mir nicht sicher, ob wir in der Lage sein werden, damit umzugehen.\n\nBegebt Euch zum Schwarzrauchgipfel und tut, was Ihr tun müsst, um sie in Schach zu halten. Im Moment ist mir unsere Sicherheit um einiges wichtiger als ihre, handelt also entschlossen.", sourceObjective = "Tötet 5 Feuerfalken.", completion = "Gut gemacht, {name}. Es ist gut zu wissen, dass ich auf Euch zählen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[29297] = { id = 29297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist das Vögelchen?", description = "Hirschhaupts Druiden schlagen an der Wildflammenspitze im Nordosten ordentlich zu.\n\nDie Druiden fliegen in Gestalt von Feuerkrähen über uns und greifen an, wenn wir es am wenigsten erwarten. Das Schlimmste ist, dass sie genau wissen, wie sie außerhalb unserer Reichweite bleiben!\n\nWir wären vollkommen hilflos, wenn mir Damek nicht seine getreue Harpune geliehen hätte. Er sagt, dass diese Waffen gerade und zuverlässig fliegen, selbst in dieser dicken Luft.\n\nNehmt die Waffe des Zwergs und holt ein paar dieser Vögel vom Himmel!", sourceObjective = "Tötet drei Druiden der Flamme, während sie in Feuerkrähengestalt unterwegs sind, mit dem Vogelpikser.", completion = "Diese verdammten Vögel sind tot? Gut, dass wir die los sind!", sourceObjectiveStatus = "unverified-source-field" }
quests[29298] = { id = 29298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verrußtes Medaillon", description = "Auf der Oberseite dieses Medaillons sind einige kleine, blattförmige Schnitzereien zu sehen, aber alle anderen Details haben sich mit der Zeit abgescheuert oder sind durch Feuer verbrannt worden. Es scheint druidischer Natur zu sein.\n\nDie meisten Druiden besuchen die Mondlichtung während ihrer Ausbildung. Wenn Euch jemand dabei helfen kann, die Herkunft dieses Medaillons herauszufinden, dann ist das Rabine Saturna in Nachthafen.", sourceObjective = "Bringt das verrußte Medaillon zu Rabine Saturna in Nachthafen auf der Mondlichtung.", progress = "Ja, junger {race}?", completion = "Was haben wir denn da? Eine Halskette? Nein, ein Medaillon...\n\nOh je...", sourceObjectiveStatus = "unverified-source-field" }
quests[29299] = { id = 29299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manche mögen's heiß", description = "Ich bin in meinen Studien vorangekommen, {name}. Basierend auf den Dingen, die wir in der lokalen Flora beobachtet haben, ist es durchaus möglich, dass Euer Peitscher auch supererhitzte Flüssigkeiten als Hauptnahrungsquelle verträgt.\n\nIch hätte gerne, dass Ihr mir bei einem kleinen Experiment helft. Die Glutspeiskorpione, die in den Magmaquellen im Norden hausen, versprühen im Kampf brennende Feuerlachen.\n\nNehmt den Peitscher und beobachtet seine Reaktion auf die Glutlachen der Skorpione.", sourceObjective = "Beobachtet den Purpurpeitscher, wenn er von 6 Glutlachen trinkt. Glutlachen entstehen durch den Kampf gegen Glutspeiskorpione.", completion = "Hat es funktioniert? Meine Theorie war also korrekt?", sourceObjectiveStatus = "unverified-source-field" }
quests[29302] = { id = 29302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufdecken verborgener Geheimnisse", description = "Die Initialen auf dem Medaillon scheinen verblasst zu sein, aber ich kann eine Macht darin spüren, die auf nur einen möglichen Besitzer schließen lässt:\n\nLeyara, die Druidin der Flamme.\n\nTretet zurück und wir werden sehen, welche Überraschungen dieses Medaillon bereithält.", sourceObjective = "Beobachtet die in dem verrußten Medaillon gespeicherten Erinnerungen.", completion = "Wenn Leyara den Krieg der Sandstürme miterlebt hat, dann ist es wahrscheinlich, dass sie Fandral kannte - und seinen verstorbenen Sohn, Valstann - und zwar sehr viel näher, als wir jemals vermutet hätten.\n\nEs scheint, dass Eure Reise hier noch nicht endet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29303] = { id = 29303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tragödie und Familie", description = "Es war sehr einsichtsvoll von Euch, mir dieses Medaillon zu bringen, {name}. Ich bin einer der wenigen, die wissen, wo Valstanns Leichnam begraben ist.\n\nIhr findet seine letzte Ruhestätte auf einem kleinen Friedhof, südöstlich von Astranaar im Eschental. Bringt dieses Medaillon zu dem Ort und vielleicht eröffnet es Euch weitere Erinnerungen.\n\nLebt wohl, {name}, und viel Glück für Eure Reise.", sourceObjective = "Bringt das verrußte Medaillon zu dem nachtelfischen Grab in der Nähe von Astranaar im Eschental.", sourceObjectiveStatus = "unverified-source-field" }
quests[29304] = { id = 29304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hunde des Krieges", description = "Unsere Truppen werden von entfesselten Monstrositäten in die Knie gezwungen - Aschenhunde aus den geschmolzenen Tiefen.\n\nDiese Hunde fürchten nichts und niemanden und werden nicht innehalten, bis ihr Blutdurst befriedigt ist. Unsere Streitkräfte können sie gerade so zurückhalten.\n\nGeht und schließt Euch den Verteidigern auf den Aschenfeldern oder im Geschmolzenen Strom an. Vielleicht gelingt es Euch, ihre Anzahl ein wenig zu reduzieren.", sourceObjective = "Tötet 5 Aschenhunde oder uralte Aschenhunde.", completion = "Gut, {class}. Der Feind mag hart sein, aber Ihr habt heute bewiesen, dass Ihr härter seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[29305] = { id = 29305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Stich ins Herz", description = "Einer von Ragnaros' Leutnants hat sich auf Ragnaros' Ebenen gezeigt, dem von Mauern umgebenen Bereich im Nordosten von uns.\n\nIch hatte gehofft, Euch direkt nach Eurer Rückkehr wieder aussenden zu können, aber ich fürchte, dass Dorrzweig und einige unserer Streitkräfte sich bereits in die Schlacht gestürzt haben. Ihr solltet Euch beeilen.\n\nEs sollte Euch möglich sein, diese Klippe direkt hier hinunterzuspringen und sie so schnell zu erreichen.", sourceObjective = "Tötet den Leutnant der Flamme.", completion = "Sehr gut gemacht, {name}! Das sollte sie erheblich hemmen.\n\nWenn wir das durchhalten, sollten wir den Kampf leicht zu Ragnaros selbst tragen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[29307] = { id = 29307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herz der Flamme", description = "Ihr seid <der/die> erste Sterbliche, <der/die> einem Drachenkonzil beiwohnt und gehört zu den einzigen Wesen in Azeroth, die an der Wahl eines Aspekts teilnehmen.\n\nMein Aufstieg hat mich mit unglaublicher Macht erfüllt. Ich habe mir erlaubt, Tarecgosas Band mit Euch zu stärken, obschon sie ein... permanenteres Zuhause benötigt.\n\nIch möchte, dass Ihr ein letztes Mal in die Ebene des Feuers reist und mir das Herz von Ragnaros bringt.\n\nWenn wir uns das nächste Mal begegnen, werde ich Euch angemessen für alles, was Ihr getan habt, belohnen können.", sourceObjective = "Verstärkt den Runenstab von Nordrassil mit 250 schwelenden Essenzen und besorgt Euch das Herz der Flamme.", progress = "Ein feiner Tag für eine Zeremonie. Findet Ihr nicht, {name}?", completion = "Ihr habt Großes geleistet, {name}.\n\nBereitet Euch nun darauf vor, die Belohnung eines Helden zu empfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29308] = { id = 29308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herz der Flamme", description = "Ihr seid <der/die> erste Sterbliche, <der/die> einem Drachenkonzil beiwohnt und gehört zu den einzigen Wesen in Azeroth, die an der Wahl eines Aspekts teilnehmen.\n\nMein Aufstieg hat mich mit unglaublicher Macht erfüllt. Ich habe mir erlaubt, Tarecgosas Band mit Euch zu stärken, obschon sie ein... permanenteres Zuhause benötigt.\n\nIch möchte, dass Ihr ein letztes Mal in die Ebene des Feuers reist und mir das Herz von Ragnaros bringt.\n\nWenn wir uns das nächste Mal begegnen, werde ich Euch angemessen für alles, was Ihr getan habt, belohnen können.", sourceObjective = "Verstärkt den Runenstab von Nordrassil mit 250 Essenzen der Seelenflamme und besorgt Euch das Herz der Flamme.", progress = "Ein feiner Tag für eine Zeremonie. Findet Ihr nicht, {name}?", completion = "Ihr habt Großes geleistet, {name}.\n\nBereitet Euch nun darauf vor, die Belohnung eines Helden zu empfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29309] = { id = 29309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stoff, aus dem Legenden sind", description = "Es ist eine Ehre, Euch kennen zu lernen, {race}.\n\nEure Taten sind bei den Kreaturen Azeroths in aller Ohren, sowohl sterblich als auch unsterblich.\n\nIch werde Kalecgos nach seiner Ankunft das Herz von Ragnaros präsentieren. Seine Macht wird dazu verwendet werden, Eure Waffe noch zu verstärken.\n\nDie Zeremonie beginnt in Kürze. Ich wurde dazu ernannt, Euch dort hinzuführen, sobald Ihr bereit seid.", sourceObjective = "Sprecht mit Hallegosa.", progress = "Seht! Drachenzorn, Tarecgosas letzte Ruhe.", completion = "Eure Heldentaten werden nie vergessen werden, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29310] = { id = 29310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Trendwende", description = "An dem Tag, an dem Leyara Hamuul angriff, hat sie in der Nähe von einigen Ruinen am Hyjal gewartet, nordwestlich des Geheilten Hyjal. Sie hat sich zu der Zeit seltsam verhalten: gefasst, ruhig und mit Blick in die Ferne. Möglicherweise ist der Ort für sie wichtig.\n\nDas Medaillon könnte vielleicht reagieren, wenn es an diesen Ort gebracht wird.", sourceObjective = "Bringt das verrußte Medaillon zu dem kleinen Grabstein bei Leyaras Trauer beim Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[29311] = { id = 29311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Rest ist Geschichte", description = "In ihren Erinnerungen hat Leyara von Malfurion gesprochen. Die Tragödien ihrer Vergangenheit sind - zumindest ihrer Meinung nach - hauptsächlich seinen Handlungen geschuldet.\n\nMalfurion muss sich an Leyara erinnern, bevor sie eine Druidin der Flamme wurde. Ihr entschließt Euch, ihm das Medaillon in die Feuerlande zu bringen. Hoffentlich kann er alle offenen Fragen beantworten.", sourceObjective = "Bringt das verrußte Medaillon zu Malfurion an der Geschmolzenen Front.\n\nBereitgestellter Gegenstand:", completion = "Ja, ich kannte Leyara und ich war mir ihres Zorns bewusst, selbst bevor sie sich den Druiden der Flamme anschloss. Einst war sie eine vielversprechende junge Druidin. Leider sind Familienbande oft stärker als die Macht der Vernunft und letztendlich hat sie sich dafür entschieden, Fandral auf seinem verräterischen Pfad zu folgen.\n\nIhr solltet dieses Medaillon behalten, {name}. Möge es Euch daran erinnern, dass jeder von uns auf seinem eigenen Pfad durchs Leben geht... und dass einige Pfade einfacher sind als andere.", sourceObjectiveStatus = "unverified-source-field" }
quests[29312] = { id = 29312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stoff, aus dem Legenden sind", description = "Es ist eine Ehre, Euch kennen zu lernen, {race}.\n\nEure Taten sind bei den Kreaturen Azeroths in aller Ohren, sowohl sterblich als auch unsterblich.\n\nIch werde Kalecgos nach seiner Ankunft das Herz von Ragnaros präsentieren. Seine Macht wird dazu verwendet werden, Eure Waffe noch zu verstärken.\n\nDie Zeremonie beginnt in Kürze. Ich wurde dazu ernannt, Euch dort hinzuführen, sobald Ihr bereit seid.", sourceObjective = "Sprecht mit Hallegosa.", progress = "Seht! Drachenzorn, Tarecgosas letzte Ruhe.", completion = "Eure Heldentaten werden niemals in Vergessenheit geraten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29313] = { id = 29313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geheimnis des perfekten Kimchis", description = "Meine Familie stellt seit der Gründung der Stadt das beste Kimchi in ganz Darnassus her, {name}. Das Geheimnis ist eine ganz einfache Sache, aber sie macht den ganzen Unterschied.\n\nWir vergraben die Krüge im Boden, bis der Inhalt bereit ist, serviert zu werden, und die letzte Ladung hat gerade diesen Punkt erreicht. Ihr könnt die Krüge überall in der Stadt in Erdhügeln vergraben finden. Würdet Ihr mir helfen, sie einzusammeln, solange ihr Inhalt genau richtig ist?", sourceObjective = "Findet 8 vergrabene Kimchikrüge in Darnassus.", progress = "Habt Ihr die Krüge gefunden?", completion = "Habt Dank, {name}. Ich hätte sie nie alle rechtzeitig finden können und es wäre doch schade gewesen, so viel gutes Kimchi zu verpassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29314] = { id = 29314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gedenkt der Vorfahren", description = "Die Lebenden sind nicht die Einzigen, die Nahrung brauchen. Eine meiner Pflichten besteht darin, die Reiskuchen zuzubereiten, die den Vorfahren dargebracht werden. Normalerweise hat meine oberste Schülerin die Ehre, die Kuchen zum Tempel des Mondes zu bringen, damit sie dort gesegnet werden, und sie dann den Vorfahren darzubieten. Würdet Ihr, da sie heute nicht in der Stadt ist, diese Pflicht an ihrer Stelle übernehmen?", sourceObjective = "Sammelt die gesegneten Reiskuchen aus dem Tempel des Mondes ein.", progress = "Dies ist der Schrein, von dem der Ausbilder gesprochen hat.", completion = "<Ihr plaziert die Reiskuchen um den Schrein herum, der anfängt, sanft zu leuchten. Euch überkommt ein mildes Gefühl der Dankbarkeit.>", sourceObjectiveStatus = "unverified-source-field" }
quests[29315] = { id = 29315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fungourmet", description = "Manche Köche beschweren sich darüber, dass unsere geliebte Unterstadt nicht mit den nötigen Zutaten aufwarten kann, um wahrhaftig köstliche Speisen zuzubereiten.\n\nWas für jammernde Einfaltspinsel. Dabei gibt es hier doch solche Köstlichkeiten!\n\nSammelt einige der ranzigen, schleimigen Abflusskappen, die entlang der Nordwestkanäle der Unterstadt wachsen und bringt sie zu mir.", sourceObjective = "Besorgt 12 Abflusskappen. Liefert die Pilze bei Eunice Burch in Unterstadt ab.", progress = "Habt Ihr genügend Abflusskappen finden können?", completion = "Die riechen ja einfach nur widerlich. Perfekt!", sourceObjectiveStatus = "unverified-source-field" }
quests[29316] = { id = 29316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grundnahrungsmittel", description = "Es gibt bestimmte Dinge, die jeder braucht, vom Koch im kleinsten Haushalt bis zum obersten Küchenchef. Eines der wichtigsten Grundnahrungsmittel der Stadt ist Reismehl. Die meisten Familien haben mindestens einen Korb Reis in ihrem Haus und das gilt genauso für die Bewohner der Terrassen der Handwerker und der Händler.\n\nIch trage meinen Schülern oft auf, dabei zu helfen, Reis in Mehl zu verwandeln, da es eine gute Übung und eine Endlosaufgabe ist. Warum versucht Ihr es nicht einmal?", sourceObjective = "Helft den Bewohnern der Terrasse der Handwerker und der Terrasse der Händler Reis in Mehl zu verwandeln, indem Ihr den Inhalt der Reiskörbe zermahlt.", completion = "Nur durch viel Fleiß und Mühe können wir sicherstellen, dass es genügend Mehl für alle gibt. Danke für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29317] = { id = 29317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fischkopp", description = "Es hat einen... Vorfall mit einer Orcwache und einer von Apothekermeister Faranells Monstrositäten gegeben.\n\nOffenbar hat der Aufseher der Kor'kron ihr kurzerhand den Kopf abgeschlagen und ihn in den Schleim getreten.\n\nFaranells Lehrlinge suchen schon seit Stunden danach, können das Ding aber einfach nicht finden. Würdet Ihr versuchen, nach ihm zu angeln? Ich bin sicher, dass der alte Knabe sehr dankbar wäre.", sourceObjective = "Armand Kromwell möchte, dass Ihr für Apothekermeister Faranell einen abgetrennten Monstrositätenkopf aus den Kanälen von Unterstadt angelt.", progress = "Ihr habt nicht rein zufällig einen abgetrennten Monstrositätenkopf gesehen, oder...?", completion = "Ah! DA ist er ja! Wie habt Ihr ihn nur gefunden?\n\nNun, ganz gleich. Meine Schüler waren nicht in der Lage, den Kopf zu finden, obwohl sie stundenlang im Schleim herumgeplantscht haben. Aber dabei haben sie IMMERHIN diesen Beutel mit Glitzerkram gefunden... vielleicht könnt Ihr ja mit dem Inhalt etwas anfangen?\n\nIch danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[29318] = { id = 29318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rippchen für die Schildwachen", description = "Einer meiner Verantwortungsbereiche umfasst die Verpflegung der Schildwachen von Darnassus, wenn sie im Dienst sind. Diese Aufgabe kostet Zeit, aber es ist eine, die ich gerne erledige. Würde es Euch etwas ausmachen, mir beim heutigen Essen zu helfen? Nehmt einfach diese Rippchen, bereitet sie in einem Herd oder über einem Feuer zu und verteilt sie unter den Schildwachen in der Stadt.", sourceObjective = "Benutzt die rohen Rippchen in der Nähe eines Herdes oder Lagerfeuers, um sie zu kochen und benutzt sie dann, um 5 Schildwachen von Darnassus zu verpflegen.", completion = "All diese Schildwachen zu verköstigen ist mit Eurer Hilfe viel einfacher. Diesmal musste sich niemand für sein Essen anstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29319] = { id = 29319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaulquappen des Todes", description = "Einige unserer Apotheker haben es sich zur Gewohnheit gemacht, ihren etwas bedenklicheren chemischen Müll in den Stillwassertümpel zu kippen und... nun, sagen wir einfach, dass niemand so genau wissen möchte, wie groß mutierte fleischfressende Kröten werden können.\n\nWärt Ihr bereit, ein paar riesige fleischfressende Kaulquappen zu fangen, bevor es so weit kommt? Fasst sie nur besser nicht mit bloßen Händen an.", sourceObjective = "Armand Kromwell in Unterstadt möchte, dass Ihr ihm 8 riesige fleischfressende Kaulquappen bringt.", progress = "Habt Ihr ein paar mutierte Kaulquappen finden können? Ihr solltet sie besser nicht mit bloßen Händen anfassen.", completion = "Ausgezeichnete Arbeit, {name}. Ich sorge dafür, dass sie sofort... verwahrt werden.\n\nWas könnten unsere wunderbaren Apotheker denn auch mit einer Armee monströser, giftspuckender, fleischfressender Superkröten anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29320] = { id = 29320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein toller Hecht", description = "Ihr habt doch schon im Blendwassersee geangelt, oder?\n\nDer größte Fang in dem See ist, einen der riesigen leichengefütterten Hechte an Land zu ziehen. Sie beißen allerdings nur bei einer ganz besonderen Ködersorte an... Leichenwürmer.\n\nSucht bei den Gräbern im Innenhof an der Oberfläche. Dort solltet Ihr welche finden können.", sourceObjective = "Grabt einen Leichenwurm im Innenhof der Ruinen von Lordaeron aus und benutzt ihn als Köder um einen leichengefütterten Hecht zu fangen. Leichengefütterte Hechte gibt es im Blendwassersee, nordöstlich von Unterstadt.", progress = "Schon den Hecht gefangen?", completion = "Das ist ein toller Hecht, {name}. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[29321] = { id = 29321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muscheltaucher", description = "Es scheint, als würden alle, die ich kenne, Muscheln lieben, aber ich kann ihren Anblick nicht ertragen! Sie riechen schlecht und sind schleimig und um sie zu ernten, muss man im Matsch graben. Da würde ich einer Angel und ein bisschen Köder doch jeden Tag den Vorzug geben.\n\nTrotzdem möchte ich meinen Bruder mit einem Eimer frischer Muscheln überraschen. Euch winkt eine Belohnung, wenn Ihr Euch bereit erklärt, mir diese Muscheln zu beschaffen.\n\nGeht einfach durch das Portal nach Rut'theran und sucht in den seichten Stellen am Ufer nach Muscheln.", sourceObjective = "Sammelt 10 Teldrassilmuscheln von den Ufern in der Nähe von Rut'theran.", progress = "Habt Ihr genug Muscheln gefunden?", completion = "Igitt, die sehen so eklig aus, aber mein Bruder mag sie am liebsten. Danke, dass Ihr mir diese unangenehme Aufgabe abgenommen habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[29322] = { id = 29322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schleim-Time", description = "Es braucht schon eine ganz besondere Art von Angler, um die Schätze der blubbernden Schleimkanäle von Unterstadt wertzuschätzen. Meint Ihr, Ihr könnt ein paar der zuckenden Schleimschimmel einsammeln, die dort unten herumkriechen?\n\nIhr könnt versuchen, sie zu angeln, aber sie sind verschlagen; vielleicht wäre es einfacher, ein Schleimbad zu nehmen und sie einfach zu packen.\n\nDenkt daran, dass sie uns nur lebendig und intakt etwas nützen... Wer möchte schon gern tote Schleimschimmel essen?! Widerwärtig.", sourceObjective = "Sammelt 10 zuckende Schleimschimmel. Liefert sie bei Armand Kromwell in Unterstadt ab.", progress = "Gar nicht so einfach zu fangen, was?", completion = "Diese Schleime sehen perfekt aus. Ich schicke sie auf den Weg zu Eunice, damit sie sie zubereitet. Vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[29323] = { id = 29323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstockung", description = "Wir haben die meisten unserer Lebensmittelvorräte benutzt, um diejenigen zu versorgen, deren Häuser und Lebensgrundlagen zerstört wurden. Wenn wir unsere Vorräte nicht wieder aufstocken, werden wir alle in Gefahr sein, wenn das nächste Mal ein schlimmer Sturm oder eine Invasion der Horde über uns hereinbricht.\n\nVielleicht seid Ihr bereit, mir dabei zu helfen, unsere Bestände an Seefelchen wieder aufzufüllen. Ihr könnt sie überall in Darnassus fangen und sobald sie getrocknet sind, halten sie sich, bis sie gebraucht werden.", sourceObjective = "Fangt 5 Seefelchen, indem Ihr in Darnassus angelt.", progress = "Wenn all unsere Fischer mit anpacken, dann wird es nicht lange dauern, bis wir unsere Vorräte wieder aufgefüllt haben.", completion = "Die sind prächtig! Danke, {name}. Ich hänge sie zum Trocknen auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[29324] = { id = 29324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Anhänger der Schwester", description = "Habt Ihr schon Schwester Aquinne kennengelernt? Sie und ich wurden gemeinsam in Dolanaar geschult und sie ist vor kurzem in der Stadt angekommen, um im Tempel des Mondes ausgebildet zu werden. Wir haben eine Bootsfahrt gemacht, aber der ungeschickte Ruderer hat das Boot zum Kentern gebracht!\n\nAls wir wieder am Ufer waren, war Aquinnes Anhänger verschwunden. Die Seen von Darnassus sind voll von riesigen Welsen, die alles verschlucken, was glänzt.\n\nIch habe ohne Pause nach ihnen geangelt und gehofft, dass ich einen mit ihrem Anhänger finde. Wollt Ihr mir vielleicht helfen?", sourceObjective = "Erhaltet Aquinnes Mondanhänger aus dem Magen eines riesigen Welses. Ihr solltet sie an jeder Angelstelle in Darnassus fangen können.", progress = "Konntet Ihr Aquinnes verlorenen Anhänger finden? Ich muss schon etwa fünfzig dieser Monster gefangen haben und habe nicht die geringste Spur!", completion = "<Astaia nimmt Euch den Anhänger ab.>\n\nUnter all dem Schleim und Anlauf glaube ich, es wiederzuerkennen! Aquinne wird sich so freuen, es wiederzubekommen... natürlich nachdem ich es gründlich gereinigt habe. Ich kann Euch nicht genug danken, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29325] = { id = 29325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein glitschiger Snack", description = "Habt Ihr schon einmal Oktopusfleisch gegessen? Es ist etwas gewöhnungsbedürftig, aber es ist mein Leibgericht! Ich kenne sogar Leute, die die Dinger am Stück und lebendig essen!\n\nIch habe nicht vor, das bald auszuprobieren, aber mir sind gerade die frischen Oktopusse ausgegangen. Helft Ihr mir, neue zu bekommen? Sie leben im seichten Wasser an der Küste von Rut'theran.", sourceObjective = "Sammelt 6 Babyoktopusse aus dem seichten Wasser in der Nähe von Rut'theran.", progress = "Es ist unmöglich, Oktopusse mit einer Rute zu fangen. Ihr müsst sie einfach packen!", completion = "Die werden köstlich sein, das weiß ich jetzt schon! Danke, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[29326] = { id = 29326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Nordrassilgipfeltreffen", description = "Hallo, {class}! Meine Brüder und Schwestern vom Irdenen Ring haben Gutes über Eure Taten nach dem Kataklysmus zu berichten gewusst. Doch noch immer muss vieles getan werden, wenn diese zerbrochene Welt geheilt werden soll.\n\nBegleitet mich ein paar Schritte. Vorbereitungen für eine Zeremonie sind im Gange, für ein Ritual, von dem ich hoffe, dass es der Wendepunkt in unserem Kampf gegen den Schattenhammer darstellen wird.\n\nSobald alles abgeschlossen ist, werdet Ihr das Wort über unseren Triumph hier in die Welt tragen können.", sourceObjective = "Sprecht mit Thrall unter dem Weltenbaum am Hyjal und beobachtet die Zeremonie des Irdenen Rings.", completion = "Es kann nicht vorbei sein. Wir dürfen die Hoffnung nicht aufgeben!", sourceObjectiveStatus = "unverified-source-field" }
quests[29327] = { id = 29327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementare Bande: Zweifel", description = "Ich kenne denjenigen, nach dem Ihr sucht... aber ich weiß nicht, ob es weise von Euch ist, ihm zu folgen. Er hat sich selbst in den Zyklon gestürzt. Die Winde zehren nun an seinem Körper und seinem Geist, zweifellos lassen sie nichts zurück als Fetzen und Zweifel.\n\nHinter ihm herzujagen würde Euch nur demselben Schicksal aussetzen. Der schneidende Wind lässt nichts unberührt.\n\nIhr seid gewarnt worden. Was habt Ihr jetzt vor?", sourceObjective = "Sprecht mit Zyklonas, um eine sichere Passage zu Thrall zu bekommen. Kämpft dann mit den Windelementaren, die ihn peinigen, bis er frei ist.", progress = "Bleibt wachsam, {name}! Gebt Go'el nicht auf.", completion = "Was ist dieses... Wasser?", sourceObjectiveStatus = "unverified-source-field" }
quests[29328] = { id = 29328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementare Bande: Verlangen", description = "Noch einmal, {class}, ich schaffe es nicht ohne Eure Hilfe. Ich werde versuchen, den Sturm zu besänftigen, aber Ihr werdet die instabilen Elementare zurückdrängen müssen, die darum herumwirbeln. Nur dann können wir Go'el befreien!", sourceObjective = "Vernichtet die Fluten des Verlangens und die Wirbel des Verlangens in der Nähe des Wirbelnden Abgrunds, bis Thrall aus ihren Fängen befreit ist.", completion = "Luft, Wasser... und jetzt Erde?", sourceObjectiveStatus = "unverified-source-field" }
quests[29329] = { id = 29329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementare Bande: Geduld", description = "Mit dem Segen der Steinmutter kann ich uns dahin bringen, wo Go'el gefangen gehalten wird.\n\nWir müssen vorsichtig sein. Der Schattenhammer verfügt überall über Agenten. Helft mir, sie zurückzuhalten, während ich versuche, zu Go'el durchzukommen!\n\nSprecht mit mir, wenn Ihr bereit seid, und ich werde Euch zu ihm bringen.", sourceObjective = "Sprecht mit Aggra, wenn Ihr bereit seid, Thrall zu helfen. Bezwingt dann die Elemente und Kernsteine der Geduld, die ihn gefangen halten.", completion = "<Aggra ballt ihre Fäuste und starrt auf die Stelle, an der Thrall noch vor wenigen Augenblicken stand.>", sourceObjectiveStatus = "unverified-source-field" }
quests[29330] = { id = 29330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementare Bande: Zorn", description = "Die Totems, {name}! Wir müssen sie aktivieren oder Go'el ist verloren!\n\nTötet die Elementare neben jedem meiner Totems, die an den Kanten dieses Plateaus platziert sind. Sobald alle vier Totems aktiviert sind, sollte es uns möglich sein, das letzte Stück von Go'els Seele zu befreien!", sourceObjective = "Tötet Feuerelementare neben Aggras Lufttotem an der westlichen Kante des Plateaus, bis es aktiviert ist. Macht dann bei Aggras Wassertotem, Aggras Erdtotem und Aggras Feuertotem weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[29331] = { id = 29331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementare Bande: Das Gelübde", description = "Bevor er durch das Portal zum Hyjal trat, hat Thrall Euch gebeten, ihm zu folgen. Es gibt da etwas, von dem er möchte, dass Ihr es seht.", sourceObjective = "Sprecht mit Thrall bei Nordrassil auf dem Hyjal.", completion = "Ich danke Euch – ich lebe erneut! Und dank der gemeinsamen Anstrengungen des Zirkels des Cenarius und dem Irdenen Ring wird der Weltenbaum ebenfalls neues Leben nach Azeroth bringen.\n\nWährend wir uns weiterhin um Todesschwinge und den Rest unserer Feinde kümmern müssen, möchte ich gerne etwas mit Euch teilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29332] = { id = 29332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leckere Lilien", description = "Die Lilien, die um den Stillwassertümpel herum wachsen, lassen sich zu einer köstlichen Suppe verkochen.\n\nNun ja... \"köstlich\" in dem Sinne, dass nicht sofort jedem Orc schlecht wird, der sie trinkt.\n\nWarum sammelt Ihr nicht ein paar für mich, hmmm? Gebt nur gut auf die riesigen fleischfressenden Kaulquappen Acht.", sourceObjective = "Besorgt 10 Stillwasserlilien. Liefert die Pflanzen bei Eunice Burch in Unterstadt ab.", progress = "Habt Ihr genügend Stillwasserlilien finden können?", completion = "Ah, so eine üppige Ladung Lilien. Bravo! Ich koche sie sofort ein...", sourceObjectiveStatus = "unverified-source-field" }
quests[29333] = { id = 29333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneckt lecker!", description = "Die Orcwachen beschweren sich ständig über fade, schimmlige Kost in Unterstadt - als ob WIR etwas dafür könnten, dass sie sich nicht von Pilzen und alten Leichen ernähren können - also finde ich, dass es an der Zeit ist, dass sie herausfinden, was für exotische Köstlichkeiten wir zubereiten können, wenn wir wollen.\n\nSammelt ein paar Süßwasserschnecken aus dem Blendwassersee und ich zeige ihnen, was eine wahre kulinarische Meisterin zaubern kann.", sourceObjective = "Sammelt 8 Blendwasserschnecken. Liefert sie bei Eunice Burch in Unterstadt ab.", progress = "Schon die Süßwasserschnecken gesammelt?", completion = "Ihr müsst ein guter Schwimmer sein... Ich kann höchstens Toter-Mann spielen.\n\nWie dem auch sei, Ihr habt da ein hervorragendes Bündel Schnecken gesammelt. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[29334] = { id = 29334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wahres Schabsal", description = "Bei all dem Gemecker, das diese Aufseher der Kor'kron für die Verpflegung in Unterstadt übrig haben, gibt es eine Sache, die sie schaufelweise essen: der dreifach gewürzte Knuspereintopf meiner Schwester.\n\nWeil er so beliebt ist, gehen ihr ständig die Zutaten aus. Würdet Ihr ein paar zu ihr zum Wagen bringen, aus dem sie den Eintopf verkauft?\n\nÜberall in der Stadt werdet Ihr Fallen finden; bringt einfach deren Inhalt zu Audrey und sie kümmert sich um den Rest!", sourceObjective = "Beschafft 20 träge Kakerlaken. Liefert die Insekten bei Chefköchin Audrey in Unterstadt ab.", progress = "Ich nenne meine kleinen Fallen \"Kakerlabinen\".\n\nKakerlaken spazieren hinein, sie spazieren aber nicht wieder heraus.", completion = "Gerade noch rechtzeitig bevor meine Vorräte erschöpft waren. Danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[29335] = { id = 29335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die beißenden Winde", description = "{class}, ich weigere mich zu glauben, dass mein Go'el für immer verloren ist. Sein Geist ist über die Elementarebene zerstreut worden. Sollte auch nur ein Teil von ihm noch existieren, dann können wir ihn finden, ich brauche allerdings Eure Hilfe.\n\nWir werden mit der Ebene der Luft beginnen.\n\nSprecht mich erneut an und wir werden gemeinsam zum Vortexgipfel reisen. Wir müssen mit einem Elementar namens Zyklonas sprechen. Ein launischer Geselle, aber im Reich der Luft sieht er alles. Wenn mein Liebster dort sein sollte, so wird Zyklonas wissen, was mit ihm geschehen ist.", sourceObjective = "Sprecht mit Zyklonas auf dem Felsen des Südwinds in Uldum.", completion = "<Ihr spürt, wie der Wind über Eure Arme fegt, über Euer Gesicht, Eure Waffen und Rüstung...>\n\n<Zyklonas inspiziert Euch.>", sourceObjectiveStatus = "unverified-source-field" }
quests[29336] = { id = 29336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die drängenden Fluten", description = "Go'el muss sich auf der Ebene des Wassers befinden... im Meeresschlund selbst! Mich fröstelt, wenn ich mir vorstelle, was ihn dort erwartet.\n\nFindet den Elementar Hydrius, in der Nähe des Wirbelnden Abgrunds. Er weiß von Go'el und sympathisiert mit unserem Kampf gegen Ragnaros. Wenn Euch jemand dort helfen kann, dann er.\n\nIch werde Euch unter den Strömen Vashj'irs treffen, {race}...", sourceObjective = "Sprecht mit Hydrius beim Wirbelnden Abgrund in den Abyssischen Tiefen von Vashj'ir.", completion = "Ich werde tun, was ich kann, um Euch zu helfen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29337] = { id = 29337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die beständige Erde", description = "Die Zeit ist knapp! Mein Liebster liegt in Tiefenheim. Ich werde uns dorthin bringen, sobald Ihr bereit seid, und wir werden mit Therazane, der Steinmutter, sprechen.", sourceObjective = "Sprecht mit Therazane bei Therazanes Thron in Tiefenheim.\n\nAggra kann Euch vom Wirbelnden Abgrund aus zu Therazanes Thron teleportieren.", completion = "Ich weiß bereits, wonach Ihr sucht, Fleischlinge. Und ich habe mich entschieden, Euch zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29338] = { id = 29338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die unnachgiebige Flamme", description = "Wir müssen nun zu den Feuerlanden reisen. In diesem Reich kann Go'els brennender Geist so fürchterlich wie Ragnaros selbst werden! Macht Euch bereit, da er allein in einer feindlichen Welt sein wird.\n\nSprecht mich an, wenn Ihr bereit seid... und mögen die Vorfahren uns beschützen!", sourceObjective = "Sprecht mit Aggra auf dem Nimbusrücken in Tiefenheim, um eine Passage in die Feuerlande zu sichern.", completion = "Haltet Euch bereit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29339] = { id = 29339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[29340] = { id = 29340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[29341] = { id = 29341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[29342] = { id = 29342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisangeln", description = "Die leckersten Fische leben in den kalten Gewässern Dun Moroghs, {name}, lasst Euch da mal nichts anderes erzählen! Mein Favorit, und am beliebtesten in Eisenschmiede, ist der Seesaibling, der aus den Ländern unserer Ahnen kommt.\n\nIch möchte ihn als Eisenschmiedes Geschenk an die Welt bezeichnen!\n\nWarum versucht Ihr nicht mal selbst, ein paar davon zu fangen? Der beste Ort, um diesen Fisch zu finden, ist im Helmsbettsee, im östlichen Teil von Dun Morogh.", sourceObjective = "Fangt 5 Seesaiblinge, indem Ihr im Helmsbettsee in Dun Morogh angelt.", progress = "Habt Ihr schon versucht, diese Saiblinge zu fangen?", completion = "Sie sind wunderschön, {name}! Ich glaube, Ihr habt jetzt langsam den Dreh raus.", sourceObjectiveStatus = "unverified-source-field" }
quests[29343] = { id = 29343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Nachwelt", description = "Ich bin mir sicher, dass Ihr inzwischen schon mal vom alten Eisenkiefer gehört habt, dem berühmtesten und am schwersten fassbaren Fisch in den Gewässern von Eisenschmiedes Düsterem Viertel. Nun, in seinen vielen Lebensjahren war er dafür verantwortlich, dass jede Menge Nachkommen das Licht der Welt erblickten. Lasst Euch nicht von dem Namen \"Junger Eisenkiefer\" täuschen, {name}, diese Jungfische sind genauso clever wie ihr Vater, ihnen mangelt es nur ein wenig an Erfahrung.\n\nMit Können und Geduld wird es Euch sicher gelingen, einen zu fangen, und wenn es so weit ist, dann bringt ihn zum Museum in Eisenschmiedes Bibliothek und stellt ihn aus, damit ihn alle sehen können!", sourceObjective = "Fangt einen jungen Eisenkiefer in Eisenschmiedes Düsterem Viertel und stellt ihn in der Bibliothek neben der leeren Plakette aus.", completion = "Gut gemacht, {name}! Vielleicht wird Euer Fang ja mehr Zwerge dazu inspirieren, das Angeln anzufangen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29344] = { id = 29344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fische für Squrky", description = "Hab ich Euch schon meinen Begleiter Squrky vorgestellt? Ich bringe ihm bei, wie man angelt, so richtig mit allen Schikanen! Bisher habe ich ihn mit Elritzen gefüttert, die ich aus dem Teich in diesem Viertel gefischt habe.\n\nVielleicht wollt Ihr es ja mal versuchen? Werft einfach Euren Köder in dem Teich da drüben aus und füttert Squrky mit den Elritzen, die Ihr rauszieht. Er wird Euch für immer lieben!", sourceObjective = "Angelt 3 blinde Elritzen aus dem Teich im Düsteren Viertel und verfüttert sie an Squrky.", completion = "Ihr habt gute Arbeit geleistet. Squrky sieht zufrieden aus und ich hatte Zeit, ein paar neue Köder zu basteln. Danke für Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[29345] = { id = 29345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tümpelschrecken", description = "Ein Goblinbesucher, der es sicher nur gut meinte, hat Azsharaschlangenköpfe in unseren Gewässern ausgesetzt und die überrennen jetzt unseren Teich.\n\nIch bitte Euch, wenn Ihr ein paar von diesen gefräßigen Raubfischen fangen könnt, bevor sie alle Kleinfische und Matschschnapper in Donnerfels gefressen haben, wäre ich sehr dankbar.", sourceObjective = "Kah Nebelläufer in Donnerfels braucht 8 Azsharaschlangenköpfe aus dem Teich in Donnerfels.", progress = "Konntet Ihr schon ein paar Azsharaschlangenköpfe fangen?", completion = "Gut gemacht, {name}. Alle Angler von Donnerfels müssen mit anpacken, damit sich diese boshaften Geschöpfe nicht in Mulgores Gewässern ansiedeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[29346] = { id = 29346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ring sie zu knechten", description = "Einer der Verlassenen aus den Teichen der Visionen ist an mich herangetreten und hat mir gesagt, dass sein Ring von einem blinden Höhlenfisch in den dortigen Teichen verschluckt worden ist.\n\nEs könnte auch sein Finger gewesen sein. So richtig verstanden habe ich ihn nicht; sein Kiefer hat sich nicht bewegt und sein Orcisch war nicht besser als mein eigenes.\n\nWie dem auch sei, ich dachte mir, dass wir unseren ungewöhnlichen Gästen einen Gefallen tun könnten und Höhlenfische ausnehmen könnten, bis wir den Ring - oder den Finger - gefunden haben.\n\nWürdet Ihr mir helfen?", sourceObjective = "Angelt einen blinden Höhlenfisch aus den Teichen der Visionen in Donnerfels. Wenn Ihr einen gefangen habt, nehmt ihn aus und seht nach, ob er den Ring verschluckt hat.", progress = "Ihr habt nicht zufällig meinen Ring gesehen, oder? Ich glaube, einer der Höhlenfische hat ihn verschluckt...", completion = "Ihr habt also meinen Ring gefunden, wie? Ich bin Euch überaus dankbar.\n\nUm ganz ehrlich zu sein, ich habe keine Ahnung, warum ich das Ding überhaupt behalte. Ich erinnere mich noch nicht einmal, wie er in meinen Besitz gekommen ist... vermutlich bin ich einfach ein Gewohnheitstier.\n\nWie ich schon sagte, bin ich Euch sehr dankbar. Diese Dinge hier habe ich während meiner Suche nach dem Ring gefunden. Vielleicht sind sie für Euch von Nutzen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29347] = { id = 29347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lebendköder", description = "Wenn Ihr schon mal auf der Jagd nach Flusskrebsen wart, dann wisst Ihr, dass sie am besten auf Lebendköder reagieren. Und je mehr Köder, desto besser! Würdet Ihr gerne meinen neuen Köder ausprobieren? Schmiert Euch einfach damit ein und hüpft in den Helmsbettsee im östlichen Dun Morogh.\n\nBringt Euren Fang zu Koch Ghilm am Steinbruch Gol'Bolar westlich des Sees. Er ist ein Experte in der Zubereitung dieser zu groß geratenen Krabbeltiere!", sourceObjective = "Benutzt Grimnurs Köder an Euch selbst und springt dann in den Helmsbettsee in Dun Morogh.", completion = "Sie sind wunderschön, {name}! Grimnur wird so stolz sein, wenn er davon hört!\n\nOh, er hat mir gesagt, ich soll Euch das hier geben, wenn der Plan aufgeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[29348] = { id = 29348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Fische für Donnerfels", description = "Der Fischteich von Donnerfels wird von gefräßigen Azsharaschlangenköpfen heimgesucht. Es sind kaum noch Kleinfische oder Matschschnapper übrig.\n\nUnsere Angler sind schon dabei, so viele Schlangenköpfe wie möglich zu töten, aber könntet Ihr uns bei unseren Bemühungen, den Teich wieder zu bevölkern, ein wenig zur Hand gehen?\n\nWenn Ihr ein paar Fische aus dem Steinbullensee sammeln könntet und sie hierher nach Donnerfels bringt, wäre ich sehr dankbar.", sourceObjective = "Kah Nebelläufer in Donnerfels braucht 2 scharfe Kleinfische und 2 liebestolle Matschschnapper aus dem Steinbullensee in Mulgore.", progress = "Habt Ihr die Fische aus dem Steinbullensee dabei?", completion = "Wir wissen Eure Hilfe sehr zu schätzen, {name}.\n\nHoffentlich helfen diese Fische dabei, unseren Fischteich wieder zu bevölkern.", sourceObjectiveStatus = "unverified-source-field" }
quests[29349] = { id = 29349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lust auf Flusskrebs", description = "Eine der berühmtesten Delikatessen Mulgores sind die Flusskrebse, die in unseren Seen und Flüssen leben. Sie sind besonders beliebt bei Hochzeiten oder Geburtsfeiern.\n\nWürdet Ihr mir dabei helfen, einige dieser gerissenen Krustentiere für die Kochtöpfe von Donnerfels zu fangen?\n\nIhr könnt sie im Steinbullensee angeln, oder einfach hineinspringen und sie so fangen.", sourceObjective = "Kah Nebelläufer in Donnerfels braucht 10 Steinbullenflusskrebse aus dem Steinbullensee in Mulgore.", progress = "Krebse sind so schmackhaft. Habt Ihr viele gefangen?", completion = "Ah, so viele Krebse!\n\nHabt Ihr sie geangelt? Oder seid Ihr ihnen hinterhergeschwommen?\n\nIst auch egal. Ausgezeichnete Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29350] = { id = 29350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gnomische Köder-o-Matik", description = "Einer von den gnomischen Ingenieurskunstlehrern hat mir die Baupläne für einen raffinierten Köder gegeben, von dem er behauptet, dass er mir hilft, Fische schneller zu fangen und sie davon abzuhalten, abzuhauen.\n\nHier sind die Baupläne. Ihr werdet glänzende Schmuckstücke benötigen, die Ihr von meiner Assistentin im Gebäude erhalten könnt, einen haarfeinen Sprengstoffauslöser von einem Händler für Ingenieurskunstwaren in Tüftlerstadt und ein paar Rattenfallen von der Tiefenbahn.", sourceObjective = "Benutzt die Baupläne für einen Köder-o-Matik mit 5 glänzenden Schmuckstücken, einem haarfeinen Sprengstoffauslöser und 3 Rattenfallen, um einen gnomischen Köder-o-Matik herzustellen.", progress = "Und, wie sieht's aus mit diesem raffinierten neuen Köder?", completion = "Ich denke, es sieht nicht nach was aus, was ein Fisch interessant finden könnte, aber man weiß ja nie. Fische sind seltsame Viecher. Danke, dass Ihr es versucht habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29351] = { id = 29351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Runde für die Wachen", description = "Die Wachen, die Eisenschmiede schützen, riskieren ihr Leben im Kampf gegen unsere vielen Feinde, und es ist an uns, uns um sie zu kümmern.\n\nHeute bestehen ihre Rationen aus zwei Lieblingsdingen der Zwerge: Haggis und Silberbräu aus Eisenschmiede. Wäret Ihr so gut, mir dabei zu helfen, die Rationen zu verteilen? Dadurch bekommen alle ihr Essen rechtzeitig und wir können zu der Erledigung anderer Aufgaben übergehen.", sourceObjective = "Verteilt die Rationen aus Eisenschmiede an 6 Wachen aus Eisenschmiede.", completion = "Eine volle Wache ist eine glückliche Wache, pflege ich immer zu sagen. Danke für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29352] = { id = 29352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geflügelmangel", description = "Oh nein, {name}, das wird ein Desaster, wenn wir nicht bald ein paar Hühner finden... Man kann doch eine Lauch-Hühnersuppe nicht ohne Huhn kochen! Das geht einfach nicht!\n\nEs ist immer noch Zeit genug, die Suppe und die Brühe herzustellen, wenn Ihr ein paar frische Hühner findet. Werdet Ihr mir helfen? Es laufen normalerweise immer ein paar Hühner außerhalb des Haupteingangs der Stadt herum. Wenn Ihr, sagen wir mal, sechs von ihnen erwischt, dann würdet Ihr mir den Hals retten.", sourceObjective = "Fangt 6 Hühner von Dun Morogh in der Nähe des Eingangs von Eisenschmiede.", progress = "Die Hühner, {name}, habt Ihr sie oder nicht?", completion = "Ja, das ist genau das, was ich brauchte. Ihr habt meinen Dank, {name}, und meine Entschuldigung, dass ich vorher so barsch war. Ich kann den Gedanken einfach nicht ertragen, dass eine Mahlzeit nicht rechtzeitig fertig wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[29353] = { id = 29353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haggis für alle!", description = "Der Haggis muss fließen. Na gut, bildlich gesprochen. Haggis wird niemals flüssig sein! Ihr wollt gar nicht wissen, was passiert, wenn die Bevölkerung von Eisenschmiede keinen Haggis bekommt.\n\nIch arbeite gerade an der nächsten Ladung, aber mir fehlen noch ein paar Zutaten.\n\nSognar Klippenbart ist der Fleischverkäufer im Militärviertel und er kann Euch den Sack voller Schafsinnereien verkaufen, den ich brauche. Milde Gewürze bekommt Ihr von jedem Kochbedarfshändler und Säcke voller Hafermehl findet Ihr in den Gasthäusern oder den Vorratslagern der Stadt.", sourceObjective = "Besorgt einen Sack voller Schafsinnereien, 5 Pakete milder Gewürze und 4 Säcke voller Hafermehl.", progress = "Habt Ihr die Zutaten?", completion = "Ihr habt sie alle? Wunderbar! Dann frisch ans Werk.", sourceObjectiveStatus = "unverified-source-field" }
quests[29354] = { id = 29354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glänzende Schmuckstücke", description = "Eines der einfachsten und nützlichsten Hilfmittel eines jeden Anglers ist das glänzende Schmuckstück. Selbst der ungeübteste Angler hat mit einem glänzenden Schmuckstück an der Sehne gute Chancen.\n\nBei all dem Fischen in letzter Zeit gehen die Vorräte von Donnerfels aber schnell zur Neige!\n\nKönnte ich Euch bitten, glänzende Steine vom Fuß der zentralen Anhöhe zu sammeln? Bringt sie zu Nahari Wolkenjäger, damit sie mit ihnen Nachschub anfertigen kann.", sourceObjective = "Nahari Wolkenjäger in Donnerfels braucht 20 glänzende Steine vom Fuß der zentralen Anhöhe.", progress = "Habt Ihr mir vielleicht ein paar glänzende Steine mitgebracht?", completion = "Das sind aber besonders hübsche Steine! Daraus werden perfekte glänzende Schmuckstücke werden, danke sehr.\n\nHier... Kah hat mir Bescheid gesagt, dass Ihr mit den Steinen vorbeikommen würdet und hat mich gebeten, Euch dies bei Eurer Ankunft zu geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[29355] = { id = 29355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewürzbrot en masse", description = "Es mag zwar nichts Besonderes sein, {name}, aber Gewürzbrot ist in Eisenschmiede schon seit jeher sehr beliebt. Manchmal komme ich mit meinen Lieferungen gar nicht hinterher!\n\nMöchtet Ihr vielleicht ein paar Laibe backen, damit Ihr nicht aus der Übung kommt, und mir damit helfen, meine Kunden zu versorgen? Ihr könnt alle Zutaten, die Ihr braucht, von meinem Bruder, Emrul Riknussun, ein Stockwerk unter uns erhalten.", sourceObjective = "Backt oder erhaltet 10 Scheiben Gewürzbrot.", progress = "Wie läuft es mit dem Gewürzbrot?", completion = "Dieses Brot sieht köstlich aus. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29356] = { id = 29356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft den Bierdürftigen", description = "Mein Vorrat an EKW, Eisenschmieder Kristallweizen für Euch Grünschnäbel, gehen zur Neige. Zum Glück ist die Brauerei nicht weit weg und die sollten schon ein neues Fass voll Drugans EKW für uns haben. Dieser Drugan ist ein echtes Brauereigenie, sag' ich Euch.\n\nIch werde es heute nicht schaffen, selbst nach Kharanos hinunterzulaufen, aber vielleicht könnt Ihr dort hinunter flitzen, ein neues Fass abholen und es hierher bringen? Was sagt Ihr?", sourceObjective = "Holt das Fass voll Drugans EKW von der Brauerei in Kharanos ab und bringt es nach Eisenschmiede zurück.", completion = "Ah, gut gemacht! Ich sage Euch, dieser Drugan ist ein echtes Universalgenie - Entdecker, Historiker, Brauer - gibt es etwas, das dieser {race} nicht gemeistert hat?", sourceObjectiveStatus = "unverified-source-field" }
quests[29357] = { id = 29357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jede Menge Gewürzbrot", description = "Ist es nicht erstaunlich, wie etwas so einfaches wie Gewürzbrot jeden Tag in Darnassus verbraucht wird? Wenn ich mich nicht um meine anderen Verantwortlichkeiten kümmere, dann backe ich gerne Gewürzbrot, um meine Fähigkeiten als Koch zu verfeinern und an meiner Technik zu arbeiten.\n\nWarum probiert Ihr es nicht mal aus? Ihr solltet die Zutaten eigentlich hier im Laden finden.\n\nEgal wie viel wir herstellen, es wird nie schlecht. Bringt mir einige Laibe, wenn Ihr fertig seid und ich werde jemanden schicken, um sie mit unseren Freunden, den Gilneern, zu teilen.", sourceObjective = "Stellt 10 Laibe Gewürzbrot her oder besorgt sie Euch anderweitig.", progress = "Ich liebe diesen Geruch von frisch gebackenem Brot einfach, besonders von Gewürzbrot, Ihr nicht?", completion = "Diese hier sind gut gemacht, {name}. Ich hoffe, Ihr fandet es genauso entspannend wie ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[29358] = { id = 29358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir benötigen mehr Pinienkerne", description = "Die Shu'halo verwenden Pinienkerne in so vielen Gerichten: Wild, Fisch, Gemüse, selbst Backwaren versetzen wir mit ihnen.\n\nDie Erdenmutter hat uns damit gesegnet, dass die allerbesten Pinienkerne von den Bäumen auf diesen Anhöhen stammen.\n\nSammelt einfach Kienäpfel und röstet sie über einem Feuer, damit die Kerne herausfallen. Es sind fast nie genug für alle da...", sourceObjective = "Sammelt 30 Pinienkerne, indem Ihr Kienäpfel von Mulgore in Donnerfels sammelt und sie röstet. Liefert die Kerne bei Aska Nebelläufer in Donnerfels ab.", progress = "Habt Ihr viele dieser leckeren Pinienkerne finden können?", completion = "Ihr arbeitet so schnell!\n\nIch sorge dafür, dass sie an die verschiedenen Köche und Bäcker von Donnerfels verteilt werden.\n\nHabt Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[29359] = { id = 29359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Klassiker", description = "Hering ist eine der meistverlangten Fischarten in Darnassus, aber Hering ist nicht gleich Hering. Der Kaldoreihering kommt nur in den Gewässern um Teldrassil vor.\n\nIch versuche, immer ein paar vorrätig zu haben, weil dieser Fisch so vielseitig ist! Ich habe gerade erst wieder welche fertig geräuchert, deshalb muss ich meine Vorräte aufstocken. Würde es Euch etwas ausmachen, mir zu helfen? Ihr könnt Kaldoreihering fangen, wenn Ihr in der Nähe von Rut'theran angelt.", sourceObjective = "Angelt 8 Kaldoreiheringe, indem Ihr in der Nähe von Rut'theran Eure Angel auswerft.", progress = "Habt Ihr die Heringe?", completion = "Danke! Ich frage mich, was ich mit denen wohl anstellen könnte...", sourceObjectiveStatus = "unverified-source-field" }
quests[29360] = { id = 29360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und als Beilage: Fliegen", description = "Wir verpflegen hier nicht nur die Orcs, {class}. Diesmal geht es darum, Nahrung für deren Ablösung zuzubereiten.\n\nWir müssen klein beginnen und Fliegen fangen. Fliegen lieben fauliges Fleisch und wir lieben fauliges Fleisch... als Belagerungsgeschosse!\n\nDurchsucht die Fleischwagen nach überschüssigen Fleischbrocken. Wo es Fleisch gibt, gibt es auch Fliegen.\n\nBringt mir 25 fette Fliegen, damit ich Phase Zwei unseres Kochplans einleiten kann.", sourceObjective = "Beschafft 25 fette Fliegen von dem \"Fleisch\" in der Nähe der Fleischwagen. Kehrt anschließend zu Eunice Burch in Unterstadt zurück.", progress = "Ich wette, ein bisschen von dem \"Fleisch\" ist noch gut.", completion = "Ah! Perfekt! Fett, träge und bereit, gefressen zu werden! Als nächstes werden wir sie an unsere Spinnen verfüttern. Die werden gemästet und dann verfüttern wir sie an die Frösche...\n\nAch, ich plappere schon wieder. Die Details müsst Ihr gar nicht wissen. Das ist nur ein kleiner Schritt in einem großen kulinarischen Plan.", sourceObjectiveStatus = "unverified-source-field" }
quests[29361] = { id = 29361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Monster im Burggraben", description = "Manchmal muss man beim Angeln seinen Fang wieder ins Wasser zurückwerfen, {class}.\n\nWir haben diese Frösche nur für diesen Zweck gemästet. Sie haben fette Spinnen bekommen, die ihrerseits mit fetten Fliegen gefüttert worden sind, und jetzt füttern wir ein echtes Monster.\n\nIn den Burggräben an der Oberfläche, in den Ruinen von Lordaeron, lebt unser eigenes Burggrabenmonster.\n\nHeute ist Fütterungstag. Aber wir müssen es dabei auch abrichten. In diesem Beutel findet Ihr einen Lockvogelbausatz und ein paar fette Frösche. Stellt den Lockvogel auf und werft dem Monster die Frösche zu, sobald es auftaucht.", sourceObjective = "Benutzt den Allianzlockvogelbausatz, um das Burggrabenmonster in den Ruinen von Lordaeron hervorzulocken. Verwendet dann die fetten Frösche, um das Monster zu füttern.", completion = "Die Toten ernähren die Fliegen. Die Fliegen ernähren die Spinnen. Die Spinnen ernähren die Frösche. Die Frösche füttern unser Burggrabenmonster... ein entzückender Lebenszyklus, bei dem so viele Leben beendet werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29362] = { id = 29362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Magische\" Pilze", description = "Ihr kennt doch sicher die Teiche der Visionen, oder?\n\nDort wächst eine bestimmte Pilzart... nicht die ledrigen, wuchernden Pilze, die dort überall stehen, sondern kleinere, zerbrechlichere Schwämme, die unter ihnen wachsen.\n\nSie sind selten, sehr köstlich und verleihen Gerichten einen Geschmack, den man magisch nennen könnte.\n\n...Was denn? Ernsthaft. Sie schmecken einfach nur gut. Sonst nichts.", sourceObjective = "Sammelt 6 \"magische\" Pilze aus den Teichen der Visionen in Donnerfels. Liefert sie bei Aska Nebelläufer in Donnerfels ab.", progress = "Konntet Ihr die Pilze finden?", completion = "Danke, {name}! Ich bin sicher, dass sie ein einfach magisches Aroma in jedes Gericht zaubern.\n\nWas ist denn? Hört auf mich so anzuschauen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29363] = { id = 29363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewürzbrot aus Mulgore", description = "Ich werde oft gefragt \"Aska, wer bäckt eigentlich all dieses Gewürzbrot aus Mulgore?!\"\n\nEine berechtigte Frage. Unser gutes und edles Brot wird an unzähligen Orten in jedem Winkel Azeroths gehandelt, selbst von unseren erbittertsten Feinden. SO LECKER IST ES!\n\nUnd die Antwort lautet...?\n\n\"IHR seid es.\" Bitte nehmt dieses Paket mit Gewürzen aus Mulgore und macht damit aus fadem, langweiligem Gewürzbrot Gewürzbrot aus MULGORE!", sourceObjective = "Kombiniert die Gewürze aus Mulgore mit Gewürzbrot, um 5 Laibe frisches Gewürzbrot aus Mulgore herzustellen (Ihr könnt Euer eigenes Gewürzbrot backen, oder welches aus anderen Quellen verwenden). Liefert die Brote bei Aska Nebelläufer in Donnerfels ab.", progress = "Habt Ihr schon das Gewürzbrot aus Mulgore gebacken?", completion = "Ooh, das Brot duftet aber köstlich. Ihr seid ja ein Meisterbäcker.\n\nWer weiß, wie weit diese exquisiten Laibe reisen werden... wie ich höre, sind sie sogar bei den Draenei auf der Azurmythosinsel beliebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29364] = { id = 29364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maisbrei", description = "Eins der wichtigsten Grundnahrungsmittel hier in Donnerfels ist Maismehl; in fast jedem Haushalt findet man Schüsseln mit Mais.\n\nDa so viele Mühlen im Land ständig von Harpyien, Gnollen, rücksichtslosen Bergbaugesellschaften und weiß die Erdenmutter wem angegriffen werden, bitte ich oft meine Lehrlinge, beim Maismahlen mitzuhelfen.\n\nWürdet Ihr vielleicht auch mit anfassen?", sourceObjective = "Helft den Bewohnern von Donnerfels, Maismehl herzustellen, indem Ihr Schüsseln mit Maiskörnern mahlt.", completion = "Es steckt viel Arbeit darin, genügend Maismehl für alle zu machen. Danke für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29365] = { id = 29365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perfekt ausgewählte Portionen", description = "Selbst Einsteigerköche wissen, dass ein großartiges Gericht mit großartigen Zutaten beginnt.\n\nIch habe bei den Händlern von Donnerfels Daueraufträge, aber ich möchte gern sehen, wie Ihr Euch dabei schlagt, die allerbesten Waren auszuwählen, die sie im Angebot haben.\n\nBitte geht von Händler zu Händler und besorgt mir perfekte Portionen Fleisch, Fisch, Gemüse und Kräuter.", sourceObjective = "Besorgt vier \"perfekte Portionen\" von den Händlern in Donnerfels. Liefert die Zutaten bei Aska Nebelläufer in Donnerfels ab.", progress = "Habt Ihr alle nötigen Zutaten gesammelt?", completion = "<Aska beäugt die Zutaten, die Ihr ausgewählt habt.>\n\nMmmhmmm. Ja. Gut gemacht!\n\nIch hätte sie selbst nicht besser auswählen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[29368] = { id = 29368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking" }
quests[29371] = { id = 29371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Zeit des Verlierens", description = "Seid gegrüßt, {class}. Während wir versuchen, uns an der Weidenmannzeremonie zu erfreuen, ist es nicht verwunderlich, dass die Horde versucht, unsere Feierlichkeiten zu ruinieren.\n\nDie schlauste Lösung wäre es wohl, einfach darüber zu stehen und diese Angriffe zu ignorieren.\n\nIch bewundere diejenigen, die das schaffen, doch ich kann ihnen nicht helfen. Doch denjenigen, die zurückschlagen möchten... denen kann ich helfen. Falls Ihr Interesse habt, {class}, nehmt dieses Löschmittel und setzt es gegen den Weidenmann der Horde in den Ruinen von Lordaeron ein.", sourceObjective = "Benutzt das Löschmittel gegen den Weidenmann in den Ruinen von Lordaeron.", completion = "Ah, es ist also vollbracht. Das wird nur kurz anhalten, aber wenn es so sehr stört wie ihre Angriffe uns, dann war es das wert.\n\nIch habe den Kindern von Eurem Abenteuer erzählt und sie waren davon begeistert. Sie waren beeindruckt von Eurem Mut, sich in das Territorium des Feindes zu wagen. Gleichzeitig haben sie sich scheinbar über das Unglück gefreut, das Ihr verbreitet habt... Oh, diese kleinen Schlingel...\n\nSie wollten, dass Ihr als Belohnung einige ihrer Süßigkeiten erhaltet. Genießt sie, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29372] = { id = 29372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger in Posemuckel", description = "Gesetzlose haben den Sheriff entführt!", sourceObjective = "Rettet den Sheriff.", sourceObjectiveStatus = "unverified-source-field" }
quests[29373] = { id = 29373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger in Posemuckel", description = "Wir haben Sheriff Blundy niemals besonders viel Aufmerksamkeit geschenkt, wie er sich da ständig aufgeplustert hat wegen seinen \"Gesetzen\" und \"Fehl-ver-halt-en\". Aber den dreckigen alten McClintocks und ihrem Kuhtreiber von einem Vater vom Truckshawgrat hat es bis hier gestanden mit den ständigen Kerkerhaften und Verhandlungen und Sippenhaften und \"Tot oder lebendig!\"-Steckbriefen und da sind sie letzte Woche gekommen und haben das Gesetz in die eigenen Hände genommen - im wahrsten Sinne des Wortes - indem sie den guten Sheriff verschleppt haben.", sourceObjective = "Rettet den Sheriff.", sourceObjectiveStatus = "unverified-source-field" }
quests[29374] = { id = 29374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stinkbomben los!", description = "Die närrische Allianz hat Hexen eingestellt, um einen Angriff auf unsere Stadt durchzuführen. Na, wie meine Schwester mal gesagt hat: \"Gleiches Recht für alle!\".\n\nWir werden ihnen den Gefallen mit Freuden zurückzahlen. Sprecht mit meiner Schwester und sie wird Euch einen Ritt auf einem Besen über Sturmwind organisieren. Sobald Ihr Euch über Sturmwind befindet, solltet Ihr die Stinkbomben auf die Stadt und ihre Einwohner fallenlassen. Lasst sie leiden!\n\nWir werden diesen Hexen in Sturmwind schon zeigen, wer mächtiger ist.", sourceObjective = "Sprecht mit Crina Fenlow und nehmt einen Besen, um damit über Sturmwind zu fliegen. Benutzt die Stinkbomben, um die Stadt und ihre Einwohner damit zu bewerfen.", progress = "Die Magie, die diese Hexen in Sturmwind benutzen, kann mit unserer Magie nicht mithalten, {class}.", completion = "Das wird den Narren in der Allianz zeigen, wer hier der Stärkste ist.\n\nNehmt diese Dinge und belohnt Euch mit etwas Schönem, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29375] = { id = 29375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufräumen in Unterstadt", description = "Seid gegrüßt, {class}! Genießt Ihr die Schlotternächte? Es scheint, dass die Allianz als Antwort auf unseren Stinkbombenangriff auf Sturmwind auch unsere Stadt mit Stinkbomben angreift.\n\nZum Glück verfügen wir über Magien, die mit dem Gestank der Allianz fertigwerden. Benutzt diesen Arkanreiniger, um die Stinkbomben aus der Stadt zu beseitigen.", sourceObjective = "Benutzt den Arkanreiniger, um die Stinkbomben in Unterstadt zu entfernen.", completion = "Mir ist der Geruch vorher nicht aufgefallen, aber ich bin an dem Punkt angelangt, an dem ich von den Allianzhexen schwache Magie erwarte. Wie dem auch sei, die orcischen Wachen haben sich genug beklagt und werden Eure Anstrengungen sicher zu schätzen wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29376] = { id = 29376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Zeit des Aufbaus", description = "Wir verbrennen den Weidenmann als Symbol für unseren Kampf gegen diejenigen, die sich uns in den Weg stellen. Wir tragen die Asche des verbrannten Weidenmanns als Symbol für den niemals endenden Kampf gegen diejenigen, die uns versklaven wollen.\n\nBenutzt das nahe Feuer, um den Weidenmann zu entzünden. Nehmt Euch dann die herumliegende Asche und beschmiert Euer Gesicht damit.\n\nDiese Gesten werden unsere Feinde daran erinnern, dass wir niemals innehalten werden.", sourceObjective = "Benutzt das Freudenfeuer vor dem Weidenmann, um ihn in Brand zu stecken. Benutzt die Asche auf dem Boden in der Nähe des Weidenmanns.", progress = "Dies ist die Nacht, in der unsere Feinde uns am meisten fürchten, {class}.", completion = "JETZT ist die Zeit für die Verlassenen! Alle Macht den Verlassenen - JETZT UND FÜR IMMER!", sourceObjectiveStatus = "unverified-source-field" }
quests[29377] = { id = 29377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Zeit des Vandalismus", description = "Seid gegrüßt, {class}. Während wir versuchen, uns an der Weidenmannzeremonie zu erfreuen, ist es nicht verwunderlich, dass die Allianz versucht, unsere Feierlichkeiten zu ruinieren.\n\nWir haben die Möglichkeit, es ihnen heimzuzahlen. Falls Ihr Interesse habt, {class}, nehmt dieses Löschmittel und setzt es gegen den Weidenmann der Allianz vor Sturmwind ein.\n\nLöscht ihre Flamme und erfreut Euch an ihrem Leid.", sourceObjective = "Benutzt das Löschmittel gegen den Weidenmann vor Sturmwind.", completion = "Ah, es ist also vollbracht. Das wird zwar nur kurz anhalten, aber wenn es sie so sehr stört wie ihre Angriffe uns, dann war es das wert.\n\nDie Kinder haben von Eurem Abenteuer erfahren und waren begeistert. Sie haben sich anscheinend über das Unglück gefreut, das Ihr verbreitet habt... Oh, diese kleinen Schlingel...\n\nSie wollten, dass Ihr als Belohnung einige dieser Süßigkeiten erhaltet. Genießt sie, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29378] = { id = 29378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Teleport nach Vashj'ir" }
quests[29379] = { id = 29379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Teleport nach Tiefenheim" }
quests[29380] = { id = 29380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Teleport in die Feuerlande" }
quests[29381] = { id = 29381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Teleport nach Hyjal" }
quests[29382] = { id = 29382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Danke, aber nein danke", description = "Ein Feiertagspulli gefällt vielleicht nicht jedem.\n\nAuf dem Beleg steht, dass Ihr ihn bei jedem Händler der Kokelwälder gegen Gold umtauschen könnt.\n\nDer Umtausch lässt sich nicht rückgängig machen.", sourceObjective = "Wenn Euch Euer Geschenk wirklich nicht gefällt, dann könnt Ihr es gegen Gold eintauschen, indem Ihr mit einem Händler der Kokelwälder sprecht.\n\nDer Umtausch lässt sich nicht rückgängig machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29383] = { id = 29383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Danke, aber nein danke", description = "Ein Feiertagspulli gefällt vielleicht nicht jedem.\n\nAuf dem Beleg steht, dass Ihr ihn bei jedem Händler der Kokelwälder gegen Gold umtauschen könnt.\n\nDer Umtausch lässt sich nicht rückgängig machen.", sourceObjective = "Wenn Euch Euer Geschenk wirklich nicht gefällt, dann könnt Ihr es gegen Gold eintauschen, indem Ihr mit einem Händler der Kokelwälder sprecht.\n\nDer Umtausch lässt sich nicht rückgängig machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29385] = { id = 29385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Winterhauchgeschenk" }
quests[29386] = { id = 29386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Hyjal!", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Botschafterin Windweise in Nachthafen auf der Mondlichtung zu melden.\n\nUnsere Brüder im Zirkel des Cenarius haben uns berichtet, dass Todesschwinges Anhänger einen vernichtenden Angriff gegen den Weltenbaum gestartet haben und drohen, ihn zu verbrennen!\n\nSprecht mit Cenarius' Abgesandter Jademond in Sturmwind, um Zugang zur Mondlichtung zu erlangen.\n\nFür den Ruhm und die Ehre der Allianz! Auf in den Kampf, <Bruder/Schwester>!", sourceObjective = "Sprecht mit Cenarius' Abgesandter Jademond, um auf die Mondlichtung zu reisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29387] = { id = 29387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wächter des Hyjal: Die Invasion der Feuerlande!", description = "Die Wächter des Hyjal, angeführt von dem Erzdruiden Malfurion Sturmgrimm, suchen nach tapferen Helden, die bei einem großangelegten Angriff auf die Feuerlande helfen.\n\nFähige Helden der Allianz sollten sich augenblicklich beim Heiligtum von Malorne am Hyjal einfinden.", sourceObjective = "Meldet Euch bei Matookla beim Heiligtum von Malorne am Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[29388] = { id = 29388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wächter des Hyjal: Die Invasion der Feuerlande!", description = "Die Wächter des Hyjal, angeführt von dem Erzdruiden Malfurion Sturmgrimm, suchen nach tapferen Helden, die bei einem großangelegten Angriff auf die Feuerlande helfen.\n\nFähige Champions der Horde sollten sich augenblicklich beim Heiligtum von Malorne am Hyjal einfinden.", sourceObjective = "Meldet Euch bei Matookla beim Heiligtum von Malorne am Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[29389] = { id = 29389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wächter des Hyjal: Die Invasion der Feuerlande!", description = "Eure Arbeit hat uns den Vorteil verschafft, den wir brauchen, um gegen die Bewohner der Feuerlande zu mobilisieren. Genau in diesem Moment versammeln wir unsere Invasionsstreitkräfte südlich Eurer Position.\n\nWir könnten Eure Stärke ein weiteres Mal brauchen, {race}. Sprecht mit Matookla am Heiligtum von Malorne. Sie koordiniert die Invasionsanstrengungen.", sourceObjective = "Meldet Euch bei Matookla beim Heiligtum von Malorne am Hyjal.", completion = "Danke, dass Ihr unserem Ruf gefolgt seid, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29390] = { id = 29390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wächter des Hyjal: Der Ruf der Uralten", description = "Die Wächter des Hyjal, angeführt von dem Erzdruiden Malfurion Sturmgrimm, suchen nach tapferen Helden, die helfen, den Hyjal vor den Elementarangreifern zu schützen. Diese Angreifer müssen zurückgedrängt werden, bevor Streitkräfte für den direkten Angriff auf die Feuerlande mobilisiert werden können.\n\nFähige Helden sollten sich augenblicklich am Hyjal einfinden und den uralten Verteidigern zu Hilfe kommen: Lo'Gosh, Tortolla, Aviana und Aessina.\n\nReisende, die sich zum ersten Mal zum Hyjal aufmachen, können sich nach einem Befehl des Kriegshäuptlings auf einem beliebigen Aufrufbrett der Horde umsehen.", sourceObjective = "Helft Lo'Gosh, Tortolla, Aviana und Aessina beim Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[29391] = { id = 29391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wächter des Hyjal: Der Ruf der Uralten", description = "Die Wächter des Hyjal, angeführt von dem Erzdruiden Malfurion Sturmgrimm, suchen nach tapferen Helden, die helfen, den Hyjal vor den Elementarangreifern zu schützen. Diese Angreifer müssen zurückgedrängt werden, bevor Streitkräfte für den direkten Angriff auf die Feuerlande mobilisiert werden können.\n\nFähige Helden sollten sich augenblicklich am Hyjal einfinden und den uralten Verteidigern zu Hilfe kommen: Goldrinn, Tortolla, Aviana und Aessina.\n\nReisende, die sich zum ersten Mal zum Hyjal aufmachen, können sich nach einem Heldenaufruf auf einem beliebigen Aufrufbrett der Allianz umsehen.", sourceObjective = "Helft Goldrinn, Tortolla, Aviana und Aessina beim Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[29392] = { id = 29392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermisste Erbstücke", description = "Meine letzten Besitztümer hätten eigentlich heute aus Theramore eintreffen sollen. Das Schiff ist angekommen, aber ich habe nichts von dem Kurier gehört. Die Kiste, die er transportieren sollte, enthält Gegenstände, die schon seit Generationen im Familienbesitz sind.\n\nWürdet Ihr vielleicht hinunter zum Hafen von Sturmwind gehen und nachsehen, was ihn aufhält?", sourceObjective = "Durchsucht die Kabine auf dem Schiff des angeheuerten Kuriers im Hafen von Sturmwind nach Hinweisen, was den Kurier aufhalten könnte.", progress = "Die von Anson beschriebene Kiste scheint nicht hier zu sein...", completion = "Dieser Kurier wird sich wohl in naher Zukunft nicht mit seinem Arbeitgeber treffen und die Kiste, die er transportieren sollte, scheint verschwunden zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[29393] = { id = 29393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebräu fürs Braufest", description = "Ihr wollt also die Rennwidder testen? Die Zwerge bilden sich ein, dass sie's besonders drauf hätten; aber seien wir mal ehrlich, die meiste Zeit sind sie ja sowieso betrunken, so schwer kann's also gar nicht sein!\n\nSo, bevor Ihr Euch ins Abenteuer stürzt, müsst Ihr mir zeigen, dass Ihr mit diesen feinen, auf legale Weise erworbenen Widdern umgehen könnt.\n\nJetzt zur Abmachung. Ich borge Euch Zügel und lasse Euch auf einem Widder reiten. Mal sehen, was Ihr drauf habt.\n\nLasst den Widder traben, dann leicht galoppieren und schließlich richtig galoppieren. Ihr müsst jede Geschwindigkeit 8 Sekunden lang halten.", sourceObjective = "Ihr habt 4 Minuten, um den Widder zu reiten und dabei 3 verschiedene Geschwindigkeitsstufen für jeweils 8 Sekunden zu halten.", completion = "Der Unfall auf dem Weg nach Messerbucht hat den Bierfluss ganz schön ins Stocken gebracht! Und es hilft natürlich überhaupt nicht, dass die Dunkeleisenzwerge gefühlt jede Stunde angreifen!\n\nWenn Ihr also helfen wollt, machen wir es so: Ich borge Euch einen meiner Widder.\n\nJedes Mal, wenn Ihr mir einen Becher bringt, gebe ich Euch ein paar Abzeichen. Für jeden Becher, den Ihr mir bringt, werde ich Euch den Widder ein wenig länger nutzen lassen!\n\nABER: Wenn Ihr einmal damit angefangen habt, dann könnt Ihr es erst morgen erneut versuchen.\n\nSeid Ihr sicher, dass Ihr bereit seid, es zu versuchen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29394] = { id = 29394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebräu fürs Braufest", sourceObjective = "Ihr habt 4 Minuten, um den Widder zu reiten und dabei 3 verschiedene Geschwindigkeitsstufen für jeweils 8 Sekunden zu halten.", completion = "Beim Braufest besteht immer Bedarf nach weiteren Bechern und Kharanos verfügt über jede Menge Becher, die sie entbehren können!\n\nIch werde Euch einen meiner Privatwidder leihen.\n\nJedes Mal, wenn Ihr mir einen Becher bringt, gebe ich Euch ein paar Abzeichen. Für jeden Becher, den Ihr mir bringt, werde ich Euch den Widder ein wenig länger nutzen lassen!\n\nBeachtet aber: Wenn Ihr einmal damit angefangen habt, dann könnt Ihr es erst morgen erneut versuchen.\n\nSeid Ihr sicher, dass Ihr bereit seid, es zu versuchen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29395] = { id = 29395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Teleport nach Uldum" }
quests[29396] = { id = 29396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neuer Souvenirlieferant", description = "<seufz>\n\nHört mir auf mit den Krügen vom letzten Jahr...\n\nIch glaube, dass diese zwielichtigen Bierkruglieferanten irgendwas mit diesem merkwürdigen Schattenhammerkult zu tun hatten, der aufgetaucht ist, bevor die Elementare eingefallen sind.\n\nUnd das ist der Grund, warum wir einen neuen Lieferanten und einen besseren Krug haben!\n\nHier habt Ihr einen Gutschein für einen Bierkrug.\n\nSprecht mit Blix in der Nähe des hinteren Endes des Braufestlagers. Er ist ziemlich seltsam, vor allem, weil er immer diese Brille aufhat. Er wird den Gutschein für Euch bearbeiten, und alle anderen Transaktionen des Braufests.", sourceObjective = "Löst Euren Gutschein für einen Braufestkrug bei Blix Fixtand im hinteren Teil des Braufestlagers ein.", progress = "Was ist los, Schätzchen? Habt Ihr etwas für mich?", completion = "Was ist das? Ein Gutschein für einen Braufestkrug? Ihr trinkt also gerne? Großartig! Sobald Ihr den Krug habt, solltet Ihr Euch ein paar Schluck gönnen... und noch ein paar mehr... und mehr... Dann, und das ist wichtig, kommt wieder hierher zu mir.\n\nIch weiß doch, dass Ihr wieder hierherkommt. Wenn Ihr Eure Gutscheine einlösen möchtet, dann müsst Ihr hierher zu mir.\n\nNaja, hier ist der Krug. Vergesst nicht, später noch einmal mit mir zu sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29397] = { id = 29397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neuer Souvenirlieferant", description = "Je weniger Worte wir über die Krüge vom letzten Jahr verlieren, je besser, {name}. Ich kann Euch sagen, die letzten Lieferanten, das waren zwielichtige Typen. Letztendlich hat sich herausgestellt, dass sie in irgendwelche Kultistenaktivitäten verwickelt waren...\n\nMit Leuten, die versuchen, die Welt zu zerstören, können wir nicht arbeiten!!\n\nDeshalb haben wir uns einen neuen Lieferanten und einen neuen Krug gesucht.\n\nBringt diesen Gutschein zu Belbi Blitzknips im hinteren Teil des Braufestlagers. Sie kümmert sich außerdem um alle sonstigen Braufestgeschäfte, die während der Festtage anstehen.", sourceObjective = "Löst Euren Gutschein für einen Braufestkrug bei Belbi Blitzknips im Braufestlager ein.", progress = "Was ist los, Schätzchen? Habt Ihr etwas für mich?", completion = "Ooch, es ist nur ein Gutschein für einen Braufestkrug... vielleicht gebt Ihr Euch ja auch nur so unnahbar. So, hier habt Ihr den diesjährigen Krug.\n\nIch nehme an, dass ich Euch noch öfter hier sehen werde. Denn wenn Ihr Eure Gutscheine einlösen möchtet, dann bin ich Euer Mädel hier...\n\noder vielleicht seins...\n\nooohhh... oder seins...", sourceObjectiveStatus = "unverified-source-field" }
quests[29398] = { id = 29398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hehlerware", description = "Eine schnelle Überprüfung der Kabine ergibt keine Hinweise auf die Identität des Mörders oder seine Motive. Die Kiste, wegen der Ihr gekommen seid, ist verschwunden.\n\nWährend Ihr Euch umdreht, um die Kabine zu verlassen, bemerkt Ihr, dass sich am Boden etwas Kleines bewegt. Eine Gruppe Spinnen kriecht unter dem Bett des erschlagenen Kuriers hervor. Wo könnten sie hinwollen?", sourceObjective = "Folgt den Spinnen zu ihrem Ziel und befragt den Mann, den Ihr dort findet.", progress = "Warum belästigt Ihr mich noch immer?", completion = "Senkt Eure Stimme und lasst nichts hierüber verlauten oder meine Karriere als Auktionator ist vorüber!", sourceObjectiveStatus = "unverified-source-field" }
quests[29399] = { id = 29399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preise vergleichen", description = "Ich habe dem 'Herrn' gesagt, dass es da einen Laden im Zwergendistrikt gibt, der vielleicht besser geeignet ist für seine Bedürfnisse. Er heißt \"Schattenspiele\" und Ihr findet den Eingang in der Nähe der Kanäle auf der westlichen Seite des Distrikts.\n\nQuincy Messerschmied ist Euer Mann. Er handelt mit Waren, die ein ehrlicher Händler nicht mal mit der Kneifzange anfassen würde!", sourceObjective = "Begebt Euch zum Laden \"Schattenspiele\" im Zwergendistrikt von Sturmwind und sucht nach Hinweisen auf den Besuch des Kistendiebes.", progress = "Ihr seht aus, als wüsstet Ihr etwas über diese verschwundenen Waren.", completion = "Endlich hat mir Messerschmied mal etwas gegeben, womit ich arbeiten kann. Bevor ich diese Information herausrücke, will ich wissen, für wen Ihr arbeitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[29400] = { id = 29400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Zeit zum Feiern", description = "Seid gegrüßt, {class}.\n\nDie Schlotternächte sind eine Zeit des Feierns und der Besinnlichkeit, obwohl es scheint, dass viele von uns vergessen haben, warum. Das Verbrennen des Weidenmanns im Besonderen ist ein Rätsel für viele außerhalb der Verlassenen.\n\nReist zu den Ruinen von Lordaeron und sprecht mit der Ruferin der Dunkelheit Yanka. Sie wird Euch mehr von der Weidenmannzeremonie erzählen.", sourceObjective = "Sprecht mit der Ruferin der Dunkelheit Yanka in den Ruinen von Lordaeron.", completion = "Die Weidenmannzeremonie ist eine ehrwürdige Tradition. Es ist schön zu sehen, dass die Horde sich uns in den Feierlichkeiten anschließt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29401] = { id = 29401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weggeweht", description = "Bitte, <Onkel/Tante>, Ihr müsst mir helfen!\n\nMein Papa hat mir auf dem Dunkelmond-Jahrmarkt ein paar Luftballons gekauft. Das beste Geschenk... aller... ZEITEN! Sie sind magisch, wisst Ihr, und sie verlieren nie ihre Schwebkraft!\n\nDa gibt es nur ein Problem...\n\nEin riesiger Windstoß hat sie mir direkt aus den Händen gerissen. Jetzt sind sie über ganz Orgrimmar verteilt!\n\nIch würde ja selber hinter ihnen herlaufen, aber die Stadt ist so groß, dass ich mich ganz sicher verlaufen würde.\n\nKönnt Ihr sie für mich einsammeln, bevor sie weggeweht werden?\n\nBitte?", sourceObjective = "Jaga möchte, dass Ihr 5 entflohene Ballons in Orgrimmar einsammelt.", progress = "Habt Ihr alle meine Ballons gefunden, Onkel?", completion = "Das ist so SUPER! Ihr habt es geschafft!\n\nDanke, Onkel!", sourceObjectiveStatus = "unverified-source-field" }
quests[29402] = { id = 29402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorsichtsmaßnahmen", description = "Ich wäre vorsichtig mit allen, die sich als rechtmäßige Besitzer der Kiste und ihres Inhalts ausgeben. Hat man Euch nicht vor der Gefahr gewarnt?\n\nHier ist eine bessere Idee: Lasst uns zusammenarbeiten, um die Kiste zurückzuholen und sicherzugehen, dass ihr Inhalt niemandem schadet. Um uns selbst zu schützen werden wir ein Gebräu benötigen, das aus einigen Ingredienzien besteht, die in der Stadt zu finden sind.\n\nKauft etwas seltsamen Staub bei einem Verzauberkunsthändler, besorgt Euch ein paar Phiolen von einem Alchemisten und sammelt ein paar Blutnesseln in den Feldern nördlich der Stadt.", sourceObjective = "Besorgt Euch 2 Portionen seltsamen Staub, 5 Kristallphiolen und 5 Blutnesseln.", progress = "Habt Ihr alle Ingredienzien erhalten?", completion = "Manchmal denke ich, dass ich meinem Vater in die Alchemie hätte folgen sollen.\n\nDieses Gebräu sollte uns vor den schlimmsten Auswirkungen, die das Tragen und die Handhabung der Kiste mit sich bringen, schützen. Wohl bekommt's!", sourceObjectiveStatus = "unverified-source-field" }
quests[29403] = { id = 29403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Agent des Sammlers", description = "Quincy zufolge ist der \"Sammler\", der die Kiste haben will, niemand anders als der wahnsinnige Erzmagier Xylem aus Azshara.\n\nDer treue Diener des Erzmagiers soll sich mit dem Mann, der die Kiste hat, in den Katakomben unterhalb der Kathedrale des Lichts treffen.\n\nIhr müsst Euch rechtzeitig dort einfinden, um den Austausch zu verhindern und die Kiste in Euren Besitz zu bringen, bevor sie für immer an Xylem verloren ist. Trefft mich im \"Goldenen Fass\", sobald Ihr die Kiste habt.", sourceObjective = "Unterbrecht das Treffen zwischen Sanath Lim-yo und dem Dieb in den Katakomben unterhalb der Kathedrale des Lichts.", completion = "Ranken aus dunkler Macht tanzen um die Kiste, aber es gibt keine Spur von Sanath Lim-yo. Ihr könnt die Kiste jetzt an Euch nehmen und zu Eurem Auftraggeber zurückkehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[29404] = { id = 29404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viel zu lernen", description = "Nun, da Eure Ausbildung begonnen hat, erhaltet Ihr Eure erste, recht simple Aufgabe: Sprecht mit Meister Shang Xi.", sourceObjective = "Sprecht mit Meister Shang Xi.", sourceObjectiveStatus = "unverified-source-field" }
quests[29405] = { id = 29405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lektion des Eisenstabes", description = "Für Eure Ausbildung müsst Ihr Euch zunächst einmal ausstatten. Beschafft Euch eine Waffe von einem der Waffenregale dort unten, bringt sie zu mir und zeigt mir, dass Ihr auch wisst, wie man sie richtig hält.", sourceObjective = "Nehmt eine Übungswaffe von einem Waffenregal und legt sie an.", sourceObjectiveStatus = "unverified-source-field" }
quests[29406] = { id = 29406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lektion der Sandfaust", description = "Ich würde gern beobachten, wie Ihr Euer neues Werkzeug einsetzt, <mein junger Schüler/meine junge Schülerin>. Das wird mir helfen, darüber zu entscheiden, welcher Grad der Ausbildung Euren Talenten am ehesten entspricht.\n\nWir haben dort unten auf dem Ausbildungsgelände eine Menge Übungsziele. Erprobt Eure Angriffe an ihnen und kehrt zu mir zurück, sobald Ihr ein Gefühl für Eure neue Ausrüstung entwickelt habt.", sourceObjective = "Zerstört 5 Übungsziele.", completion = "Gar nicht schlecht, {name}. Ihr scheint tatsächlich den richtigen Pfad gewählt zu haben.\n\nGut. Lasst uns fortfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[29407] = { id = 29407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das erste Zeichen des Winters", description = "An dem Bach dort unten wächst eine einzelne Lotusblume. In ihr lassen sich Anzeichen dessen finden, was kommen wird. Bringt sie mir, sodass ich Euch zeigen kann, was ich meine.", sourceObjective = "Beschafft den schimmernden Lotus.", sourceObjectiveStatus = "unverified-source-field" }
quests[29408] = { id = 29408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lektion der brennenden Schriftrolle", description = "Jede Weisheit hat einen rechten Ort und eine rechte Zeit, aber die Zeiten ändern sich für all diejenigen, die auf Shen-zin Su leben. Für diese Lektion bitte ich Euch um zwei Dinge.\n\nZunächst halte ich eine Flamme in meiner Hand. Konzentriert Euch und versucht, sie mir zu entreißen, sobald Ihr Euch bereit fühlt.\n\nSolltet Ihr erfolgreich sein, möchte ich, dass Ihr den Tempel besteigt und das Edikt der Mäßigung verbrennt, das Ihr dort oben finden könnt.", sourceObjective = "Entreißt Meister Shang Xi die Flamme und verbrennt dann das Edikt der Mäßigung.", completion = "Dass Ihr mir die Flamme so einfach entreißen konntet, ist keine geringe Leistung.\n\nDas Edikt der Mäßigung ist eine Schriftrolle mit Weisheiten, die über unzählige Generationen hinweg überliefert worden sind. Weisheiten aus einer friedlicheren Zeit.\n\nJede Lehre hat einen rechten Ort und eine rechte Zeit... und nun, da sich die Dunkelheit am Horizont zusammenbraut, gehört die rechte Zeit dieser Weisheiten der Vergangenheit an.\n\nDas Verbrennen der Schriftrolle stellt die Akzeptanz dieser Zeichen und gleichzeitig ein Versprechen dar, zu handeln. Eure Hand trug die Flamme und ich bin gewiss, dass sie dies auch in Zukunft tun wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[29409] = { id = 29409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung des Schülers", description = "Ich sehe große Stärke, gewaltigen Mut und eine unübertroffene Reinheit der Seele in Euch, {name}.\n\nEure Ausbildung hat zwar gerade erst begonnen, aber ich denke, dass Ihr bereits für größere Aufgaben gewappnet seid.\n\nGeht die Treppen hinunter und überquert die Brücke. Dort werdet Ihr Jaomin Ro finden, einen unserer erfahrensten Schüler. Fordert ihn heraus und besiegt ihn in einem ehrenhaften Kampf - dadurch werdet Ihr den ersten Teil Eurer Ausbildung abschließen.", sourceObjective = "Besiegt Jaomin Ro.", completion = "Sehr beeindruckend, {name}. Es scheint, dass Ihr als {class} tatsächlich den richtigen Pfad gewählt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29410] = { id = 29410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aysa, Anhängerin der Tushui", description = "In so kurzer Zeit habt Ihr mir gezeigt, dass in Euch das Potenzial steckt, <ein wahrer Meister/eine wahre Meisterin> Eurer Klasse zu werden, {class}. Das Ausbildungsgelände liegt hinter Euch, und nun müsst Ihr Euch beweisen, indem Ihr eine ungleich größere Herausforderung annehmt, die bislang noch keiner meiner Schüler bewältigt hat.\n\nBitte kehrt zu Huo zurück, dem Geist des Feuers im Tempel der Fünf Sonnenaufgänge.\n\nMeine zwei besten Schüler neben Euch werden Euch bei dieser Aufgabe unterstützen. Sucht zunächst bitte Aysa Wolkensänger auf. Ihr findet sie beim Teich im Westen.", sourceObjective = "Sprecht mit Händler Lorvo bei Fus Teich.", completion = "Ihr sucht nach Aysa? Ihr... Ihr solltet sie besser nicht unterbrechen, bis sie mit ihren Übungen fertig ist. Sie spricht mit niemandem, bevor ihre Übung abgeschlossen ist.\n\nKönntet Ihr mir in der Zwischenzeit vielleicht behilflich sein? Ich hatte etwas Pech mit den Waldgeistern.", sourceObjectiveStatus = "unverified-source-field" }
quests[29411] = { id = 29411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was jetzt?", description = "Endlich habt Ihr die Kiste gefunden, die Anson Euch ausgeschickt hat, zurückzuholen. Es scheint allerdings, dass die Warnungen des Archäologielehrlings korrekt waren.\n\nEs besteht kein Zweifel, dass Euer Auftraggeber Euch bezüglich der Gefahren dieses Auftrags angelogen hat. Wollt Ihr ihm die Kiste wirklich übergeben oder wollt Ihr sie lieber Hudson Barnes geben, der glaubt, dass es besser wäre, den Inhalt der Kiste sicher zu verwahren?", sourceObjective = "Gebt die Kiste Anson Hastings in der \"Güldenen Rose\" in Sturmwind.\n\n-ODER-\n\nGebt die Kiste Hudson Barnes im \"Goldenen Fass\" in Sturmwind.", progress = "Habt Ihr die Kiste wie besprochen dabei?", completion = "Ah, Ihr habt es also geschafft, die Kiste zu bekommen, bevor Erzmagier Xylems Mann sie aus der Stadt schaffen konnte. Exzellent!", sourceObjectiveStatus = "unverified-source-field" }
quests[29412] = { id = 29412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weggeweht", description = "Bitte, <Onkel/Tante>, Ihr müsst mir helfen!\n\nMein Papa hat mir auf dem Dunkelmond-Jahrmarkt ein paar Luftballons gekauft. Das beste Geschenk... aller... ZEITEN! Sie sind magisch, wisst Ihr, und sie verlieren nie ihre Schwebkraft!\n\nDa gibt es nur ein Problem...\n\nEin riesiger Windstoß hat sie mir direkt aus den Händen gerissen. Jetzt sind sie über ganz Sturmwind verteilt!\n\nIch würde ja selber hinter ihnen herlaufen, aber die Stadt ist so groß, dass ich mich ganz sicher verlaufen würde.\n\nKönnt Ihr sie für mich einsammeln, bevor sie weggeweht werden?\n\nBitte?", sourceObjective = "Vin möchte, dass Ihr 5 entflohene Ballons in Sturmwind einsammelt.", progress = "Habt Ihr alle meine Ballons gefunden, Onkel?", completion = "Das ist so SUPER! Ihr habt es geschafft!\n\nDanke, Onkel!", sourceObjectiveStatus = "unverified-source-field" }
quests[29413] = { id = 29413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die unheimliche Kiste", description = "Nach ihr ist gesucht worden, sie wurde gestohlen und verkauft. Jeder, der versucht hat, die in ihr enthaltene Magie anzuzapfen, musste erleben, dass sich diese Macht gegen ihn wandte.\n\nUnd doch erscheint die Kiste selbst unversehrt zu sein und erfüllt von magischer Energie. Von Zeit zu Zeit zittert und hüpft sie, als ob ihr Inhalt lebendig wäre.\n\nSie scheint an Euch gebunden zu sein und jetzt gehört sie Euch." }
quests[29414] = { id = 29414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg der Tushui", description = "Es ist mir eine Freude, Eure Bekanntschaft zu machen, {class}. Ich heiße Aysa und bin eine Anhängerin der Tushui.\n\nIch habe viel Zeit mit Nachsinnen verbracht, seit Meister Shang mir offenbart hat, dass die Suche nach Huo, dem Geist des Feuers, unsere Aufgabe sein würde. Ich weiß, wo er sich aufhält, aber nicht, wie man zu ihm gelangen könnte. Die Antworten sind allerdings zum Greifen nah.\n\nFolgt mir zur Höhle der Meditation gleich in der Nähe. Sie ist ein Ort großer Weisheit. Ich werde dort meditieren und meinen Geist öffnen - dann wird der Weg sich uns offenbaren.", sourceObjective = "Beschützt Aysa, während sie meditiert.", completion = "Euer Weg ist vorgezeichnet. Ihr werdet derjenige sein, der den Geist des Feuers neu entfacht und ihn in die Sicherheit des Tempels zurückführt.\n\nDas wird nicht das letzte Mal sein, dass Ihr mit Aysa zusammenarbeitet. Sie ist stark und weise. Ihr könnt ihr vertrauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29415] = { id = 29415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermisste Erbstücke", description = "Ich habe dem Kurier gesagt, dass er den Zeppelin nehmen soll, aber nein, er musste ja unbedingt ein Goblinschiff nehmen! Na ja, jetzt ist er verspätet und die wertvollen Erbstücke meiner Familie sind bei ihm.\n\nWenn Ihr helfen wollt, könntet Ihr vielleicht hinunter zu den Docks östlich von Orgrimmar gehen, Euch an Bord des Goblinschiffs begeben und nachsehen, was ihn aufhält?", sourceObjective = "Durchsucht die Kabine auf dem Schiff des angeheuerten Kuriers an den Docks östlich von Orgrimmar nach Hinweisen, was den Kurier aufhalten könnte.", completion = "Dieser Kurier wird sich wohl in naher Zukunft nicht mit seinem Arbeitgeber treffen und die Kiste, die er transportieren sollte, scheint verschwunden zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[29416] = { id = 29416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hehlerware", description = "Eine schnelle Überprüfung der Kabine ergibt keine Hinweise auf die Identität des Mörders oder seine Motive. Die Kiste, wegen der Ihr gekommen seid, ist verschwunden.\n\nWährend Ihr Euch umdreht, um die Kabine zu verlassen, bemerkt Ihr, dass sich am Boden etwas Kleines bewegt. Eine Gruppe Spinnen kriecht unter dem Bett des erschlagenen Kuriers hervor. Wo könnten sie hinwollen?", sourceObjective = "Folgt den Spinnen zu ihrem Ziel und befragt den Mann, den Ihr dort findet.", completion = "Senkt Eure Stimme und lasst nichts hierüber verlauten oder meine Karriere als Auktionator ist vorüber!", sourceObjectiveStatus = "unverified-source-field" }
quests[29417] = { id = 29417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg der Huojin", description = "Wir nennen diese teuflischen Affen, die über die Siedlung herfallen, Ho-zen. Normalerweise bleiben sie unter sich, aber sie spüren, dass irgendetwas Schlimmes bevorsteht, und fangen deshalb an, sich Vorräte zusammenzustehlen.\n\nFür ein Problem wie dieses gibt es nur eine Lösung - eine drastische Lösung. Diese Affen werden verschwinden, wenn wir sie dazu zwingen! Unsere Siedlung und damit diejenigen, die wir lieben, nicht zu verteidigen, wäre das wahre Verbrechen. Das ist der Weg der Huojin.", sourceObjective = "Tötet 8 Fe-Feng-Angreifer.", completion = "Ihr habt aber Mumm in den Knochen! Ich glaube, wir werden gut miteinander auskommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29418] = { id = 29418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Feuer entfachen", description = "Nun, da diese Angelegenheit erledigt ist, lasst uns also beginnen!\n\nHuo, der Geist des Feuers, hungert nach trockenen Hartriegelwurzelspänen. Hartriegel wächst im Wald südlich des Dorfes. Es sollte Euch ein Leichtes sein, ein paar Wurzeln zu sammeln.", sourceObjective = "Sammelt 5 trockene Hartriegelwurzeln.", progress = "Ich hoffe, dass Ihr Euch nicht zu fein seid, Euch die Hände schmutzig zu machen.", completion = "{name}! Ihr seid zurück - und wie ich sehe, habt Ihr die Wurzeln mitgebracht. Ihr seid kein Kerl, der lange fackelt, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[29419] = { id = 29419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Fahrer", description = "Mein Fahrer ist den Waldgeistern nachgerannt, kurz nachdem sie uns angegriffen hatten. Ich glaube nicht, dass sie ihm ernsthaft etwas zuleide tun werden, aber ich brauche ihn hier, damit er mir dabei helfen kann, dieses Durcheinander beim Karren in Ordnung zu bringen.\n\nEr hat sie in Richtung der Klippen im Norden gejagt. Wenn Ihr Euch dahin aufmacht, solltet Ihr ihn recht schnell finden können.", sourceObjective = "Rettet den Karrenfahrer.", completion = "Sehr liebenswürdig, {class}. Vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[29420] = { id = 29420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wächter des Geistes", description = "Ihr habt Euch so weit gut geschlagen, <mein Schüler/meine Schülerin>. Ihr seid im Besitz der benötigten Materialien, um Huo, den Geist des Feuers, neu zu entfachen.\n\nEr erwartet Euch in der Höhle im Südwesten, aber er wird von Meister Li Fei bewacht, dem Pandarenältesten, dem Ihr in der Höhle der Meditation begegnet seid. Begebt Euch mit den Opfergaben zu ihm. Beweist Euch und findet dann Huo.", sourceObjective = "Sprecht mit Meister Li Fei im Schrein des Inneren Lichts.", completion = "Im Leben geht es nicht darum, sich selbst zu finden. Es geht darum, sich selbst zu formen. Es liegt ein Weg vor Euch, aber Ihr selbst wählt die Prüfungen, denen Ihr gegenübersteht, und die Prüfungen, die Ihr bestehen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[29421] = { id = 29421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur die Würdigen dürfen passieren", description = "Es ist an der Zeit, dass Ihr mir gegenübertretet. Nun, da diese drei Feuer Euer wahres Potenzial erhellen, werden wir Gewissheit darüber erhalten, ob Eure entschlossene Seele wirklich würdig genug ist, um passieren zu dürfen.", sourceObjective = "Besiegt Meister Li Fei im Kampf.", completion = "Erinnert Euch stets daran, dass der überlegene Krieger durch seine Taten glänzen, aber seine Worte maßvoll wählen sollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[29422] = { id = 29422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Huo, der Geist des Feuers", description = "Ihr habt Euch als würdig erwiesen, {class}.\n\nHuo, der Geist des Feuers, ruht in der Kammer hinter uns. Lasst ihn sich an den Spänen, die Ihr gesammelt habt, nähren und benutzt den Wind, um seine Flammen anzufachen. Indem Ihr dies tut, werdet Ihr ihn Euch geneigt stimmen. Sobald er entfacht - und gewillt - ist, führt ihn zurück zum Tempel der Fünf Sonnenaufgänge, dem hoch aufragenden Gebäude im Zentrum der Insel.", sourceObjective = "Entfacht Huo, den Geist des Feuers, von Neuem.", completion = "<Durch das grelle Licht hindurch sieht es fast so aus, als würde Huo lächeln. Er scheint sich für Euch zu erwärmen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[29423] = { id = 29423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Passion von Shen-zin Su", description = "<Huo springt aufgeregt hin und her. Er ist offensichtlich bereit, Euch zu folgen.>\n\n<Meister Shang Xi hat Euch aufgetragen, Huo zu ihm in den Tempel der Fünf Sonnenaufgänge im Zentrum der Insel zu bringen. Ihr solltet Euch auf den Weg machen.>", sourceObjective = "Bringt den Geist des Feuers in den Tempel der Fünf Sonnenaufgänge.", completion = "{name}, Ihr habt Euch sehr gut geschlagen. Huo, der Geist des Feuers, ist hier. Die Flammen des Tempels sind neu entfacht. Ihr habt Eure letzte Herausforderung bestanden, und ohne große Mühe, wie es scheint.\n\nEs gibt auch einen sehr guten Grund dafür, Huo in den Tempel zu bringen. Es ist an der Zeit, dass ich Euch mehr über die bevorstehenden Ereignisse erzähle.", sourceObjectiveStatus = "unverified-source-field" }
quests[29424] = { id = 29424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegenstände von äußerster Wichtigkeit", description = "Honigblattstrolche haben meinen Karren umzingelt und die meisten der Übungsmaterialien gestohlen, die ich gerade zum Ausbildungsgelände bringen wollte. Sie waren schon immer Unruhestifter, aber sie sind noch nie so aggressiv gewesen. Ich weiß nicht, was mit ihnen passiert ist.\n\nIch bitte Euch, helft mir, die Materialien wiederzubeschaffen!", sourceObjective = "Beschafft 6 Übungsmaterialien von den Honigblattstrolchen wieder.", progress = "Ihr braucht Euch keine Sorgen darüber zu machen, den Waldgeistern etwas zuleide zu tun. Im Endeffekt sind sie einfach nur sehr quirlige Pflanzen - sie werden schon wieder aufsprießen.", completion = "Vielen Dank! Ihr seid ein ehrenhafter {class}. Eure Ausbildung trägt schon jetzt Früchte.", sourceObjectiveStatus = "unverified-source-field" }
